@layer base {
  html {
    font-family: "Manrope", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    color: rgb(var(--ink));
    background-color: rgb(var(--surface-soft));
    line-height: 1.45;
    scroll-behavior: smooth;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  body {
    min-height: 100%;
    background-color: rgb(var(--surface-soft));
    background-image:
      radial-gradient(circle at 15% -10%, rgba(236, 72, 153, 0.08), transparent 35%),
      radial-gradient(circle at 85% -20%, rgba(59, 130, 246, 0.08), transparent 38%),
      linear-gradient(180deg, rgba(248, 250, 252, 0.96), rgba(241, 245, 249, 0.92));
    background-attachment: fixed;
  }

  #root {
    min-height: 100%;
  }

  h1, h2, h3, .font-display {
    font-family: "Unbounded", "Manrope", system-ui, sans-serif;
    letter-spacing: -0.01em;
  }

  input:focus-visible,
  textarea:focus-visible,
  select:focus-visible,
  button:focus-visible {
    outline: none;
    border-color: rgba(168, 85, 247, 0.6);
    box-shadow: 0 0 0 3px rgba(168, 85, 247, 0.18);
  }

  button {
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease;
  }

  button,
  button *,
  [role='button'],
  [role='button'] * {
    -webkit-user-select: none;
    user-select: none;
  }

  button:not(:disabled):active {
    transform: translateY(1px);
  }

  * {
    scrollbar-width: thin;
    scrollbar-color: rgba(139, 92, 246, 0.55) rgba(241, 245, 249, 0.75);
  }

  *::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  *::-webkit-scrollbar-track {
    background: rgba(241, 245, 249, 0.7);
    border-radius: 999px;
  }

  *::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(167, 139, 250, 0.8), rgba(99, 102, 241, 0.75));
    border: 2px solid rgba(241, 245, 249, 0.9);
    border-radius: 999px;
  }

  *::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, rgba(147, 51, 234, 0.86), rgba(79, 70, 229, 0.82));
  }

  ::selection {
    background: rgba(168, 85, 247, 0.25);
  }
}

.yRemoteSelection {
  background-color: rgba(14, 165, 233, 0.35);
}

.yRemoteSelectionHead {
  border-left: 2px solid rgba(14, 165, 233, 0.9);
  border-top: 2px solid rgba(14, 165, 233, 0.9);
  border-bottom: 2px solid rgba(14, 165, 233, 0.9);
  box-sizing: border-box;
}

.collab-selection-overlay {
  scrollbar-width: none;
}

.collab-selection-overlay::-webkit-scrollbar {
  display: none;
}

.monaco-editor .collab-debug-active-line {
  background: linear-gradient(90deg, rgba(56, 189, 248, 0.18), rgba(56, 189, 248, 0.06));
  border-left: 2px solid rgba(56, 189, 248, 0.92);
  box-sizing: border-box;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph,
.monaco-editor .margin .collab-debug-active-glyph {
  position: relative !important;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph {
  transition: filter 0.2s ease;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph:hover {
  filter: brightness(1.06);
}

.monaco-editor .margin .collab-debug-active-glyph {
  animation: collabDebugPulse 1.35s ease-in-out infinite;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph::before,
.monaco-editor .margin .collab-debug-active-glyph::before {
  content: '';
  position: absolute;
  inset: 0;
  margin: auto;
  width: var(--collab-breakpoint-size, 12px);
  height: var(--collab-breakpoint-size, 12px);
  border-radius: 999px;
  box-sizing: border-box;
  pointer-events: none;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph::before {
  background: radial-gradient(circle at 30% 28%, #ffe4ea 0%, #fb7185 34%, #e11d48 70%, #9f1239 100%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    inset 0 0 0 1px rgba(136, 19, 55, 0.56),
    0 0 var(--collab-breakpoint-glow, 8px) rgba(225, 29, 72, 0.55),
    0 0 0 var(--collab-breakpoint-ring, 2px) rgba(244, 63, 94, 0.18);
}

.monaco-editor .margin .collab-debug-active-glyph::before {
  background: radial-gradient(circle at 30% 28%, #ecfeff 0%, #67e8f9 38%, #06b6d4 68%, #0369a1 100%);
  border: 1px solid rgba(240, 249, 255, 0.85);
  box-shadow:
    inset 0 0 0 1px rgba(14, 116, 144, 0.42),
    0 0 calc(var(--collab-breakpoint-glow, 8px) + 2px) rgba(14, 165, 233, 0.68),
    0 0 0 var(--collab-breakpoint-ring, 2px) rgba(56, 189, 248, 0.2);
}

@keyframes collabDebugPulse {
  0%, 100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.14);
  }
}

.monaco-editor .collab-debug-inline-hint {
  color: rgba(148, 163, 184, 0.88) !important;
  font-style: italic;
  font-size: 0.92em;
  letter-spacing: 0.01em;
  opacity: 0.95;
}

.monaco-editor .inline-inlay-hint,
.monaco-editor .inline-hints .inline-hint,
.monaco-editor .editorInlayHint {
  color: rgba(148, 163, 184, 0.92) !important;
  font-style: italic;
  background: transparent !important;
  border: none !important;
}

@layer components {
  .app-shell {
    background:
      radial-gradient(circle at -10% -20%, rgba(236, 72, 153, 0.11), transparent 38%),
      radial-gradient(circle at 18% 0%, rgba(59, 130, 246, 0.12), transparent 40%),
      radial-gradient(circle at 82% -8%, rgba(168, 85, 247, 0.13), transparent 48%),
      repeating-linear-gradient(-32deg, rgba(255, 255, 255, 0.35) 0 1px, transparent 1px 34px),
      linear-gradient(180deg, rgba(248, 250, 252, 0.93), rgba(241, 245, 249, 0.97));
  }

  .sidebar-shell {
    position: relative;
    isolation: isolate;
    background:
      radial-gradient(circle at 10% -8%, rgba(244, 114, 182, 0.18), transparent 38%),
      radial-gradient(circle at 96% -10%, rgba(59, 130, 246, 0.18), transparent 42%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(243, 239, 255, 0.97));
