  .sidebar-shell::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
      linear-gradient(115deg, rgba(255, 255, 255, 0.46), transparent 38%),
      repeating-linear-gradient(-24deg, rgba(139, 92, 246, 0.055) 0 1px, transparent 1px 20px);
