  background: linear-gradient(135deg, rgba(16, 185, 129, 0.96), rgba(37, 99, 235, 0.92));
  box-shadow:
    0 18px 38px rgba(14, 165, 233, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

@keyframes mockAnswerBurstStage {
  0% { opacity: 0; }
  12% { opacity: 1; }
  76% { opacity: 1; }
  100% { opacity: 0; }
}

@keyframes mockAnswerBurstWash {
  0% { opacity: 0; transform: scale(0.76) rotate(0deg); }
  18% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.18) rotate(54deg); }
}

@keyframes mockAnswerBurstRing {
  0% { opacity: 0; transform: scale(0.28); }
  18% { opacity: 0.95; }
  100% { opacity: 0; transform: scale(1.75); }
}

@keyframes mockAnswerBurstBadge {
  0% { opacity: 0; transform: translateY(18px) scale(0.72) rotate(-5deg); }
  22% { opacity: 1; transform: translateY(0) scale(1.12) rotate(2deg); }
  48% { transform: translateY(-2px) scale(0.98) rotate(0deg); }
  78% { opacity: 1; transform: translateY(-6px) scale(1); }
  100% { opacity: 0; transform: translateY(-26px) scale(0.9); }
}

@keyframes mockAnswerBurstParticle {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.35) rotate(0deg);
  }
  14% { opacity: 1; }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(0.18) rotate(var(--rot));
  }
}

.mock-artifact-drop {
  --artifact-main: #facc15;
  --artifact-hot: #22d3ee;
  --artifact-deep: #7c3aed;
  --artifact-ink: #ffffff;
  position: fixed;
  inset: 0;
  z-index: 1500;
  display: grid;
  place-items: center;
  overflow: hidden;
  pointer-events: none;
  isolation: isolate;
  background:
    radial-gradient(circle at 50% 47%, color-mix(in srgb, var(--artifact-main), transparent 78%), transparent 25%),
    radial-gradient(circle at 50% 47%, rgba(255, 255, 255, 0.12), transparent 11%),
    radial-gradient(circle at 18% 78%, color-mix(in srgb, var(--artifact-deep), transparent 76%), transparent 30%),
    linear-gradient(135deg, rgba(2, 6, 23, 0.84), rgba(15, 23, 42, 0.64));
  animation: mockArtifactDropStage 3.8s ease both;
}

.mock-artifact-drop--rank-s {
  --artifact-main: #fb7185;
  --artifact-hot: #f97316;
  --artifact-deep: #be123c;
}

.mock-artifact-drop--rank-a {
  --artifact-main: #c084fc;
  --artifact-hot: #22d3ee;
  --artifact-deep: #7c3aed;
}

.mock-artifact-drop--rank-b {
  --artifact-main: #38bdf8;
  --artifact-hot: #2dd4bf;
  --artifact-deep: #2563eb;
}

.mock-artifact-drop--rank-c {
  --artifact-main: #a3e635;
  --artifact-hot: #38bdf8;
  --artifact-deep: #475569;
}

.mock-artifact-drop::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 47%;
  width: 154vmax;
  height: 154vmax;
  z-index: -2;
  border-radius: 999px;
  background:
    radial-gradient(circle, transparent 0 18%, color-mix(in srgb, var(--artifact-main), transparent 72%) 19% 21%, transparent 23% 35%, color-mix(in srgb, var(--artifact-hot), transparent 78%) 36% 37%, transparent 39%),
    conic-gradient(
      from 0deg,
      transparent 0deg,
      color-mix(in srgb, var(--artifact-hot), transparent 74%) 22deg,
      transparent 52deg,
      color-mix(in srgb, var(--artifact-main), transparent 68%) 108deg,
      transparent 138deg,
      color-mix(in srgb, var(--artifact-deep), transparent 72%) 212deg,
      transparent 250deg,
      color-mix(in srgb, var(--artifact-hot), transparent 76%) 318deg,
      transparent 360deg
    );
  filter: blur(1px);
  mix-blend-mode: screen;
  opacity: 0;
  animation: mockArtifactDropWash 3.4s cubic-bezier(0.16, 0.92, 0.24, 1) both;
}

.mock-artifact-drop::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(circle at 50% 47%, transparent 0 14%, rgba(255, 255, 255, 0.18) 14.4% 14.8%, transparent 15.4% 28%, color-mix(in srgb, var(--artifact-main), transparent 82%) 28.4% 29%, transparent 30%),
    radial-gradient(circle at 50% 47%, color-mix(in srgb, var(--artifact-hot), transparent 86%), transparent 39%),
    radial-gradient(circle at 64% 28%, rgba(255, 255, 255, 0.12), transparent 8%),
    radial-gradient(circle at 28% 66%, color-mix(in srgb, var(--artifact-main), transparent 84%), transparent 10%);
  mix-blend-mode: screen;
  opacity: 0;
  animation: mockArtifactDropBeams 3.2s ease both;
}

.mock-artifact-drop__orbit {
  position: absolute;
  left: 50%;
  top: 47%;
  border: 1px solid color-mix(in srgb, var(--artifact-main), transparent 34%);
  border-radius: 999px;
  box-shadow:
    0 0 34px color-mix(in srgb, var(--artifact-main), transparent 38%),
    inset 0 0 42px color-mix(in srgb, var(--artifact-hot), transparent 76%);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.3);
}

.mock-artifact-drop__orbit--outer {
  width: min(74vmin, 42rem);
  aspect-ratio: 1;
  animation: mockArtifactDropOrbit 2.7s cubic-bezier(0.18, 0.9, 0.2, 1) 0.08s both;
}

.mock-artifact-drop__orbit--inner {
  width: min(48vmin, 28rem);
  aspect-ratio: 1;
  border-color: color-mix(in srgb, var(--artifact-hot), transparent 34%);
  animation: mockArtifactDropOrbit 2.45s cubic-bezier(0.18, 0.9, 0.2, 1) 0.18s both reverse;
}

.mock-artifact-drop__card {
  position: relative;
  z-index: 3;
  display: grid;
  width: min(88vw, 28rem);
  justify-items: center;
  gap: 0.74rem;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: clamp(0.65rem, 2vmin, 1rem);
  color: #ffffff;
  text-align: center;
  box-shadow: none;
  transform-origin: center;
  animation: mockArtifactDropCard 3.15s cubic-bezier(0.16, 0.92, 0.24, 1) both;
}

.mock-artifact-drop__card::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 46%;
  width: min(66vmin, 31rem);
  aspect-ratio: 1;
  z-index: -1;
  border: 1px solid color-mix(in srgb, var(--artifact-main), transparent 58%);
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 42%, rgba(255, 255, 255, 0.2), transparent 18%),
    radial-gradient(circle, color-mix(in srgb, var(--artifact-main), transparent 70%), transparent 54%),
    radial-gradient(circle, color-mix(in srgb, var(--artifact-deep), transparent 78%), transparent 70%);
  box-shadow:
    0 0 80px color-mix(in srgb, var(--artifact-main), transparent 50%),
    inset 0 0 54px rgba(255, 255, 255, 0.1);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.72);
  animation: mockArtifactDropHalo 2.9s cubic-bezier(0.16, 0.92, 0.24, 1) 0.04s both;
}

.mock-artifact-drop__kicker,
.mock-artifact-drop__rank {
  border-radius: 999px;
  background: color-mix(in srgb, var(--artifact-main), transparent 78%);
  padding: 0.28rem 0.68rem;
  color: color-mix(in srgb, var(--artifact-main), #ffffff 54%);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: uppercase;
}

.mock-artifact-drop__image-shell {
  display: grid;
  width: clamp(9.5rem, 28vmin, 14.5rem);
  aspect-ratio: 1;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--artifact-hot), transparent 34%);
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 42%, rgba(255, 255, 255, 0.38), transparent 29%),
    radial-gradient(circle, color-mix(in srgb, var(--artifact-main), transparent 66%), transparent 63%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.04));
  color: color-mix(in srgb, var(--artifact-main), #ffffff 20%);
  box-shadow:
    0 0 54px color-mix(in srgb, var(--artifact-main), transparent 34%),
    0 0 110px color-mix(in srgb, var(--artifact-hot), transparent 68%),
    inset 0 0 34px rgba(255, 255, 255, 0.1);
  animation: mockArtifactDropRelic 2.6s cubic-bezier(0.18, 0.92, 0.18, 1) 0.18s both;
}

.mock-artifact-drop__image {
  display: block;
  width: 86%;
  height: 86%;
  object-fit: contain;
  filter:
    drop-shadow(0 22px 28px rgba(0, 0, 0, 0.34))
    drop-shadow(0 0 24px color-mix(in srgb, var(--artifact-main), transparent 20%));
}

.mock-artifact-drop__name {
  max-width: 100%;
  color: #ffffff;
  font-size: clamp(1.55rem, 5vmin, 2.85rem);
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1.02;
  overflow-wrap: anywhere;
  text-shadow:
    0 0 18px color-mix(in srgb, var(--artifact-main), transparent 28%),
    0 3px 18px rgba(0, 0, 0, 0.36);
}

.mock-artifact-drop__shard {
  position: absolute;
  left: 50%;
  top: 47%;
  z-index: 2;
  width: var(--size, 0.48rem);
  height: calc(var(--size, 0.48rem) * 1.25);
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 28%, #ffffff, transparent 32%),
    linear-gradient(180deg, var(--artifact-hot), var(--artifact-main));
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.34),
    0 0 22px color-mix(in srgb, var(--artifact-main), transparent 22%);
  transform: translate(-50%, -50%) scale(0.2) rotate(var(--angle));
  animation: mockArtifactDropShard 1.8s cubic-bezier(0.12, 0.72, 0.18, 1) both;
  animation-delay: var(--delay, 0ms);
}

.mock-chest-overlay {
  position: fixed;
  inset: 0;
  z-index: 1800;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 42%, rgba(250, 204, 21, 0.2), transparent 24rem),
    radial-gradient(circle at 18% 22%, rgba(34, 211, 238, 0.16), transparent 19rem),
    radial-gradient(circle at 82% 18%, rgba(168, 85, 247, 0.2), transparent 21rem),
    linear-gradient(180deg, rgba(2, 6, 23, 0.92), rgba(10, 15, 31, 0.98));
  color: white;
  isolation: isolate;
}

.mock-chest-overlay__aura {
  position: absolute;
  inset: -60vmax;
  background:
    conic-gradient(from 20deg, transparent 0 10%, rgba(250, 204, 21, 0.2) 14% 17%, transparent 23% 32%, rgba(34, 211, 238, 0.15) 36% 40%, transparent 47% 57%, rgba(168, 85, 247, 0.18) 61% 66%, transparent 72%),
    radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.1), transparent 36%);
  filter: blur(1.4rem);
  mask-image: radial-gradient(circle at 50% 50%, #000 0 46%, rgba(0, 0, 0, 0.82) 58%, transparent 78%);
  opacity: 0.82;
  transform-origin: 50% 50%;
  animation: mockChestAuraSpin 10s linear infinite;
}

.mock-chest-overlay__stars {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.mock-chest-overlay__stars span {
  position: absolute;
  left: calc(8% + (var(--star-index) * 5.2%));
  top: calc(12% + ((var(--star-index) % 7) * 10%));
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 0 18px rgba(255, 255, 255, 0.66);
  opacity: 0.58;
  animation: mockChestStarTwinkle 2.6s ease-in-out infinite;
  animation-delay: calc((var(--star-index) % 6) * 130ms);
}

.mock-chest-overlay__close {
  position: absolute;
  right: 1rem;
  top: 1rem;
  z-index: 5;
  display: inline-flex;
  width: 2.5rem;
  height: 2.5rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(15, 23, 42, 0.54);
  color: rgba(255, 255, 255, 0.8);
  transition: transform 0.16s ease, background 0.16s ease, color 0.16s ease;
}

.mock-chest-overlay__close:hover {
  transform: translateY(-1px);
  background: rgba(30, 41, 59, 0.82);
  color: white;
}

.mock-chest-overlay--closing {
  pointer-events: none;
  animation: mockChestOverlayExit 1.18s cubic-bezier(0.18, 0.78, 0.22, 1) both;
}

.mock-chest-overlay--closing .mock-chest-overlay__aura {
  animation: mockChestAuraExit 0.76s ease both;
}

.mock-chest-overlay--closing .mock-chest-overlay__stars span {
  animation: mockChestStarExit 0.46s ease both;
  animation-delay: calc((var(--star-index) % 8) * 18ms);
}

.mock-chest-overlay--closing .mock-chest-overlay__close,
.mock-chest-overlay--closing .mock-chest-stage__kicker,
.mock-chest-overlay--closing .mock-chest-stage__copy,
.mock-chest-overlay--closing .mock-chest-coin-prize {
  animation: mockChestUiExit 0.42s ease both;
}

.mock-chest-overlay--closing .mock-chest {
  animation: mockChestLeave 0.76s cubic-bezier(0.18, 0.78, 0.2, 1) both !important;
}

.mock-chest-overlay--closing .mock-chest__asset-glow {
  animation: mockChestAssetGlowExit 0.62s ease both !important;
}

.mock-chest-overlay--closing .mock-chest__shine {
  animation: mockChestGlowExit 0.62s ease both !important;
}

.mock-chest-overlay--closing .mock-chest-artifact {
  animation: mockChestRewardExit 0.48s cubic-bezier(0.18, 0.78, 0.2, 1) both !important;
}

.mock-chest-overlay--closing .mock-chest-artifact.is-visible {
  animation: mockChestArtifactFlyToCollection 1.08s cubic-bezier(0.18, 0.86, 0.2, 1) both !important;
  animation-delay: var(--artifact-exit-delay, 0ms) !important;
}

.mock-chest-overlay--closing .mock-chest-coins {
  animation: mockChestUiExit 0.34s ease both;
}

.mock-chest-stage {
  position: relative;
  z-index: 2;
  display: flex;
  width: min(92vw, 54rem);
  min-height: min(88vh, 44rem);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1.25rem;
  perspective: 58rem;
  text-align: center;
}

.mock-chest-stage--clickable {
  cursor: pointer;
}

.mock-chest-stage__kicker {
  position: absolute;
  top: 0.8rem;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border-radius: 999px;
  border: 1px solid rgba(250, 204, 21, 0.28);
  background: rgba(15, 23, 42, 0.5);
  padding: 0.55rem 0.9rem;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(254, 240, 138, 0.96);
  box-shadow: 0 18px 42px rgba(2, 6, 23, 0.28);
}

.mock-chest {
  position: relative;
  width: min(23.5rem, 74vw);
  height: min(17.2rem, 55vw);
  padding: 0;
  border: 0;
  appearance: none;
  background: transparent;
  perspective: 42rem;
  transform-style: preserve-3d;
  filter: drop-shadow(0 2.2rem 2.5rem rgba(0, 0, 0, 0.44));
  transition: filter 0.42s cubic-bezier(0.16, 0.84, 0.22, 1);
  will-change: filter;
  animation: mockChestArrive 0.92s cubic-bezier(0.14, 0.88, 0.24, 1.12) both, mockChestFloat 3.2s ease-in-out 0.92s infinite;
}

.mock-chest--clickable {
  cursor: pointer;
}

.mock-chest--clickable:hover {
  filter:
    drop-shadow(0 2.4rem 2.7rem rgba(0, 0, 0, 0.46))
    drop-shadow(0 0 2.4rem rgba(250, 204, 21, 0.34));
}

.mock-chest.mock-chest--image {
  width: min(30rem, 82vw);
  height: min(24rem, 72vw);
  margin: -1.1rem 0 -2.4rem;
  overflow: visible;
}

.mock-chest__asset-shell {
  pointer-events: none;
  position: absolute;
  inset: -3%;
  display: block;
  transform-origin: 50% 78%;
  transform-style: preserve-3d;
  will-change: transform, filter;
  z-index: 3;
}

.mock-chest__asset {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  transform-origin: 50% 62%;
  user-select: none;
  filter:
    drop-shadow(0 2rem 2.2rem rgba(0, 0, 0, 0.38))
    drop-shadow(0 0 2.2rem rgba(250, 204, 21, 0.16));
}

.mock-chest__asset--closed {
  opacity: 1;
  transform: translateY(0.2rem) scale(0.86);
}

.mock-chest__asset--open {
  opacity: 0;
  transform: translateY(1.7rem) scale(0.66) rotateX(10deg);
  filter:
    drop-shadow(0 2.2rem 2.6rem rgba(0, 0, 0, 0.42))
    drop-shadow(0 0 3rem rgba(250, 204, 21, 0.28));
}

.mock-chest--opened .mock-chest__asset--closed {
  animation: mockChestClosedAssetExit 0.48s cubic-bezier(0.16, 0.86, 0.24, 1) both;
}

.mock-chest--opened .mock-chest__asset--open {
  animation: mockChestOpenAssetReveal 0.86s cubic-bezier(0.14, 0.92, 0.18, 1.04) 0.12s both;
}

.mock-chest__asset-glow {
  position: absolute;
  left: 50%;
  top: 38%;
  width: 72%;
  height: 42%;
  border-radius: 999px;
  background:
    radial-gradient(ellipse at 50% 54%, rgba(255, 250, 205, 0.9), rgba(250, 204, 21, 0.36) 28%, rgba(245, 158, 11, 0.14) 48%, transparent 72%),
    radial-gradient(ellipse at 38% 46%, rgba(34, 211, 238, 0.18), transparent 42%);
  filter: blur(0.35rem);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.62);
  z-index: -1;
}

.mock-chest--opened .mock-chest__asset-glow {
  animation: mockChestAssetGlow 1.35s cubic-bezier(0.16, 0.86, 0.2, 1) 0.18s both, mockChestAssetGlowPulse 2.4s ease-in-out 1.45s infinite;
}

.mock-chest__asset-spark {
  position: absolute;
  width: 0.46rem;
  height: 0.46rem;
  border-radius: 999px;
  background: #fff8c9;
  box-shadow:
    0 0 0.7rem rgba(255, 248, 201, 0.96),
    0 0 1.6rem rgba(250, 204, 21, 0.58);
  opacity: 0;
  z-index: 5;
}

.mock-chest__asset-spark--one {
  left: 33%;
  top: 28%;
}

.mock-chest__asset-spark--two {
  left: 55%;
  top: 22%;
}

.mock-chest__asset-spark--three {
  left: 69%;
  top: 36%;
}

.mock-chest--opened .mock-chest__asset-spark {
  animation: mockChestAssetSpark 1.55s ease-in-out infinite;
}

.mock-chest--opened .mock-chest__asset-spark--one {
  animation-delay: 0.22s;
}

.mock-chest--opened .mock-chest__asset-spark--two {
  animation-delay: 0.5s;
}

.mock-chest--opened .mock-chest__asset-spark--three {
  animation-delay: 0.78s;
}

.mock-chest--press-odd .mock-chest__asset-shell {
  animation: mockChestPressOdd 0.38s cubic-bezier(0.16, 0.82, 0.18, 1.08) both;
}

.mock-chest--press-even .mock-chest__asset-shell {
  animation: mockChestPressEven 0.38s cubic-bezier(0.16, 0.82, 0.18, 1.08) both;
}

.mock-chest--press-odd .mock-chest__base {
  animation: mockChestPressShadowOdd 0.38s cubic-bezier(0.16, 0.82, 0.18, 1.08) both;
}

.mock-chest--press-even .mock-chest__base {
  animation: mockChestPressShadowEven 0.38s cubic-bezier(0.16, 0.82, 0.18, 1.08) both;
}

.mock-chest__shine {
  position: absolute;
  inset: -22%;
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 46%, rgba(255, 255, 255, 0.34), transparent 10%),
    radial-gradient(circle at 50% 54%, rgba(250, 204, 21, 0.24), transparent 45%);
  opacity: 0.72;
  animation: mockChestPulse 2.4s ease-in-out infinite;
}

.mock-chest__lid,
.mock-chest__body,
.mock-chest__base {
  position: absolute;
  left: 50%;
  box-sizing: border-box;
  transform: translateX(-50%);
  overflow: hidden;
}

.mock-chest__lid {
  top: 14%;
  width: 84%;
  height: 32%;
  border-radius: 2.8rem 2.8rem 0.78rem 0.78rem / 2.05rem 2.05rem 0.78rem 0.78rem;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.26), transparent 13% 83%, rgba(91, 33, 10, 0.2)),
    repeating-linear-gradient(90deg, transparent 0 22%, rgba(92, 38, 8, 0.22) 22.5% 23.5%, transparent 24% 48%, rgba(255, 248, 190, 0.18) 48.5% 49.2%, transparent 49.8% 73%, rgba(92, 38, 8, 0.2) 73.5% 74.5%, transparent 75% 100%),
    radial-gradient(ellipse at 50% -22%, rgba(255, 249, 196, 0.92), rgba(255, 249, 196, 0.12) 32%, transparent 33%),
    linear-gradient(180deg, #ffd86a 0%, #eba22a 42%, #a95317 100%);
  border: 0.28rem solid rgba(254, 226, 95, 0.92);
  box-shadow:
    inset 0 0.65rem 0.75rem rgba(255, 255, 255, 0.32),
    inset 0 -0.75rem 0.95rem rgba(83, 38, 8, 0.48),
    0 1rem 1.4rem rgba(0, 0, 0, 0.3);
  backface-visibility: visible;
  transform-origin: 50% 96%;
  transform-style: preserve-3d;
  will-change: transform;
  z-index: 3;
}

.mock-chest__lid::before {
  content: '';
  position: absolute;
  inset: 0.58rem 0.76rem 0.72rem;
  border-radius: 2rem 2rem 0.46rem 0.46rem / 1.38rem 1.38rem 0.46rem 0.46rem;
  background:
    radial-gradient(ellipse at 22% 40%, rgba(255, 245, 157, 0.42), transparent 18%),
    radial-gradient(ellipse at 75% 56%, rgba(92, 38, 8, 0.2), transparent 24%),
    repeating-linear-gradient(90deg, transparent 0 31%, rgba(92, 38, 8, 0.24) 31.5% 32.5%, transparent 33% 65%, rgba(255, 248, 190, 0.16) 65.5% 66%, transparent 66.5% 100%);
  opacity: 0.9;
  pointer-events: none;
}

.mock-chest__lid::after {
  content: '';
  position: absolute;
  right: 0.42rem;
  bottom: 0.3rem;
  left: 0.42rem;
