.notes-save-mode-option {
  position: relative;
  isolation: isolate;
  display: flex;
  min-height: 6.4rem;
  cursor: pointer;
  gap: 0.75rem;
  overflow: hidden;
  border: 1px solid rgba(203, 213, 225, 0.92);
  border-radius: 1.15rem;
  background:
    radial-gradient(circle at 12% 0%, rgba(255, 255, 255, 0.95), transparent 34%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.88));
  box-shadow:
    0 12px 26px rgba(15, 23, 42, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.86);
  padding: 0.85rem;
  transition:
    border-color 0.2s ease,
    box-shadow 0.24s ease,
    transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1),
    background 0.24s ease;
}

.notes-save-mode-option::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  opacity: 0;
  background:
    radial-gradient(circle at 15% 8%, rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.16), transparent 44%),
    linear-gradient(135deg, rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.1), transparent 62%);
  transition: opacity 0.22s ease;
}

.notes-save-mode-option:hover {
  transform: translateY(-1px);
  border-color: rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.34);
  box-shadow:
    0 16px 34px rgba(15, 23, 42, 0.09),
    0 0 0 4px rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.notes-save-mode-option:hover::before,
.notes-save-mode-option.is-active::before {
  opacity: 1;
}

.notes-save-mode-option.is-active {
  border-color: rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.52);
  background:
    radial-gradient(circle at 14% 0%, rgba(255, 255, 255, 0.96), transparent 34%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.1));
  box-shadow:
    0 18px 40px rgba(15, 23, 42, 0.1),
    0 0 0 4px rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.notes-save-mode-option--full {
  --notes-save-mode-rgb: 79, 70, 229;
}

.notes-save-mode-option--code {
  --notes-save-mode-rgb: 14, 165, 233;
}

.notes-save-mode-option--cheatsheet {
  --notes-save-mode-rgb: 147, 51, 234;
}

.notes-save-mode-option__icon {
  position: relative;
  display: inline-flex;
  width: 2.55rem;
  height: 2.55rem;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 0.95rem;
  background:
    radial-gradient(circle at 30% 20%, rgba(255, 255, 255, 0.9), transparent 38%),
    linear-gradient(145deg, rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.96), rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.72));
  color: #ffffff;
  box-shadow:
    0 10px 22px rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.34);
}

.notes-save-mode-option__icon span {
  position: absolute;
  right: 0.36rem;
  top: 0.36rem;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: 0 0 14px rgba(255, 255, 255, 0.72);
}

.notes-save-mode-option__body {
  min-width: 0;
}

.notes-save-mode-option__top {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.42rem;
}

.notes-save-mode-option__title {
  color: #0f172a;
  font-size: 0.9rem;
  font-weight: 850;
}

.notes-save-mode-option__badge {
  border: 1px solid rgba(var(--notes-save-mode-rgb, 99, 102, 241), 0.18);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  color: rgb(var(--notes-save-mode-rgb, 99, 102, 241));
  padding: 0.12rem 0.48rem;
  font-size: 0.68rem;
  font-weight: 800;
}

.notes-save-mode-option__description {
