.schedule-skill-tree__panel {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.schedule-skill-tree__panel--collapsed {
  border-radius: 18px !important;
}

.schedule-skill-tree__panel--collapsed::before,
.schedule-skill-tree__panel--collapsed::after {
  opacity: 0.14;
}

.schedule-skill-tree__panel::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 14% -10%, rgba(56, 189, 248, 0.08), transparent 28%),
    radial-gradient(circle at 86% -14%, rgba(99, 102, 241, 0.06), transparent 32%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.18), transparent 30%);
}

.schedule-skill-tree__panel::after {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.16), transparent 24%);
  opacity: 0.5;
}

.schedule-skill-tree__header-icon {
  backdrop-filter: blur(18px) saturate(136%);
  -webkit-backdrop-filter: blur(18px) saturate(136%);
}

.schedule-skill-tree__collapse-chip {
  backdrop-filter: blur(10px) saturate(108%);
  -webkit-backdrop-filter: blur(10px) saturate(108%);
}

.schedule-skill-tree__collapse-chip-icon {
  box-shadow: none;
}

.schedule-skill-tree__summary {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  backdrop-filter: blur(14px) saturate(124%);
  -webkit-backdrop-filter: blur(14px) saturate(124%);
}

.schedule-skill-tree__summary::before {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.26), transparent 34%);
  opacity: 0.56;
}

.schedule-skill-tree__summary-track {
  position: relative;
  box-shadow: inset 0 1px 2px rgba(148, 163, 184, 0.16);
}

.schedule-skill-tree__focus-banner {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.schedule-skill-tree__focus-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.18), transparent 36%);
  opacity: 0.52;
}

.schedule-skill-tree__canvas {
  position: relative;
  overflow: hidden;
  box-shadow:
    0 24px 48px rgba(15, 23, 42, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.62);
}

.schedule-skill-tree__canvas::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background:
    radial-gradient(circle at 20% -10%, rgba(56, 189, 248, 0.08), transparent 28%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.14), transparent 36%);
}

.schedule-skill-tree__canvas::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent 18%);
  opacity: 0.36;
}

.schedule-skill-tree__canvas-orb {
  position: absolute;
  border-radius: 999px;
  pointer-events: none;
  filter: blur(40px);
