  height: 74px;
  border-radius: 9999px;
  display: grid;
  place-items: center;
  font-size: 2rem;
  font-weight: 900;
  color: #fff;
  background: linear-gradient(145deg, #c084fc 0%, #a855f7 44%, #7c3aed 100%);
