  box-shadow:
    inset 0 2px 0 rgba(255,255,255,0.58),
    inset 0 -5px 8px rgba(67, 17, 128, 0.4),
    0 10px 24px rgba(76, 29, 149, 0.35);
}
.levelup-badge-glow {
  position: absolute;
  inset: 6px;
  border-radius: 9999px;
  background: radial-gradient(circle, rgba(217, 70, 239, 0.8) 0%, rgba(139, 92, 246, 0.34) 50%, rgba(139, 92, 246, 0) 78%);
  filter: blur(5px);
  z-index: 1;
  animation: levelUpGlowPulse 1.6s ease-in-out infinite;
}
.levelup-rings,
.levelup-rays {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.levelup-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 180px;
  height: 180px;
  border-radius: 9999px;
  border: 2px solid rgba(196, 181, 253, 0.72);
  animation: levelUpRingExpand 1.8s ease-out infinite;
}
.levelup-ring--a { animation-delay: 0s; }
.levelup-ring--b { animation-delay: 0.35s; width: 220px; height: 220px; }
.levelup-ring--c { animation-delay: 0.7s; width: 270px; height: 270px; }
.levelup-ray {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 360px;
  height: 360px;
  border-radius: 9999px;
  transform: translate(-50%, -50%);
  background: conic-gradient(
    from 0deg,
    rgba(244, 114, 182, 0) 0deg,
    rgba(192, 132, 252, 0.24) 42deg,
    rgba(167, 139, 250, 0) 96deg,
    rgba(217, 70, 239, 0.3) 138deg,
    rgba(139, 92, 246, 0) 210deg,
    rgba(192, 132, 252, 0.18) 300deg,
    rgba(244, 114, 182, 0) 360deg
  );
  filter: blur(2px);
  animation: levelUpRaySweep 2.6s ease-in-out infinite;
}
.levelup-ray--a { --ray-rotate: 0deg; }
.levelup-ray--b { --ray-rotate: 58deg; animation-delay: 0.24s; }
.levelup-ray--c { --ray-rotate: 116deg; animation-delay: 0.52s; }
.levelup-particle {
  position: absolute;
  top: calc(50% + 18px);
  border-radius: 9999px;
  background: radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(216, 180, 254, 0.95) 45%, rgba(147, 51, 234, 0.85) 100%);
  box-shadow: 0 0 10px rgba(192, 132, 252, 0.85);
  animation-name: levelUpParticleBurst;
  animation-duration: var(--levelup-duration, 1.8s);
  animation-delay: var(--levelup-delay, 0s);
  animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
  animation-iteration-count: infinite;
  animation-fill-mode: both;
}
