.artifact-altar-stage {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: 22rem;
  border-radius: 1.75rem;
  border: 1px solid rgba(251, 191, 36, 0.38);
  padding: 1.4rem 1.2rem 1.3rem;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.98), rgba(255, 248, 220, 0.92) 34%, rgba(120, 53, 15, 0.08) 100%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.7), rgba(255, 251, 235, 0.9));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 22px 38px rgba(217, 119, 6, 0.14);
}

.artifact-altar-stage__backdrop,
.artifact-altar-stage__aurora,
.artifact-altar-stage__halo,
.artifact-altar-stage__orbit,
.artifact-altar-stage__rune-ring,
.artifact-altar-stage__particle,
.artifact-altar-stage__pedestal,
.artifact-altar-stage__focus,
.artifact-altar-stage__content {
  position: absolute;
}

.artifact-altar-stage__backdrop {
  inset: 0;
  background:
    radial-gradient(circle at 50% 18%, rgba(255, 255, 255, 0.94) 0%, var(--artifact-altar-accent-soft, rgba(245, 158, 11, 0.18)) 36%, rgba(255, 255, 255, 0) 74%),
    radial-gradient(circle at 50% 84%, rgba(251, 191, 36, 0.08), rgba(120, 53, 15, 0) 56%);
  animation: artifactAltarBackdropPulse 6s ease-in-out infinite;
}

.artifact-altar-stage__aurora {
  border-radius: 999px;
  filter: blur(28px);
  background: radial-gradient(circle, var(--artifact-altar-accent-mid, rgba(245, 158, 11, 0.34)) 0%, rgba(255, 255, 255, 0) 72%);
  animation: artifactAltarAuroraDrift 8.5s ease-in-out infinite;
}

.artifact-altar-stage__aurora--left {
  width: 9rem;
  height: 9rem;
  left: -1.8rem;
  top: 2.8rem;
}

.artifact-altar-stage__aurora--right {
  width: 10rem;
  height: 10rem;
  right: -2rem;
  top: 1.2rem;
  animation-duration: 9.6s;
  animation-direction: reverse;
}

.artifact-altar-stage__halo,
.artifact-altar-stage__orbit,
.artifact-altar-stage__rune-ring {
  left: 50%;
  top: 46%;
  border-radius: 999px;
  transform: translate(-50%, -50%);
}

.artifact-altar-stage__halo {
  background: radial-gradient(circle, rgba(255, 255, 255, 0.08) 0%, var(--artifact-altar-accent-soft, rgba(245, 158, 11, 0.18)) 52%, rgba(255, 255, 255, 0) 72%);
  animation: artifactAltarHaloPulse 4.4s ease-in-out infinite;
}

.artifact-altar-stage__halo--outer {
  width: clamp(14rem, 42vw, 18rem);
  height: clamp(14rem, 42vw, 18rem);
}

.artifact-altar-stage__halo--inner {
  width: clamp(10rem, 28vw, 13rem);
  height: clamp(10rem, 28vw, 13rem);
  animation-duration: 3.6s;
  animation-delay: 120ms;
}

.artifact-altar-stage__orbit {
  width: clamp(13rem, 40vw, 17rem);
  height: clamp(13rem, 40vw, 17rem);
  border: 1px solid rgba(255, 255, 255, 0.52);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.22),
    0 0 0 1px var(--artifact-altar-accent-soft, rgba(245, 158, 11, 0.18));
}

.artifact-altar-stage__orbit::before,
.artifact-altar-stage__orbit::after {
  content: "";
  position: absolute;
  left: 50%;
  top: -0.45rem;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.98) 0%, var(--artifact-altar-accent-strong, rgba(245, 158, 11, 0.54)) 60%, rgba(255, 255, 255, 0) 100%);
  transform: translateX(-50%);
}

.artifact-altar-stage__orbit::after {
  top: auto;
  bottom: -0.45rem;
}

.artifact-altar-stage__orbit--outer {
  animation: artifactAltarOrbitSpin 8.5s linear infinite;
}

.artifact-altar-stage__orbit--inner {
  width: clamp(10.5rem, 32vw, 13rem);
  height: clamp(10.5rem, 32vw, 13rem);
  border-style: dashed;
  opacity: 0.72;
  animation: artifactAltarOrbitSpinReverse 6.2s linear infinite;
}

.artifact-altar-stage__rune-ring {
  width: clamp(15rem, 46vw, 19rem);
  height: clamp(15rem, 46vw, 19rem);
  border: 1px dashed var(--artifact-altar-accent-soft, rgba(245, 158, 11, 0.18));
  opacity: 0.56;
  animation: artifactAltarRuneSpin 12s linear infinite;
}

.artifact-altar-stage__particle {
  left: 50%;
  top: 46%;
  width: var(--particle-size, 12px);
  height: var(--particle-size, 12px);
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.98) 0%, var(--artifact-altar-accent-mid, rgba(245, 158, 11, 0.34)) 56%, rgba(255, 255, 255, 0) 100%);
  opacity: 0;
}

.artifact-altar-stage__pedestal {
  display: none;
  left: 50%;
  bottom: 2.4rem;
  width: clamp(12rem, 40vw, 16rem);
  height: 3.8rem;
  transform: translateX(-50%);
  border-radius: 999px;
  background:
    linear-gradient(180deg, rgba(255, 251, 235, 0.98), rgba(254, 243, 199, 0.78)),
    linear-gradient(90deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.42));
  border: 1px solid rgba(251, 191, 36, 0.34);
  animation: artifactAltarPedestalGlow 3.8s ease-in-out infinite;
}

.artifact-altar-stage__pedestal-core {
  display: none;
}

.artifact-altar-stage__focus {
  left: 50%;
  top: 46%;
  width: clamp(10.5rem, 30vw, 13rem);
  height: clamp(10.5rem, 30vw, 13rem);
  transform: translate(-50%, -50%);
  border-radius: 999px;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.98) 0%, rgba(255, 255, 255, 0.84) 30%, var(--artifact-altar-accent-soft, rgba(245, 158, 11, 0.18)) 68%, rgba(255, 255, 255, 0) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    0 0 44px var(--artifact-altar-core-shadow, rgba(245, 158, 11, 0.24));
  overflow: hidden;
  transition: filter 680ms ease, box-shadow 680ms ease;
  animation: artifactAltarFocusFloat 4.8s ease-in-out infinite;
}

.artifact-altar-stage__conceal {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 94%;
  height: 94%;
  transform: translate(-50%, -50%) scale(0.92);
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 0.98) 26%, var(--artifact-altar-accent-mid, rgba(245, 158, 11, 0.34)) 56%, rgba(255, 255, 255, 0) 100%);
