.student-message-row,
.teacher-chat-message-row {
  position: relative;
  scroll-margin-block: 7rem;
}

.student-message-row--highlighted > *,
.teacher-chat-message-row--highlighted > *,
.chat-message-target--active > * {
  position: relative;
  z-index: 1;
}

.student-message-row--highlighted::before,
.teacher-chat-message-row--highlighted::before,
.chat-message-target--active::before {
  content: '';
  position: absolute;
  inset: -0.42rem -0.7rem;
  z-index: 0;
  border-radius: 1.45rem;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(34, 211, 238, 0), rgba(34, 211, 238, 0.18) 18%, rgba(168, 85, 247, 0.16) 52%, rgba(45, 212, 191, 0.14) 82%, rgba(34, 211, 238, 0));
  opacity: 0;
  transform: scaleX(0.96);
  animation: chat-message-target-row-wash 2.75s cubic-bezier(0.22, 0.72, 0.2, 1) both;
}

.student-message-row--highlighted .student-message-bubble,
.teacher-chat-message-row--highlighted .teacher-chat-bubble,
.chat-message-target--active .student-message-bubble,
.chat-message-target--active .teacher-chat-bubble {
  position: relative;
  z-index: 1;
  isolation: isolate;
  animation: chat-message-target-settle 2.75s cubic-bezier(0.22, 0.72, 0.2, 1) both;
}

.student-message-row--highlighted .student-message-bubble::after,
.teacher-chat-message-row--highlighted .teacher-chat-bubble::after,
.chat-message-target--active .student-message-bubble::after,
.chat-message-target--active .teacher-chat-bubble::after {
  content: '';
  position: absolute;
  inset: -1px;
  z-index: 2;
  border-radius: inherit;
  pointer-events: none;
  background:
    radial-gradient(circle at 12% 18%, rgba(255, 255, 255, 0.28), transparent 34%),
    linear-gradient(120deg, rgba(125, 211, 252, 0.34), rgba(168, 85, 247, 0.22) 52%, rgba(45, 212, 191, 0.2));
  box-shadow:
    inset 0 0 0 1px rgba(226, 232, 240, 0.2),
    inset 0 0 0 2px rgba(125, 211, 252, 0.26);
  opacity: 0;
  animation: chat-message-target-wash 2.75s cubic-bezier(0.22, 0.72, 0.2, 1) both;
}

@keyframes chat-message-target-row-wash {
  0% {
    opacity: 0;
    transform: scaleX(0.96);
  }
  14% {
    opacity: 1;
    transform: scaleX(1);
  }
  54% {
    opacity: 0.72;
  }
  100% {
    opacity: 0;
    transform: scaleX(1);
  }
}

@keyframes chat-message-target-settle {
  0% {
    transform: translateY(2px);
    box-shadow:
      0 0 0 0 rgba(125, 211, 252, 0),
      0 8px 20px rgba(2, 6, 23, 0.1);
    filter: saturate(1);
  }
  16% {
    transform: translateY(0);
    box-shadow:
      0 0 0 1px rgba(125, 211, 252, 0.48),
      0 0 0 6px rgba(125, 211, 252, 0.1),
      0 16px 38px rgba(14, 165, 233, 0.22),
      0 8px 26px rgba(168, 85, 247, 0.16);
    filter: saturate(1.08) brightness(1.04);
  }
  62% {
    box-shadow:
      0 0 0 1px rgba(125, 211, 252, 0.3),
      0 0 0 4px rgba(125, 211, 252, 0.06),
      0 10px 26px rgba(14, 165, 233, 0.14),
      0 5px 18px rgba(168, 85, 247, 0.1);
    filter: saturate(1.04) brightness(1.02);
  }
  100% {
    transform: translateY(0);
    box-shadow:
      0 0 0 0 rgba(125, 211, 252, 0),
      0 0 0 rgba(14, 165, 233, 0),
      0 0 0 rgba(168, 85, 247, 0);
    filter: saturate(1);
  }
}

@keyframes chat-message-target-wash {
  0% {
    opacity: 0;
  }
  16% {
    opacity: 1;
  }
  52% {
    opacity: 0.58;
  }
  100% {
    opacity: 0;
  }
}

