}

.student-message-reaction-pill,
.student-message-reaction-add,
.student-message-reaction-option {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(125, 211, 252, 0.22);
  background: rgba(15, 23, 42, 0.44);
  color: rgb(226, 232, 240);
  line-height: 1;
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.student-message-reaction-pill {
  gap: 0.24rem;
  min-width: 2.3rem;
  height: 1.55rem;
  border-radius: 999px;
  padding: 0 0.44rem;
  font-size: 0.78rem;
  box-shadow:
    0 8px 18px rgba(2, 6, 23, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.student-message-toolbar .student-message-reaction-pill {
  cursor: pointer;
  pointer-events: auto;
}

.student-message-reaction-pill strong {
  color: rgba(226, 232, 240, 0.82);
  font-size: 0.66rem;
  font-weight: 950;
}

.student-message-reaction-pill--mine {
  border-color: rgba(45, 212, 191, 0.52);
  background:
    radial-gradient(circle at 0% 0%, rgba(45, 212, 191, 0.28), transparent 46%),
    linear-gradient(135deg, rgba(14, 165, 233, 0.28), rgba(124, 58, 237, 0.24));
  color: rgb(236, 253, 245);
  box-shadow:
    0 10px 22px rgba(14, 165, 233, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.student-message-reaction-pill--mine strong {
  color: rgb(207, 250, 254);
}

.student-message-reaction-wrap {
  position: relative;
  display: inline-flex;
}

.student-message-reaction-add {
  width: 1.55rem;
  height: 1.55rem;
  border-radius: 0.65rem;
  opacity: 0.78;
}

.student-message-row:hover .student-message-reaction-add,
.teacher-chat-message-row:hover .student-message-reaction-add,
.student-message-reaction-add--active,
.student-message-reaction-add:focus-visible {
  opacity: 1;
}

.student-message-reaction-pill:hover,
.student-message-reaction-add:hover,
.student-message-reaction-option:hover {
  transform: translateY(-1px);
  border-color: rgba(45, 212, 191, 0.48);
  background: rgba(30, 41, 59, 0.68);
}

.student-message-reaction-picker {
  position: absolute;
  bottom: calc(100% + 0.42rem);
  z-index: 70;
  display: flex;
  gap: 0.2rem;
  border: 1px solid rgba(125, 211, 252, 0.28);
  border-radius: 999px;
  background:
    radial-gradient(circle at 18% 0%, rgba(34, 211, 238, 0.18), transparent 42%),
    linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(30, 41, 59, 0.92));
  padding: 0.28rem;
  box-shadow:
    0 18px 42px rgba(2, 6, 23, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.student-message-reaction-wrap--mine .student-message-reaction-picker {
  right: 0;
}

.student-message-reaction-wrap--other .student-message-reaction-picker {
  left: 0;
}

.student-message-reaction-option {
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  font-size: 1rem;
}

.student-message-reaction-option--active {
  border-color: rgba(45, 212, 191, 0.56);
  background: linear-gradient(135deg, rgba(20, 184, 166, 0.36), rgba(168, 85, 247, 0.28));
}

.student-message-reaction-pill:disabled,
.student-message-reaction-add:disabled,
.student-message-reaction-option:disabled {
  cursor: not-allowed;
  opacity: 0.58;
  transform: none;
}

.student-message-reaction-burst {
  position: absolute;
  left: 0;
  top: 50%;
  z-index: 8;
  pointer-events: none;
  display: grid;
  place-items: center;
  width: 3.4rem;
  height: 3.4rem;
  transform: translate(-0.58rem, -50%);
}

.student-message-reaction-strip--mine .student-message-reaction-burst {
  right: 0;
  left: auto;
  transform: translate(0.58rem, -50%);
}

.student-message-reaction-burst__halo {
  position: absolute;
  inset: 0.3rem;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.85), rgba(34, 211, 238, 0.28) 44%, transparent 70%);
  animation: student-reaction-halo 740ms ease-out forwards;
}

.student-message-reaction-burst__emoji {
  position: relative;
  z-index: 2;
  font-size: 1.62rem;
  filter: drop-shadow(0 10px 18px rgba(2, 6, 23, 0.34));
  animation: student-reaction-pop 760ms cubic-bezier(0.18, 1.08, 0.26, 1) forwards;
}

.student-message-reaction-burst__spark {
  position: absolute;
  z-index: 1;
  width: 0.34rem;
  height: 0.34rem;
  border-radius: 999px;
  background: linear-gradient(135deg, #67e8f9, #f0abfc);
  box-shadow: 0 0 12px rgba(103, 232, 249, 0.58);
  animation: student-reaction-spark 720ms ease-out forwards;
}

.student-message-reaction-burst__spark--0 { --spark-x: -1.45rem; --spark-y: -1.05rem; }
.student-message-reaction-burst__spark--1 { --spark-x: 1.38rem; --spark-y: -1.08rem; }
.student-message-reaction-burst__spark--2 { --spark-x: -1.35rem; --spark-y: 1.12rem; }
.student-message-reaction-burst__spark--3 { --spark-x: 1.38rem; --spark-y: 1.05rem; }
.student-message-reaction-burst__spark--4 { --spark-x: 0; --spark-y: -1.62rem; }
.student-message-reaction-burst__spark--5 { --spark-x: 0.2rem; --spark-y: 1.58rem; }

@keyframes student-reaction-pop {
  0% {
    opacity: 0;
    transform: translateY(0.3rem) scale(0.36) rotate(-10deg);
  }
  34% {
    opacity: 1;
    transform: translateY(-0.62rem) scale(1.18) rotate(6deg);
  }
  70% {
    opacity: 1;
    transform: translateY(-0.86rem) scale(1);
  }
  100% {
    opacity: 0;
    transform: translateY(-1.35rem) scale(0.72);
  }
}

@keyframes student-reaction-halo {
  0% {
    opacity: 0.84;
    transform: scale(0.24);
  }
  100% {
    opacity: 0;
    transform: scale(1.9);
  }
}

@keyframes student-reaction-spark {
  0% {
    opacity: 0;
    transform: translate(0, 0) scale(0.2);
  }
  30% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translate(var(--spark-x), var(--spark-y)) scale(0.8);
  }
}

.student-message-view-popover {
  position: fixed;
  z-index: 80;
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-width: 9.5rem;
  border: 1px solid rgba(125, 211, 252, 0.34);
  border-radius: 1rem;
  background:
    radial-gradient(circle at 0% 0%, rgba(34, 211, 238, 0.22), transparent 42%),
    linear-gradient(145deg, rgba(15, 23, 42, 0.96), rgba(30, 41, 59, 0.9));
  padding: 0.62rem 0.72rem;
  color: rgb(248, 250, 252);
  box-shadow:
    0 18px 42px rgba(2, 6, 23, 0.32),
    0 0 0 1px rgba(255, 255, 255, 0.05) inset;
}

.student-message-view-popover__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 0.78rem;
  background: linear-gradient(135deg, rgba(34, 211, 238, 0.34), rgba(168, 85, 247, 0.32));
  color: rgb(207, 250, 254);
}

.student-message-view-popover__text {
  display: grid;
  gap: 0.18rem;
  font-weight: 950;
  line-height: 1;
}

.student-message-view-popover__text span {
  color: rgba(203, 213, 225, 0.82);
  font-size: 0.68rem;
}

.student-message-view-popover__text strong {
  color: rgb(255, 255, 255);
  font-size: 1.1rem;
}

.student-message-context-menu {
  position: fixed;
  z-index: 2200;
  display: grid;
  width: min(17.5rem, calc(100vw - 1.25rem));
  gap: 0.18rem;
  border: 1px solid rgba(125, 211, 252, 0.28);
  border-radius: 1rem;
  background:
    radial-gradient(circle at 0% 0%, rgba(34, 211, 238, 0.22), transparent 42%),
    radial-gradient(circle at 100% 0%, rgba(168, 85, 247, 0.2), transparent 42%),
    linear-gradient(145deg, rgba(15, 23, 42, 0.98), rgba(30, 41, 59, 0.94));
  padding: 0.36rem;
  color: rgb(248, 250, 252);
  opacity: 0;
  transform: translateY(0.38rem) scale(0.96);
  transform-origin: top left;
  animation: student-message-context-menu-in 170ms cubic-bezier(0.18, 0.9, 0.24, 1) forwards;
  box-shadow:
    0 20px 52px rgba(2, 6, 23, 0.38),
