  backdrop-filter: blur(16px);
}

.student-message-context-menu__reactions {
  display: flex;
  align-items: center;
  gap: 0.28rem;
  overflow-x: auto;
  scrollbar-width: none;
  margin: -0.04rem -0.02rem 0.22rem;
  padding: 0.12rem 0.08rem 0.42rem;
  border-bottom: 1px solid rgba(125, 211, 252, 0.18);
}

.student-message-context-menu__reactions::-webkit-scrollbar {
