  box-shadow:
    0 0 0 1px rgba(45, 212, 191, 0.18) inset,
    0 12px 26px rgba(20, 184, 166, 0.16);
}

.student-message-context-menu__readers {
  display: grid;
  gap: 0.42rem;
  margin: -0.04rem -0.02rem 0.22rem;
  padding: 0.16rem 0.08rem 0.48rem;
  border-bottom: 1px solid rgba(125, 211, 252, 0.18);
}

.student-message-context-menu__readers-head {
  display: flex;
  align-items: center;
  gap: 0.38rem;
