}

.student-message-context-menu__reader {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.42rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.85rem;
  background: rgba(255, 255, 255, 0.07);
  padding: 0.32rem 0.42rem;
}

.student-message-context-menu__reader-avatar {
  display: grid;
  width: 1.55rem;
  height: 1.55rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 0.58rem;
  background:
    radial-gradient(circle at 28% 18%, rgba(255, 255, 255, 0.32), transparent 42%),
    linear-gradient(135deg, #22d3ee, #8b5cf6);
  color: #fff;
  font-size: 0.62rem;
  font-weight: 950;
  box-shadow: 0 7px 16px rgba(14, 165, 233, 0.16);
}

.student-message-context-menu__reader-name {
  min-width: 0;
  overflow: hidden;
  color: rgba(248, 250, 252, 0.9);
