  text-align: center;
}

.student-message-context-menu__reader-empty {
  border: 1px dashed rgba(125, 211, 252, 0.2);
  border-radius: 0.85rem;
  padding: 0.58rem 0.5rem;
}

@keyframes student-message-context-menu-in {
  from {
    opacity: 0;
    transform: translateY(0.38rem) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.student-message-context-menu__button {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  gap: 0.55rem;
  border-radius: 0.76rem;
  padding: 0.48rem 0.6rem;
  color: rgba(248, 250, 252, 0.9);
  font-size: 0.78rem;
  font-weight: 900;
  line-height: 1;
