  font-size: 32px;
  font-weight: 950;
  line-height: 1.05;
  letter-spacing: 0;
}

.student-lesson-join-prompt__copy p {
  margin: 8px 0 0;
  color: #475569;
  font-size: 15px;
  font-weight: 750;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.student-lesson-join-prompt__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 18px 24px 10px;
}

.student-lesson-join-prompt__primary,
.student-lesson-join-prompt__secondary {
  display: inline-flex;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border-radius: 14px;
  font-weight: 950;
  line-height: 1.15;
  text-align: center;
  text-decoration: none;
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease, border-color 160ms ease;
}

.student-lesson-join-prompt__primary {
  flex: 1 1 300px;
  padding: 0 18px;
  border: 1px solid rgba(6, 182, 212, 0.5);
  background: linear-gradient(135deg, #06b6d4, #2563eb);
  color: white;
  box-shadow: 0 18px 38px rgba(37, 99, 235, 0.26);
}

.student-lesson-join-prompt__primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 22px 44px rgba(37, 99, 235, 0.34);
}

.student-lesson-join-prompt__primary--disabled,
.student-lesson-join-prompt__primary--disabled:hover {
  cursor: not-allowed;
  transform: none;
  border-color: rgba(148, 163, 184, 0.34);
  background: #e2e8f0;
  color: #64748b;
  box-shadow: none;
}

.student-lesson-join-prompt__secondary {
  flex: 0 1 auto;
  padding: 0 14px;
  border: 1px solid rgba(148, 163, 184, 0.32);
  background: rgba(255, 255, 255, 0.78);
  color: #334155;
}

.student-lesson-join-prompt__secondary--telemost {
  flex: 0 1 260px;
}

.student-lesson-join-prompt__secondary:hover {
  transform: translateY(-1px);
  border-color: rgba(14, 165, 233, 0.36);
  background: rgba(240, 249, 255, 0.94);
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.08);
}

.student-lesson-join-prompt__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 24px 24px;
}

.student-lesson-join-prompt__meta span {
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(148, 163, 184, 0.26);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.54);
  color: #475569;
  font-size: 12px;
  font-weight: 850;
}

@keyframes studentLessonJoinBackdropIn {
  from {
    opacity: 0;
    backdrop-filter: blur(0) saturate(100%);
  }
  to {
    opacity: 1;
    backdrop-filter: blur(16px) saturate(112%);
  }
}

@keyframes studentLessonJoinCardIn {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 900px) {
  .schedule-shell__composer-grid {
    grid-template-columns: minmax(0, 1fr) minmax(145px, 0.45fr);
  }

  .schedule-shell__composer-actions {
    grid-column: 1 / -1;
  }

  .schedule-shell__student-lessons {
    grid-template-columns: 1fr;
    grid-template-rows: none;
    grid-auto-flow: row;
  }
}

@media (max-width: 640px) {
  .schedule-shell__support-grid,
  .schedule-shell__composer-grid,
  .schedule-shell__slots-grid {
    grid-template-columns: 1fr;
  }

  .schedule-shell__composer-actions {
    grid-column: auto;
    align-items: stretch;
    flex-direction: column;
  }

  .schedule-shell__composer-heading {
    flex-direction: column;
  }

  .schedule-shell__student-reminder-compact {
    width: 100%;
    max-width: none;
  }

  .schedule-shell__student-week-strip {
    grid-template-columns: repeat(7, minmax(58px, 1fr));
    overflow-x: auto;
    padding-bottom: 2px;
  }

  .schedule-shell__student-lesson {
    grid-template-columns: 54px minmax(0, 1fr);
  }

  .schedule-shell__student-lesson-link {
    grid-column: 1 / -1;
    width: 100%;
  }

  .student-lesson-join-prompt {
    align-items: flex-end;
    padding: 10px;
  }

  .student-lesson-join-prompt__card {
    border-radius: 20px;
  }

  .student-lesson-join-prompt__top {
    flex-direction: column;
    padding: 26px 58px 10px 16px;
  }

  .student-lesson-join-prompt__countdown {
    width: 100%;
    justify-content: flex-start;
  }

  .student-lesson-join-prompt__body {
    grid-template-columns: 58px minmax(0, 1fr);
    gap: 12px;
    padding: 12px 16px 8px;
  }

  .student-lesson-join-prompt__icon {
    width: 58px;
    height: 58px;
    border-radius: 16px;
  }

  .student-lesson-join-prompt__copy h2 {
    font-size: 24px;
  }

  .student-lesson-join-prompt__copy p {
    font-size: 13px;
  }

  .student-lesson-join-prompt__actions {
    padding: 14px 16px 8px;
  }

  .student-lesson-join-prompt__primary,
  .student-lesson-join-prompt__secondary {
    width: 100%;
    flex: 1 1 100%;
  }

  .student-lesson-join-prompt__meta {
    padding: 8px 16px 16px;
  }
}

