@keyframes notesFolderIconOpen {
  0% {
    transform: translateY(0) scale(1);
  }
  45% {
    transform: translateY(-2px) scale(1.08);
  }
  100% {
    transform: translateY(0) scale(1);
  }
}

@keyframes notesFolderChevronOpen {
  0% {
    transform: translateX(0);
  }
  55% {
    transform: translateX(4px);
  }
  100% {
    transform: translateX(0);
  }
}

.notes-explorer-shell .notes-explorer-folder-file-row {
  cursor: pointer;
  position: relative;
  transition: background 0.18s ease, box-shadow 0.18s ease, color 0.18s ease;
}

.notes-explorer-shell .notes-explorer-folder-file-row td {
  transition: background 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.notes-explorer-shell .notes-explorer-folder-file-row:hover td {
  background:
    linear-gradient(90deg, rgba(255, 251, 235, 0.72), rgba(239, 246, 255, 0.76));
}

.notes-explorer-shell .notes-explorer-folder-file-row:hover .notes-explorer-folder-name {
  color: #0f172a;
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-selected td {
  background:
    linear-gradient(90deg, rgba(219, 234, 254, 0.96), rgba(239, 246, 255, 0.84));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    inset 0 -1px 0 rgba(147, 197, 253, 0.28);
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-selected .notes-explorer-folder-name {
  color: #0b3a82;
  font-weight: 700;
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-selected .notes-explorer-folder-name-cell {
  box-shadow:
    inset 3px 0 0 rgba(37, 99, 235, 0.74),
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    inset 0 -1px 0 rgba(147, 197, 253, 0.28);
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-pressing:not(.is-opening) td {
  background:
    linear-gradient(90deg, rgba(254, 243, 199, 0.84), rgba(219, 234, 254, 0.72));
}

.notes-explorer-shell .notes-explorer-folder-file-row:hover .notes-explorer-inline-folder-icon {
  transform: translateY(-1px) scale(1.04);
  filter: drop-shadow(0 8px 12px rgba(217, 119, 6, 0.18));
}

.notes-explorer-shell .notes-explorer-folder-file-row:active .notes-explorer-inline-folder-icon {
  transform: translateY(1px) scale(0.96);
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-opening td {
  background:
    linear-gradient(90deg, rgba(254, 243, 199, 0.92), rgba(219, 234, 254, 0.9), rgba(254, 243, 199, 0.78));
  background-size: 220% 100%;
  animation: notesFolderRowPress 0.28s ease;
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-opening .notes-explorer-inline-folder-icon {
  animation: notesFolderIconOpen 0.26s ease;
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-opening .notes-explorer-folder-open-chevron {
  animation: notesFolderChevronOpen 0.26s ease;
}

.notes-explorer-shell .notes-explorer-folder-file-row:focus-visible {
  outline: none;
  box-shadow: inset 3px 0 0 rgba(37, 99, 235, 0.78);
}

.notes-explorer-shell .notes-explorer-folder-file-row.is-drop-target {
  background: linear-gradient(90deg, rgba(219, 234, 254, 0.9), rgba(239, 246, 255, 0.72)) !important;
  box-shadow: inset 3px 0 0 rgba(37, 99, 235, 0.72);
}

.notes-explorer-shell .notes-explorer-inline-folder-icon {
  position: relative;
  overflow: visible;
  border: 0 !important;
  background: transparent !important;
  color: #b45309;
  box-shadow: none !important;
  transition: transform 0.18s ease, filter 0.18s ease;
}

.notes-explorer-shell .notes-explorer-inline-folder-icon::before,
.notes-explorer-shell .notes-explorer-inline-folder-icon::after {
  content: '';
  position: absolute;
  display: block;
  pointer-events: none;
}

.notes-explorer-shell .notes-explorer-inline-folder-icon::before {
  left: 5px;
  top: 5px;
  width: 15px;
  height: 7px;
  border-radius: 5px 5px 2px 2px;
  background: linear-gradient(180deg, #fde68a, #f59e0b);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.notes-explorer-shell .notes-explorer-inline-folder-icon::after {
  left: 2px;
  right: 2px;
  bottom: 4px;
  height: 19px;
  border: 1px solid rgba(180, 83, 9, 0.24);
  border-radius: 6px;
  background:
    radial-gradient(circle at 35% 18%, rgba(255, 255, 255, 0.42), transparent 32%),
    linear-gradient(180deg, #fbbf24, #d97706);
  box-shadow:
    0 8px 14px rgba(217, 119, 6, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.42);
}

.notes-explorer-shell .notes-explorer-inline-folder-icon svg {
  opacity: 0;
}

.notes-explorer-shell .notes-explorer-folder-open-btn {
  overflow: hidden;
}

.notes-explorer-shell .notes-explorer-folder-open-chevron {
  transition: transform 0.18s ease;
}

.notes-explorer-shell .notes-explorer-folder-file-row:hover .notes-explorer-folder-open-chevron,
.notes-explorer-shell .notes-explorer-folder-open-btn:hover .notes-explorer-folder-open-chevron {
  transform: translateX(2px);
