  width: min(5.35rem, 82%);
  height: 5.15rem;
  object-fit: contain;
  margin-top: 0.7rem;
  filter:
    drop-shadow(0 0.55rem 0.35rem rgba(30, 41, 59, 0.24))
    drop-shadow(0 0 0.9rem rgba(255, 255, 255, 0.32));
  transition: transform 0.24s cubic-bezier(0.18, 0.84, 0.2, 1.16), filter 0.24s ease;
