.mock-timer-chest-slot__ghost {
  position: relative;
  z-index: 3;
  width: 4.8rem;
  height: 3.8rem;
  border: 1px dashed rgba(100, 116, 139, 0.28);
  border-radius: 1.55rem 1.55rem 0.72rem 0.72rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.35), rgba(148, 163, 184, 0.13));
  margin-top: 0.7rem;
}

.mock-timer-chest-slot__ghost::before {
  content: '';
  position: absolute;
  right: 0.55rem;
  bottom: 0.88rem;
  left: 0.55rem;
  height: 1.25rem;
  border-top: 1px dashed rgba(100, 116, 139, 0.2);
  border-bottom: 1px dashed rgba(100, 116, 139, 0.16);
