.mock-timer-chest-slot__ghost::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 1.55rem;
  width: 0.82rem;
  height: 1.02rem;
  transform: translateX(-50%);
  border-radius: 0.28rem;
  background: rgba(100, 116, 139, 0.14);
  box-shadow: 0 0.48rem 0 rgba(100, 116, 139, 0.08);
}

.mock-timer-chest-slot__action {
