@keyframes mockTimerChestSlotSquish {
  0% {
    transform: translateY(0) scale(1);
  }
  34% {
    transform: translateY(0.18rem) scale(1.035, 0.9);
  }
  62% {
    transform: translateY(-0.08rem) scale(0.965, 1.055);
  }
  100% {
    transform: translateY(0) scale(1);
  }
}

@keyframes mockTimerChestImageSquish {
  0% {
    transform: translateY(0) scale(1);
  }
  32% {
    transform: translateY(0.28rem) scale(1.08, 0.84);
  }
  64% {
    transform: translateY(-0.16rem) scale(0.92, 1.08);
  }
  100% {
    transform: translateY(0) scale(1);
  }
}

@keyframes mockTimerChestStartState {
  0% {
    transform: translateY(0) scale(1);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.56),
      inset 0 -1.15rem 1.3rem rgba(30, 41, 59, 0.18),
      0 0.65rem 1.1rem rgba(88, 28, 135, 0.18);
  }
  46% {
    transform: translateY(-0.18rem) scale(1.018);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.7),
      inset 0 -1.15rem 1.3rem rgba(30, 41, 59, 0.16),
      0 1rem 1.55rem rgba(59, 130, 246, 0.22),
      0 0 1.45rem rgba(34, 211, 238, 0.34);
  }
  100% {
    transform: translateY(0) scale(1);
  }
}

@keyframes mockTimerChestPanelPulse {
  0%, 100% {
    filter: brightness(1) saturate(1);
  }
  50% {
    filter: brightness(1.07) saturate(1.16);
  }
}

@keyframes mockTimerChestOpeningState {
  0% {
    transform: translateY(0) scale(0.985);
    filter: brightness(1.08) saturate(1.08);
  }
  48% {
    transform: translateY(-0.12rem) scale(1.012);
    filter: brightness(1.12) saturate(1.16);
  }
  100% {
    transform: translateY(0) scale(1);
    filter: brightness(1) saturate(1);
  }
}

@keyframes mockTimerChestReadyGlow {
  0%, 100% {
    filter: brightness(1) saturate(1);
  }
  50% {
    filter: brightness(1.1) saturate(1.14);
  }
}

@keyframes mockTimerChestClaimState {
  0% {
    transform: translateY(0) scale(1);
  }
  38% {
    transform: translateY(0.16rem) scale(1.05, 0.92);
  }
  72% {
    transform: translateY(-0.3rem) scale(1.03);
  }
  100% {
    transform: translateY(-0.08rem) scale(1);
  }
}

@keyframes mockTimerChestAuraSweep {
  from {
    transform: rotate(0deg) scale(1.05);
  }
  to {
    transform: rotate(360deg) scale(1.05);
  }
}

@keyframes mockTimerChestImageHalo {
  0%, 100% {
    opacity: 0.48;
    transform: translateX(-50%) scale(0.94);
    filter: blur(0.1rem);
  }
  50% {
    opacity: 0.76;
    transform: translateX(-50%) scale(1.08);
    filter: blur(0.18rem);
  }
}

@keyframes mockTimerChestStartBurst {
  0% {
    opacity: 0;
    transform: scale(0.25);
  }
  22% {
    opacity: 0.92;
  }
  100% {
    opacity: 0;
    transform: scale(1.55);
  }
}

@keyframes mockTimerChestClaimBurst {
  0% {
    opacity: 0;
    transform: scale(0.34) rotate(0deg);
  }
  34% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: scale(1.9) rotate(24deg);
  }
}

@keyframes mockTimerChestStartImage {
  0% {
    transform: translateY(0) rotate(0deg) scale(1);
  }
  30% {
    transform: translateY(0.18rem) rotate(-2deg) scale(1.06, 0.92);
  }
  58% {
    transform: translateY(-0.24rem) rotate(2deg) scale(0.96, 1.07);
  }
  100% {
    transform: translateY(0) rotate(0deg) scale(1);
  }
}

@keyframes mockTimerChestOpeningImage {
  0%, 100% {
    transform: translateY(0) rotate(-0.8deg) scale(1);
  }
  50% {
    transform: translateY(-0.12rem) rotate(0.8deg) scale(1.025);
  }
}

@keyframes mockTimerChestReadyFloat {
  0%, 100% {
    transform: translateY(0) scale(1);
  }
  50% {
    transform: translateY(-0.16rem) scale(1.04);
  }
}

@keyframes mockTimerChestClaimImage {
  0% {
    transform: translateY(0) rotate(0deg) scale(1);
  }
  28% {
    transform: translateY(0.22rem) rotate(-2deg) scale(1.08, 0.9);
  }
  62% {
    transform: translateY(-0.56rem) rotate(3deg) scale(1.08);
  }
  100% {
    transform: translateY(-0.08rem) rotate(0deg) scale(1);
  }
}

.mock-timer-chest-modal {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100vw;
  height: 100vh;
  min-height: 100dvh;
  background: rgba(15, 23, 42, 0.46);
  padding: 1rem;
  backdrop-filter: blur(10px);
  animation: mockTimerChestModalFade 0.18s ease both;
}

.mock-timer-chest-modal__card {
  position: relative;
  width: min(92vw, 24rem);
  overflow: hidden;
  border: 1px solid rgba(168, 85, 247, 0.28);
  border-radius: 1.4rem;
  background:
    radial-gradient(circle at 50% 0%, rgba(253, 224, 71, 0.24), transparent 34%),
    radial-gradient(circle at 0% 20%, rgba(34, 211, 238, 0.18), transparent 36%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.97), rgba(250, 245, 255, 0.96));
  padding: 1.25rem;
  text-align: center;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 1.5rem 4rem rgba(15, 23, 42, 0.26);
  animation: mockTimerChestModalPop 0.3s cubic-bezier(0.16, 0.9, 0.18, 1.08) both;
}

.mock-timer-chest-modal__glow {
  position: absolute;
  inset: -30%;
  pointer-events: none;
  background:
    conic-gradient(from 0deg, transparent 0 32deg, rgba(168, 85, 247, 0.16) 58deg, transparent 86deg 168deg, rgba(34, 211, 238, 0.16) 206deg, transparent 250deg 360deg);
  opacity: 0.9;
  animation: mockTimerChestAuraSweep 9s linear infinite;
}

.mock-timer-chest-modal__icon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  width: 5.4rem;
  height: 4.7rem;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.35rem;
}

.mock-timer-chest-modal__icon img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter:
    drop-shadow(0 0.55rem 0.5rem rgba(15, 23, 42, 0.18))
    drop-shadow(0 0 1.15rem rgba(253, 224, 71, 0.34));
  animation: mockTimerChestReadyFloat 1.65s ease-in-out infinite;
}

.mock-timer-chest-modal__title,
.mock-timer-chest-modal__message,
.mock-timer-chest-modal__timer,
.mock-timer-chest-modal__actions,
.mock-timer-chest-modal__button {
  position: relative;
  z-index: 1;
}

.mock-timer-chest-modal__title {
  color: #1e293b;
  font-size: 1.05rem;
  font-weight: 950;
  line-height: 1.16;
}

.mock-timer-chest-modal__message {
  margin-top: 0.45rem;
  color: #64748b;
  font-size: 0.86rem;
  font-weight: 700;
  line-height: 1.45;
}

.mock-timer-chest-modal__timer {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  margin-top: 0.85rem;
  border: 1px solid rgba(168, 85, 247, 0.22);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.76);
  padding: 0.42rem 0.72rem;
  color: #7e22ce;
  font-size: 0.95rem;
  font-variant-numeric: tabular-nums;
  font-weight: 950;
  box-shadow: 0 0.7rem 1.4rem rgba(88, 28, 135, 0.1);
}

.mock-timer-chest-modal__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  margin-top: 1rem;
}

.mock-timer-chest-modal__button {
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #22d3ee, #8b5cf6 55%, #f472b6);
  padding: 0.62rem 1.25rem;
  color: white;
  font-size: 0.86rem;
  font-weight: 900;
  box-shadow: 0 0.85rem 1.6rem rgba(124, 58, 237, 0.24);
  transition: transform 0.18s ease, filter 0.18s ease;
}

.mock-timer-chest-modal__button--test {
  background: linear-gradient(135deg, #facc15, #fb923c 46%, #f472b6);
  box-shadow:
    0 0.85rem 1.6rem rgba(251, 146, 60, 0.22),
    0 0 1.3rem rgba(250, 204, 21, 0.22);
}

.mock-timer-chest-modal__button:hover {
  transform: translateY(-1px);
  filter: brightness(1.04);
}

.mock-timer-chest-modal__button:disabled {
  cursor: wait;
  opacity: 0.72;
  transform: none;
  filter: saturate(0.85);
}

@keyframes mockTimerChestModalFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes mockTimerChestModalPop {
  0% {
    opacity: 0;
    transform: translateY(0.7rem) scale(0.95);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 640px) {
  .mock-timer-chest-panel__empty-state {
    grid-template-columns: 1fr;
  }

  .mock-timer-chest-panel--empty .mock-timer-chest-panel__empty-state {
    grid-template-columns: 1fr;
  }

  .mock-timer-chest-panel__empty-slots {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .mock-timer-chest-panel--empty .mock-timer-chest-panel__empty-slots {
    width: 100%;
  }

  .mock-timer-chest-panel__empty-slots span {
    min-height: 2.65rem;
  }

  .mock-timer-chest-panel__slots {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mock-timer-chest-slot {
    min-height: 7.6rem;
  }

  .mock-timer-chest-slot__status {
    min-width: 5rem;
  }

  .mock-timer-chest-slot__image {
    width: min(5rem, 84%);
  }
}

