  --artifact-upgrade-accent-strong: rgba(168, 85, 247, 0.62);
  position: fixed;
  inset: 0;
  z-index: 10050;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 44%, var(--artifact-upgrade-accent-soft), transparent 28%),
    radial-gradient(circle at 50% 62%, rgba(34, 197, 94, 0.14), transparent 28%),
    rgba(2, 6, 23, 0.98);
  color: #f8fafc;
  pointer-events: auto;
  cursor: pointer;
  animation: artifactUpgradeShowcaseScene 5.4s ease-out both;
