  opacity: 0;
  animation: artifactUpgradeShowcaseImpact 1.9s ease-out 1.15s both;
}

.student-artifact-upgrade-showcase__level {
  position: absolute;
  top: -2.25rem;
  z-index: 4;
  color: rgba(236, 253, 245, 0.96);
  font-size: clamp(0.76rem, 2vw, 1rem);
  font-weight: 1000;
  letter-spacing: 0.04em;
  text-shadow:
