    drop-shadow(0 0 34px var(--artifact-upgrade-accent-mid));
}

.student-artifact-upgrade-showcase__burst {
  position: absolute;
  left: 50%;
  top: 42%;
  z-index: 2;
  aspect-ratio: 1;
  border-radius: 999px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  opacity: 0;
}

.student-artifact-upgrade-showcase__burst--one {
  width: min(58vw, 36rem);
  border: 2px solid rgba(255, 255, 255, 0.48);
  box-shadow:
    0 0 34px var(--artifact-upgrade-accent-mid),
    inset 0 0 46px rgba(34, 197, 94, 0.24);
  animation: artifactUpgradeShowcaseShockwave 2.35s ease-out 1.18s both;
}

.student-artifact-upgrade-showcase__burst--two {
  width: min(42vw, 26rem);
  background: radial-gradient(circle, rgba(255, 255, 255, 0.58), var(--artifact-upgrade-accent-soft) 38%, transparent 70%);
  filter: blur(12px);
  animation: artifactUpgradeShowcaseGlow 2.85s ease-out 0.95s both;
}

.student-artifact-upgrade-showcase__results {
  position: absolute;
  right: max(1rem, env(safe-area-inset-right));
