  left: max(1rem, env(safe-area-inset-left));
  z-index: 4;
  max-width: 760px;
  margin: 0 auto;
  border: 1px solid rgba(74, 222, 128, 0.28);
  border-radius: 1.35rem;
  background:
    radial-gradient(circle at 50% 0%, rgba(34, 197, 94, 0.18), transparent 38%),
    linear-gradient(180deg, rgba(15, 23, 42, 0.88), rgba(2, 6, 23, 0.9));
  padding: clamp(0.85rem, 2.4vw, 1.15rem);
  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.46),
    0 0 44px rgba(34, 197, 94, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(18px) saturate(1.16);
  opacity: 0;
  transform: translateY(1.4rem);
  animation: artifactUpgradeShowcaseResults 3.15s cubic-bezier(0.16, 1, 0.3, 1) 1.55s both;
}

.student-artifact-upgrade-showcase__kicker {
  color: rgba(74, 222, 128, 0.96);
  font-size: 0.7rem;
  font-weight: 950;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.student-artifact-upgrade-showcase__title {
  margin-top: 0.22rem;
  color: rgba(248, 250, 252, 0.98);
  font-size: clamp(1.3rem, 3.2vw, 2rem);
  font-weight: 1000;
  line-height: 1;
}

.student-artifact-upgrade-showcase__rows {
  display: grid;
  gap: 0.5rem;
  margin-top: 0.85rem;
}

.student-artifact-upgrade-showcase__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.8rem;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 0.9rem;
  background: rgba(15, 23, 42, 0.66);
  padding: 0.65rem 0.75rem;
}

.student-artifact-upgrade-showcase__row[data-tone='xp'] {
  border-color: rgba(167, 139, 250, 0.34);
}

.student-artifact-upgrade-showcase__row[data-tone='coins'] {
  border-color: rgba(251, 191, 36, 0.3);
}

.student-artifact-upgrade-showcase__label {
  min-width: 0;
  color: rgba(203, 213, 225, 0.84);
  font-size: 0.78rem;
  font-weight: 850;
}

.student-artifact-upgrade-showcase__numbers {
  display: inline-flex;
  align-items: baseline;
  gap: 0.45rem;
  color: rgba(226, 232, 240, 0.86);
  font-size: clamp(0.9rem, 2.4vw, 1.2rem);
  font-weight: 950;
  white-space: nowrap;
}

.student-artifact-upgrade-showcase__before {
  color: rgba(148, 163, 184, 0.82);
}

.student-artifact-upgrade-showcase__arrow {
  color: rgba(148, 163, 184, 0.58);
}

.student-artifact-upgrade-showcase__after {
  color: rgba(248, 250, 252, 0.98);
}

.student-artifact-upgrade-showcase__delta {
  color: rgba(74, 222, 128, 0.98);
  font-size: 1.12em;
  text-shadow: 0 0 14px rgba(34, 197, 94, 0.42);
}

@property --legendary-rainbow-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

.student-artifact-altar__legendary-teaser {
  border-color: rgba(244, 63, 94, 0.28);
  background:
    radial-gradient(circle at 0% 0%, rgba(251, 113, 133, 0.2), transparent 34%),
    radial-gradient(circle at 100% 0%, rgba(245, 158, 11, 0.14), transparent 36%),
    linear-gradient(135deg, rgba(255, 241, 242, 0.86), rgba(255, 255, 255, 0.92) 44%, rgba(255, 247, 237, 0.88));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 20px 42px rgba(244, 63, 94, 0.09);
}

.student-artifact-altar__legendary-eyebrow {
  color: rgba(225, 29, 72, 0.92);
}

.student-artifact-altar__legendary-note {
  border-color: rgba(244, 63, 94, 0.22);
  background: rgba(255, 255, 255, 0.74);
  color: rgba(190, 18, 60, 0.9);
  box-shadow: 0 10px 22px rgba(244, 63, 94, 0.08);
}

.student-artifact-altar__legendary-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

.student-artifact-altar__legendary-card {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: 5.7rem minmax(0, 1fr);
  gap: 0.85rem;
  align-items: center;
  overflow: hidden;
  border: 1px solid var(--legendary-accent-mid, rgba(244, 63, 94, 0.22));
  border-radius: 1.35rem;
  background:
    radial-gradient(circle at 14% 50%, var(--legendary-accent-soft, rgba(244, 63, 94, 0.14)), transparent 35%),
    rgba(255, 255, 255, 0.74);
  padding: 0.75rem;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    0 14px 28px var(--legendary-accent-soft, rgba(244, 63, 94, 0.08));
  animation: artifactLegendaryTeaserIn 0.52s cubic-bezier(0.16, 1, 0.3, 1) both var(--legendary-delay, 0ms);
}

.student-artifact-altar__legendary-card[data-rank='SS'] {
  border-color: var(--legendary-accent-strong, rgba(255, 31, 109, 0.62));
  background:
    radial-gradient(circle at 72% 34%, rgba(56, 189, 248, 0.24), transparent 32%),
    radial-gradient(circle at 34% 88%, rgba(168, 85, 247, 0.22), transparent 34%),
    radial-gradient(circle at 12% 48%, var(--legendary-accent-mid, rgba(255, 31, 109, 0.3)), transparent 38%),
    radial-gradient(circle at 100% 0%, rgba(255, 255, 255, 0.92), transparent 28%),
    rgba(255, 255, 255, 0.82);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    inset 0 0 34px rgba(255, 255, 255, 0.54),
    0 20px 44px var(--legendary-accent-soft, rgba(255, 31, 109, 0.24)),
    0 0 38px rgba(56, 189, 248, 0.22),
    0 0 58px rgba(168, 85, 247, 0.18),
    0 0 72px var(--legendary-accent-soft, rgba(255, 31, 109, 0.22));
}

.student-artifact-altar__legendary-card[data-rank='SS']::before {
  opacity: 0.62;
  animation-duration: 3.8s;
}

.student-artifact-altar__legendary-card::before {
  content: '';
  position: absolute;
  inset: -45%;
  z-index: 0;
  background: conic-gradient(from 190deg, transparent, rgba(255, 255, 255, 0.48), transparent 32%);
  opacity: 0.4;
  animation: artifactLegendarySweep 4.8s ease-in-out infinite;
  pointer-events: none;
}

.student-artifact-altar__legendary-card::after {
  content: '';
  --legendary-rainbow-angle: 0deg;
  --legendary-border-opacity-low: 0.48;
  --legendary-border-opacity-high: 0.82;
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--legendary-rainbow-angle),
    rgba(56, 189, 248, 0.74),
    rgba(168, 85, 247, 0.76),
    rgba(244, 114, 182, 0.82),
    rgba(251, 191, 36, 0.72),
    rgba(74, 222, 128, 0.7),
    rgba(56, 189, 248, 0.74)
  );
  opacity: 0.5;
  filter: saturate(1.2) brightness(1.08);
  pointer-events: none;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation:
    artifactLegendaryRainbowBorder 7.2s linear infinite,
    artifactLegendaryBorderBreath 3.1s ease-in-out infinite;
}

.student-artifact-altar__legendary-card[data-rank='SS']::after {
  --legendary-border-opacity-low: 0.76;
  --legendary-border-opacity-high: 0.98;
  padding: 2px;
  opacity: 0.96;
  filter:
    saturate(1.55)
    brightness(1.18)
    drop-shadow(0 0 7px rgba(56, 189, 248, 0.56))
    drop-shadow(0 0 14px rgba(244, 114, 182, 0.46))
    drop-shadow(0 0 18px rgba(251, 191, 36, 0.24));
  animation:
    artifactLegendaryRainbowBorder 4.4s linear infinite,
    artifactLegendaryBorderBreath 2.25s ease-in-out infinite;
}

.student-artifact-altar__legendary-card > * {
  position: relative;
  z-index: 1;
}

.student-artifact-altar__legendary-visual {
  position: relative;
  isolation: isolate;
  display: grid;
  aspect-ratio: 1;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--legendary-accent-mid, rgba(244, 63, 94, 0.2));
  border-radius: 1.1rem;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.9), var(--legendary-accent-soft, rgba(244, 63, 94, 0.12)) 48%, transparent 72%),
    rgba(255, 255, 255, 0.5);
}

.student-artifact-altar__legendary-glow,
.student-artifact-altar__legendary-orbit {
  position: absolute;
  border-radius: 999px;
  pointer-events: none;
}

.student-artifact-altar__legendary-glow {
  width: 70%;
  aspect-ratio: 1;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.92), var(--legendary-accent-mid, rgba(244, 63, 94, 0.2)), transparent 70%);
  filter: blur(8px);
  animation: artifactLegendaryPulse 2.8s ease-in-out infinite;
}

.student-artifact-altar__legendary-orbit {
  width: 78%;
  aspect-ratio: 1;
  border: 1px dashed var(--legendary-accent-mid, rgba(244, 63, 94, 0.28));
  animation: artifactLegendaryOrbit 9s linear infinite;
}

.student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-glow {
  width: 96%;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.96), rgba(251, 191, 36, 0.42) 20%, rgba(244, 114, 182, 0.38) 44%, rgba(56, 189, 248, 0.32) 62%, transparent 76%);
  filter: blur(10px);
  animation-duration: 2.15s;
}

.student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-orbit {
  border-style: solid;
  border-color: rgba(255, 255, 255, 0.58);
  box-shadow:
    0 0 14px rgba(56, 189, 248, 0.36),
    0 0 24px var(--legendary-accent-soft, rgba(255, 31, 109, 0.32)),
    inset 0 0 20px rgba(251, 191, 36, 0.18),
    inset 0 0 24px var(--legendary-accent-soft, rgba(255, 31, 109, 0.2));
  animation-duration: 6.5s;
}

.student-artifact-altar__legendary-silhouette {
  position: relative;
  z-index: 1;
  width: 78%;
  height: 78%;
  object-fit: contain;
  opacity: 0.72;
  filter:
    brightness(0)
    saturate(0)
    contrast(1.2)
    drop-shadow(0 12px 16px rgba(15, 23, 42, 0.24))
    drop-shadow(0 0 16px var(--legendary-accent-mid, rgba(244, 63, 94, 0.34)));
  transform: scale(1.08);
}

.student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-silhouette {
  opacity: 0.82;
  transform: scale(1.15);
  filter:
    brightness(0)
    saturate(0)
    contrast(1.35)
    drop-shadow(0 14px 18px rgba(15, 23, 42, 0.3))
    drop-shadow(0 0 18px rgba(56, 189, 248, 0.46))
    drop-shadow(0 0 26px var(--legendary-accent-strong, rgba(255, 31, 109, 0.72)));
}

.student-artifact-altar__legendary-rank {
  color: var(--legendary-accent, rgba(225, 29, 72, 0.9));
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.student-artifact-altar__legendary-title {
  letter-spacing: -0.01em;
}

.student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-title {
  color: rgba(136, 19, 55, 0.98);
  font-size: clamp(1.05rem, 2vw, 1.45rem);
  line-height: 1.05;
  text-shadow: 0 10px 24px rgba(244, 63, 94, 0.16);
}

.student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-power {
  color: rgba(159, 18, 57, 0.9);
  font-size: 0.86rem;
  font-weight: 800;
}

.student-artifact-altar__legendary-tag {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--legendary-accent-mid, rgba(244, 63, 94, 0.18));
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.66);
  padding: 0.2rem 0.48rem;
  color: var(--legendary-accent, rgba(190, 18, 60, 0.86));
  font-size: 0.66rem;
  font-weight: 800;
}

@media (min-width: 900px) {
  .student-artifact-altar__legendary-grid {
    grid-template-columns: minmax(0, 1.22fr) minmax(0, 0.78fr);
    align-items: stretch;
  }

  .student-artifact-altar__legendary-card[data-rank='SS'] {
    grid-row: span 2;
    grid-template-columns: minmax(7.2rem, 9rem) minmax(0, 1fr);
    min-height: 11rem;
    padding: 1rem;
  }

  .student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-visual {
    border-radius: 1.45rem;
  }

  .student-artifact-altar__legendary-card[data-rank='SS'] .student-artifact-altar__legendary-rank {
    font-size: 0.72rem;
    letter-spacing: 0.24em;
  }
}

@keyframes artifactLegendaryTeaserIn {
  from {
    opacity: 0;
    transform: translateY(0.75rem) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

