@keyframes artifactUpgradeShowcaseShockwave {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.18);
  }
  18% {
    opacity: 0.86;
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.2);
  }
}

@keyframes artifactUpgradeShowcaseGlow {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.4);
  }
  35% {
    opacity: 0.86;
  }
  100% {
    opacity: 0.18;
    transform: translate(-50%, -50%) scale(1.1);
  }
}

@keyframes artifactUpgradeShowcaseRing {
  0% {
    opacity: 0;
    transform: scale(0.6) rotate(0deg);
  }
  24% {
    opacity: 0.7;
  }
  100% {
    opacity: 0.2;
    transform: scale(1.2) rotate(120deg);
  }
}

@keyframes artifactUpgradeShowcaseLevel {
  0% {
    opacity: 0;
    transform: translateY(0.45rem) scale(0.92);
  }
  35%, 100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes artifactUpgradeShowcaseResults {
  from {
    opacity: 0;
    transform: translateY(1.4rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 720px) {
  .student-artifact-detail-modal {
    align-items: flex-end;
    padding: 0.65rem;
  }

  .student-artifact-detail-modal__card {
    grid-template-columns: 1fr;
    gap: 0.85rem;
    max-height: 92vh;
    overflow-y: auto;
    padding: 0.85rem;
  }

  .student-artifact-detail-modal__visual {
    min-height: 260px;
  }

  .student-artifact-detail-modal__image {
    width: min(66%, 230px);
    height: min(66%, 230px);
  }

  .student-artifact-detail-modal__title {
    padding-right: 2.5rem;
    font-size: clamp(1.85rem, 10vw, 2.6rem);
    overflow-wrap: anywhere;
    hyphens: auto;
  }

  .student-artifact-upgrade-showcase__artifact {
    top: 36%;
  }

  .student-artifact-upgrade-showcase__image {
    width: min(54vw, 14rem);
    height: min(54vw, 14rem);
    min-width: 8rem;
    min-height: 8rem;
  }

  .student-artifact-upgrade-showcase__burst {
    top: 36%;
  }

  .student-artifact-upgrade-showcase__row {
    grid-template-columns: 1fr;
    gap: 0.35rem;
  }

  .student-artifact-upgrade-showcase__numbers {
    justify-content: space-between;
  }
}

