  .student-artifact-altar__legendary-card,
  .student-artifact-altar__legendary-card::before,
  .student-artifact-altar__legendary-card::after,
  .student-artifact-altar__legendary-glow,
  .student-artifact-altar__legendary-orbit,
  .student-artifact-altar__artifact-card[data-rank='S'],
  .student-artifact-altar__artifact-card[data-rank='SS'],
  .student-artifact-altar__artifact-card::before,
  .student-artifact-altar__mini-upgrade--ready .student-artifact-altar__mini-upgrade-track::after,
  .student-artifact-upgrade-showcase,
  .student-artifact-upgrade-showcase__artifact,
  .student-artifact-upgrade-showcase__artifact::before,
  .student-artifact-upgrade-showcase__artifact::after,
  .student-artifact-upgrade-showcase__burst,
  .student-artifact-upgrade-showcase__level,
  .student-artifact-upgrade-showcase__results {
    animation: none !important;
    transition: none !important;
  }

  .student-artifact-upgrade-showcase,
  .student-artifact-upgrade-showcase__burst,
  .student-artifact-upgrade-showcase__level,
  .student-artifact-upgrade-showcase__results {
    opacity: 1 !important;
  }

  .student-artifact-upgrade-showcase__artifact,
  .student-artifact-upgrade-showcase__results {
    transform: translate(-50%, -50%) !important;
  }

  .student-artifact-upgrade-showcase__results {
    transform: none !important;
  }
}

/* Notes explorer UX polish */
.notes-explorer-shell {
  --notes-explorer-border-light: rgba(148, 163, 184, 0.24);
  --notes-explorer-border-strong: rgba(96, 165, 250, 0.42);
  --notes-explorer-surface: rgba(255, 255, 255, 0.86);
  --notes-explorer-surface-raised: rgba(255, 255, 255, 0.94);
  --notes-explorer-text: #0f172a;
  --notes-explorer-muted: #64748b;
  --notes-explorer-blue: #2563eb;
}

.notes-explorer-shell .notes-explorer-window {
  border-color: rgba(96, 165, 250, 0.28) !important;
  background:
    radial-gradient(circle at 2% 0%, rgba(59, 130, 246, 0.09), transparent 28%),
    linear-gradient(180deg, rgba(248, 250, 252, 0.96), rgba(255, 255, 255, 0.9)) !important;
  box-shadow:
    0 22px 46px rgba(15, 23, 42, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.82) !important;
}

.notes-explorer-shell .notes-explorer-toolbar {
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(135deg, rgba(248, 250, 252, 0.98), rgba(255, 255, 255, 0.92)),
    radial-gradient(circle at 94% 0%, rgba(124, 58, 237, 0.07), transparent 28%) !important;
  border-color: rgba(148, 163, 184, 0.22) !important;
}

.notes-explorer-shell .notes-explorer-toolbar::before {
  content: none;
}

.notes-explorer-shell .notes-explorer-toolbar > * {
  position: relative;
  z-index: 1;
}

.notes-explorer-shell .notes-explorer-title {
  color: var(--notes-explorer-text) !important;
  letter-spacing: 0.005em;
}

.notes-explorer-shell .notes-explorer-toolbar-subtitle {
  max-width: 520px;
  color: var(--notes-explorer-muted) !important;
}

.notes-explorer-shell .notes-explorer-address {
