  --board-toolbar-bg: rgba(8, 15, 29, 0.78);
  --board-toolbar-group: rgba(15, 23, 42, 0.68);
  --board-toolbar-border: rgba(125, 211, 252, 0.2);
  --board-toolbar-button: rgba(15, 23, 42, 0.7);
  --board-toolbar-button-hover: rgba(30, 41, 59, 0.92);
  --board-toolbar-text: rgba(226, 232, 240, 0.95);
  --board-toolbar-muted: rgba(148, 163, 184, 0.9);
  background:
    radial-gradient(circle at 0% 0%, rgba(34, 211, 238, 0.13), transparent 36%),
    radial-gradient(circle at 100% 0%, rgba(168, 85, 247, 0.14), transparent 34%),
    linear-gradient(180deg, rgba(12, 20, 36, 0.86), rgba(4, 8, 18, 0.78));
  box-shadow:
    0 18px 38px rgba(2, 6, 23, 0.28),
    inset 0 1px 0 rgba(148, 163, 184, 0.1);
