.board-toolbar__session,
.board-toolbar__group {
  align-items: center;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 0.9rem;
  background: var(--board-toolbar-group);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.42);
}

.board-toolbar__session {
  max-width: 26rem;
  gap: 0.34rem;
  padding: 0.24rem 0.46rem;
  color: var(--board-toolbar-text);
}

.board-toolbar__eyebrow {
  border-radius: 999px;
  background: rgba(147, 51, 234, 0.14);
  padding: 0.12rem 0.34rem;
  color: rgba(147, 51, 234, 0.95);
  font-size: 0.56rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.board-toolbar__session-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.66rem;
  font-weight: 800;
}

.board-toolbar__group {
  display: inline-flex;
  gap: 0.18rem;
  min-height: calc(var(--board-toolbar-control-size) + 0.22rem);
  padding: 0.1rem;
}

.board-toolbar__button {
  position: relative;
  display: inline-flex;
  min-width: var(--board-toolbar-control-size);
  height: var(--board-toolbar-control-size);
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  border: 1px solid transparent;
  border-radius: var(--board-toolbar-control-radius);
  background: var(--board-toolbar-button);
  color: var(--board-toolbar-text);
  padding: 0 0.4rem;
  font-size: var(--board-toolbar-control-font);
  font-weight: 850;
  line-height: 1;
  transition:
    transform 0.16s ease,
    background-color 0.16s ease,
    border-color 0.16s ease,
    box-shadow 0.16s ease,
    color 0.16s ease;
}

.board-toolbar__button svg {
  flex: 0 0 auto;
}

.board-toolbar__button:not(:disabled):hover {
  transform: translateY(-1px);
  border-color: rgba(125, 211, 252, 0.34);
  background: var(--board-toolbar-button-hover);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.1);
}

.board-toolbar__button:not(:disabled):active {
  transform: translateY(0);
  box-shadow: none;
}

.board-toolbar__button:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 2px rgba(125, 211, 252, 0.45),
    0 0 0 5px rgba(59, 130, 246, 0.12);
}

.board-toolbar__button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.board-toolbar__button.is-active {
  border-color: rgba(168, 85, 247, 0.72);
  background: linear-gradient(180deg, #a855f7, #7c3aed);
