  0% {
    filter: saturate(1) brightness(1);
    box-shadow: inset 0 0 0 rgba(251, 191, 36, 0);
  }
  34% {
    filter: saturate(1.18) brightness(1.018);
    box-shadow:
      inset 0 0 0 999px rgba(255, 251, 235, 0.22),
      0 0 28px rgba(251, 191, 36, 0.16);
  }
  100% {
    filter: saturate(1) brightness(1);
    box-shadow: inset 0 0 0 rgba(251, 191, 36, 0);
  }
}

@keyframes notesFavoriteRowRemove {
  0% {
    filter: saturate(1.08) brightness(1.01);
    opacity: 1;
  }
  100% {
    filter: saturate(0.94) brightness(0.995);
    opacity: 1;
  }
}

