  from {
    transform: translateX(0) rotate(18deg);
  }
  to {
    transform: translateX(420%) rotate(18deg);
  }
}

@keyframes notesFavoriteButtonAdd {
  0% {
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82);
  }
  38% {
    transform: translateY(-1px) scale(1.08);
    box-shadow:
      0 12px 26px rgba(217, 119, 6, 0.18),
      0 0 0 6px rgba(251, 191, 36, 0.12),
      inset 0 1px 0 rgba(255, 255, 255, 0.9);
  }
  100% {
    transform: translateY(0) scale(1);
  }
}

@keyframes notesFavoriteButtonRemove {
  0% {
    transform: scale(1);
  }
  48% {
    transform: scale(0.92) rotate(-5deg);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes notesFavoriteStarAdd {
  0% {
    transform: scale(0.68) rotate(-18deg);
  }
  48% {
    transform: scale(1.18) rotate(8deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
  }
}

@keyframes notesFavoriteStarRemove {
  0% {
    transform: scale(1) rotate(0deg);
  }
  52% {
    transform: scale(0.74) rotate(-16deg);
  }
  100% {
    transform: scale(1) rotate(0deg);
  }
}

