/* Sidebar redesign v3: a single calm navigation surface. */
.sidebar-shell {
  --sidebar-bg: rgba(248, 250, 252, 0.96);
  --sidebar-line: rgba(203, 213, 225, 0.62);
  --sidebar-row: transparent;
  --sidebar-row-hover: rgba(255, 255, 255, 0.66);
  --sidebar-row-active: rgba(124, 58, 237, 0.13);
  --sidebar-row-active-strong: rgba(124, 58, 237, 0.2);
  --sidebar-icon: rgba(255, 255, 255, 0.78);
  --sidebar-icon-border: rgba(167, 139, 250, 0.24);
  --sidebar-text: rgb(30, 41, 59);
  --sidebar-muted: rgb(100, 116, 139);
  background: var(--sidebar-bg) !important;
  padding: 0 !important;
  box-shadow: inset -1px 0 0 var(--sidebar-line) !important;
}

