  gap: 0.24rem;
}

.sidebar-nav-stack > :not([hidden]) ~ :not([hidden]) {
  margin-top: 0 !important;
}

.sidebar-nav-item {
  min-height: 2.85rem;
  border: 1px solid transparent !important;
  border-radius: 0.88rem !important;
  background: var(--sidebar-row) !important;
  padding: 0.42rem 0.5rem 0.42rem 0.58rem !important;
  color: var(--sidebar-text) !important;
