}

.sidebar-nav-item:not(.is-active):hover {
  transform: none !important;
  border-color: var(--sidebar-line) !important;
  background: var(--sidebar-row-hover) !important;
  box-shadow: none !important;
}

.sidebar-nav-item.is-active {
  border-color: rgba(167, 139, 250, 0.34) !important;
  background:
    linear-gradient(90deg, var(--sidebar-row-active-strong), var(--sidebar-row-active)) !important;
  color: rgb(76, 29, 149) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.54) !important;
}

.sidebar-nav-icon {
  width: 2rem !important;
  height: 2rem !important;
