@keyframes mockSectionEnter {
  0% {
    opacity: 0;
    transform: translateY(10px) scale(0.992);
    filter: blur(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes mockPanelEnter {
  0% {
    opacity: 0;
    transform: translateY(14px);
    filter: blur(5px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes mockCardEnter {
  0% {
    opacity: 0;
    transform: translateY(16px) scale(0.985);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes mockChipPop {
  0% {
    opacity: 0;
    transform: translateY(5px) scale(0.94);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes mockProgressWake {
  0% {
    opacity: 0.66;
    transform: scaleX(0.28);
    filter: saturate(0.8);
  }
  100% {
    opacity: 1;
    transform: scaleX(1);
    filter: saturate(1);
  }
}

