/* Classic mode warning modal. */
.mock-classic-lock-card {
  border-color: rgba(56, 189, 248, 0.46) !important;
  background:
    linear-gradient(135deg, rgba(15, 23, 42, 0.98), rgba(30, 41, 59, 0.94) 48%, rgba(8, 47, 73, 0.82)),
    repeating-linear-gradient(-32deg, rgba(56, 189, 248, 0.055) 0 1px, transparent 1px 18px) !important;
  color: rgb(248, 250, 252);
  box-shadow:
    0 10px 0 rgba(2, 6, 23, 0.48),
    0 32px 70px rgba(2, 6, 23, 0.52),
    inset 0 2px 0 rgba(255, 255, 255, 0.1),
    inset 0 0 0 4px rgba(14, 165, 233, 0.08) !important;
}

.mock-classic-lock-card::before,
.mock-classic-lock-card::after {
  content: '';
  position: absolute;
  width: 1.65rem;
  height: 1.65rem;
  pointer-events: none;
  border-color: rgba(56, 189, 248, 0.66);
}

.mock-classic-lock-card::before {
  top: 0.7rem;
  left: 0.7rem;
  border-top: 2px solid;
  border-left: 2px solid;
  border-top-left-radius: 1rem;
}

.mock-classic-lock-card::after {
  right: 0.7rem;
  bottom: 0.7rem;
  border-right: 2px solid;
  border-bottom: 2px solid;
  border-bottom-right-radius: 1rem;
}

.mock-classic-lock-card__glow {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(120deg, rgba(56, 189, 248, 0.16), transparent 34%, rgba(99, 102, 241, 0.12) 68%, transparent 100%),
    linear-gradient(110deg, transparent 0 34%, rgba(255, 255, 255, 0.07) 46%, transparent 64%);
  pointer-events: none;
}

.mock-classic-lock-card__icon {
  width: 3.15rem;
  height: 3.15rem;
  border: 2px solid rgba(254, 215, 170, 0.42);
  border-radius: 1rem;
  background: linear-gradient(145deg, #fb7185, #f97316 48%, #dc2626);
  color: rgb(255, 255, 255);
  box-shadow:
    0 5px 0 rgba(127, 29, 29, 0.5),
    0 16px 28px rgba(220, 38, 38, 0.18),
    inset 0 2px 0 rgba(255, 255, 255, 0.24);
}

.mock-classic-lock-card__kicker {
  color: rgb(186, 230, 253);
  font-size: 0.68rem;
  font-weight: 950;
  letter-spacing: 0.18em;
  line-height: 1;
  text-transform: uppercase;
}

.mock-classic-lock-card__title {
  color: rgb(255, 255, 255);
  font-family: var(--font-display, inherit);
  font-size: clamp(1.25rem, 2.4vw, 1.75rem);
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1.08;
  text-shadow: 0 2px 0 rgba(2, 6, 23, 0.32);
}

.mock-classic-lock-card__text {
  color: rgb(226, 232, 240);
  font-size: 0.92rem;
  font-weight: 750;
  line-height: 1.42;
}

.mock-classic-lock-card__rules > div {
  display: flex;
  min-height: 3.25rem;
  align-items: center;
  gap: 0.6rem;
  border: 1px solid rgba(56, 189, 248, 0.18);
  border-radius: 1rem;
  background: rgba(2, 6, 23, 0.26);
  padding: 0.72rem 0.82rem;
  color: rgb(224, 242, 254);
  font-size: 0.8rem;
  font-weight: 850;
  line-height: 1.22;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.mock-classic-lock-card__rules svg {
  flex: 0 0 auto;
  color: rgb(56, 189, 248);
  filter: drop-shadow(0 0 8px rgba(14, 165, 233, 0.24));
}

.mock-classic-lock-card__cancel {
  border-color: rgba(148, 163, 184, 0.26) !important;
  background: rgba(15, 23, 42, 0.62) !important;
  color: rgb(226, 232, 240) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 10px 20px rgba(2, 6, 23, 0.18) !important;
}

.mock-classic-lock-card__start {
  border: 1px solid rgba(191, 219, 254, 0.38) !important;
  background: linear-gradient(180deg, #60a5fa, #2563eb 52%, #4f46e5) !important;
  color: rgb(255, 255, 255) !important;
  font-weight: 950 !important;
  text-shadow: 0 2px 0 rgba(30, 41, 59, 0.28);
  box-shadow:
    0 5px 0 rgba(30, 64, 175, 0.54),
