/* Mock exam launch animation. */
.mock-exam-launch {
  --mock-launch-accent: #7c3aed;
  --mock-launch-accent-2: #0ea5e9;
  --mock-launch-accent-3: #14b8a6;
  animation: mockExamLaunchBackdrop 560ms ease-out both;
  perspective: 1400px;
}

.mock-exam-launch--timer {
  --mock-launch-accent: #e11d48;
  --mock-launch-accent-2: #f97316;
  --mock-launch-accent-3: #c026d3;
}

.mock-exam-launch__field,
.mock-exam-launch__ray,
.mock-exam-launch__spark {
  pointer-events: none;
}

.mock-exam-launch__field {
  position: absolute;
  inset: 0;
  overflow: hidden;
  opacity: 0;
  animation: mockExamLaunchField 980ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.mock-exam-launch__field::before,
.mock-exam-launch__field::after {
  content: '';
  position: absolute;
  inset: -18%;
  background:
    conic-gradient(
      from 116deg at 50% 50%,
      transparent 0 18deg,
      color-mix(in srgb, var(--mock-launch-accent) 34%, transparent) 28deg,
      transparent 42deg 150deg,
      color-mix(in srgb, var(--mock-launch-accent-2) 28%, transparent) 166deg,
      transparent 184deg 360deg
    );
  filter: blur(18px);
  transform: scale(0.76) rotate(-7deg);
  animation: mockExamLaunchHalo 1120ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.mock-exam-launch__field::after {
  inset: -8%;
  background:
    linear-gradient(90deg, transparent, color-mix(in srgb, var(--mock-launch-accent-2) 32%, transparent), transparent),
    linear-gradient(0deg, transparent, color-mix(in srgb, var(--mock-launch-accent) 22%, transparent), transparent);
  filter: blur(26px);
  transform: scaleX(0.18) scaleY(1.2);
  animation: mockExamLaunchCross 760ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.mock-exam-launch__ray {
  position: absolute;
  left: 50%;
  top: 50%;
  height: 1px;
  width: min(72vw, 62rem);
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--mock-launch-accent-2) 62%, white 12%), transparent);
  opacity: 0;
  transform-origin: center;
  animation: mockExamLaunchRay 760ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.mock-exam-launch__ray--one {
  transform: translate(-50%, -50%) rotate(-8deg) scaleX(0.18);
}

.mock-exam-launch__ray--two {
  width: min(58vw, 48rem);
  animation-delay: 80ms;
  transform: translate(-50%, -50%) rotate(12deg) scaleX(0.16);
}

.mock-exam-launch__spark {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0.5rem;
  height: 0.5rem;
  border: 1px solid color-mix(in srgb, var(--mock-launch-accent-2) 74%, white 20%);
  opacity: 0;
  transform: translate(-50%, -50%) rotate(45deg) scale(0.4);
  animation: mockExamLaunchSpark 920ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.mock-exam-launch__spark--one {
  --mock-launch-spark-x: -19rem;
  --mock-launch-spark-y: -8rem;
  animation-delay: 120ms;
}

.mock-exam-launch__spark--two {
  --mock-launch-spark-x: 22rem;
  --mock-launch-spark-y: -5rem;
  width: 0.42rem;
  height: 0.42rem;
  animation-delay: 180ms;
}

.mock-exam-launch__spark--three {
  --mock-launch-spark-x: 15rem;
  --mock-launch-spark-y: 10rem;
  width: 0.38rem;
  height: 0.38rem;
  animation-delay: 240ms;
}

.mock-exam-launch .mock-exam-modal-card {
  transform-origin: 50% 52%;
  will-change: transform, opacity, clip-path;
  animation: mockExamModalOpen 720ms cubic-bezier(0.16, 0.84, 0.25, 1) both;
}

.mock-exam-modal-card__launch-glow,
.mock-exam-modal-card__launch-sheen {
  pointer-events: none;
  position: absolute;
  z-index: 0;
}

.mock-exam-modal-card__launch-glow {
  inset: -1px;
  border-radius: inherit;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--mock-launch-accent) 22%, transparent), transparent 28% 72%, color-mix(in srgb, var(--mock-launch-accent-2) 20%, transparent)),
    linear-gradient(180deg, color-mix(in srgb, var(--mock-launch-accent-2) 20%, transparent), transparent 34%);
  opacity: 0;
  animation: mockExamModalGlow 1100ms ease-out both;
}

.mock-exam-modal-card__launch-sheen {
  inset: -35% -28%;
  background:
    linear-gradient(112deg, transparent 0 38%, rgba(255, 255, 255, 0.48) 49%, rgba(255, 255, 255, 0.12) 54%, transparent 66%);
  mix-blend-mode: screen;
  opacity: 0;
  transform: translate3d(-70%, 0, 0) rotate(6deg);
  animation: mockExamModalSheen 940ms cubic-bezier(0.16, 0.84, 0.25, 1) 120ms both;
}

.mock-exam-launch .mock-exam-modal-card__header,
