/* Yandex Board-inspired tool rail. It intentionally stays light in every app theme. */
.board-tool-rail {
  position: absolute;
  left: 12px;
  top: 50%;
  z-index: 36;
  display: flex;
  width: 48px;
  max-height: calc(100% - 24px);
  flex-direction: column;
  align-items: center;
  gap: 3px;
  overflow: visible;
  padding: 5px;
  border: 1px solid rgba(226, 232, 240, 0.96);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.98);
  color: #25272c;
  box-shadow:
    0 12px 28px rgba(15, 23, 42, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
  scrollbar-width: none;
  isolation: isolate;
  transform: translateY(-50%);
}

.board-tool-rail::-webkit-scrollbar {
  display: none;
}

.board-fullscreen-corner {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 40;
  display: inline-flex;
  width: 38px;
  height: 38px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(226, 232, 240, 0.98);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.98);
  color: #2f3136;
  box-shadow:
    0 9px 22px rgba(15, 23, 42, 0.11),
    inset 0 1px 0 rgba(255, 255, 255, 0.98);
  transition: color 130ms ease, background-color 130ms ease, transform 130ms ease;
}

.board-fullscreen-corner:hover {
  background: #f1eafe;
  color: #7c3aed;
}

.board-fullscreen-corner:active {
  transform: scale(0.94);
}

.board-fullscreen-corner:focus-visible {
  outline: 2px solid rgba(139, 92, 246, 0.72);
  outline-offset: 2px;
}

html[data-theme='dark'] .board-fullscreen-corner {
  border-color: rgba(226, 232, 240, 0.98);
  background: rgba(255, 255, 255, 0.98);
  color: #2f3136;
}

html[data-theme='dark'] .board-fullscreen-corner:hover {
  background: #f1eafe;
  color: #7c3aed;
}

.board-tool-rail__button {
  position: relative;
  display: inline-flex;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
