/* Image selection and actions mirror the compact Yandex Board object controls. */
.board-image-selection-layer {
  position: absolute;
  inset: 0;
  z-index: 41;
  pointer-events: none;
}

.board-image-selection {
  position: absolute;
  box-sizing: border-box;
  border: 2px solid #8b5cf6;
  pointer-events: none;
}

.board-image-selection.is-locked {
  border-style: dashed;
}

.board-image-selection__handle {
  position: absolute;
  width: 0.68rem;
  height: 0.68rem;
  padding: 0;
  border: 2px solid #8b5cf6;
  border-radius: 0.16rem;
  background: #ffffff;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.14);
  pointer-events: auto;
  touch-action: none;
}

.board-image-selection__handle--nw {
  left: 0;
  top: 0;
  cursor: nwse-resize;
  transform: translate(-55%, -55%);
}

.board-image-selection__handle--n {
  left: 50%;
  top: 0;
  cursor: ns-resize;
  transform: translate(-50%, -55%);
}

.board-image-selection__handle--ne {
  right: 0;
  top: 0;
  cursor: nesw-resize;
  transform: translate(55%, -55%);
}

.board-image-selection__handle--e {
  right: 0;
  top: 50%;
  cursor: ew-resize;
  transform: translate(55%, -50%);
}

.board-image-selection__handle--se {
  right: 0;
  bottom: 0;
  cursor: nwse-resize;
  transform: translate(55%, 55%);
}

.board-image-selection__handle--s {
  left: 50%;
  bottom: 0;
  cursor: ns-resize;
  transform: translate(-50%, 55%);
}

.board-image-selection__handle--sw {
  left: 0;
  bottom: 0;
  cursor: nesw-resize;
  transform: translate(-55%, 55%);
}

.board-image-selection__handle--w {
  left: 0;
  top: 50%;
  cursor: ew-resize;
  transform: translate(-55%, -50%);
}

.board-image-selection__handle:focus-visible {
  outline: 2px solid rgba(139, 92, 246, 0.62);
  outline-offset: 2px;
}

.board-image-selection__lock {
  position: absolute;
  right: -0.7rem;
  top: -0.7rem;
  display: grid;
  width: 1.45rem;
  height: 1.45rem;
  place-items: center;
  border: 2px solid #8b5cf6;
  border-radius: 999px;
  background: #ffffff;
  color: #202124;
  box-shadow: 0 2px 7px rgba(15, 23, 42, 0.16);
}

.board-image-toolbar {
  position: absolute;
  z-index: 4;
  display: flex;
  align-items: center;
  pointer-events: auto;
  transform: translate(-50%, -100%);
}

.board-image-toolbar.is-below {
  transform: translate(-50%, 0);
}

.board-image-toolbar__pill {
  display: flex;
  height: 2.9rem;
  align-items: stretch;
  overflow: visible;
  border: 1px solid rgba(226, 232, 240, 0.98);
  border-radius: 0.92rem;
  background: rgba(255, 255, 255, 0.99);
