    rgba(15, 23, 42, 0.62);
  backdrop-filter: blur(10px) saturate(112%);
  -webkit-backdrop-filter: blur(10px) saturate(112%);
}

.student-test-workspace {
  height: min(94dvh, 920px);
  max-height: 94dvh !important;
  padding: 0 !important;
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 28px;
  color: #172033;
  background: #f6f7fb;
  box-shadow:
    0 34px 90px rgba(15, 23, 42, 0.34),
    0 8px 28px rgba(15, 23, 42, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.student-test-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 15px 20px 13px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(255, 255, 255, 0.94);
}

.student-test-header-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(139, 92, 246, 0.2);
  border-radius: 14px;
  color: #7c3aed;
  background: linear-gradient(145deg, #f5f3ff, #ede9fe);
  box-shadow: inset 0 1px 0 #fff, 0 7px 18px rgba(124, 58, 237, 0.12);
}

.student-test-title {
  max-width: min(56vw, 650px);
  color: #172033;
  font-size: 15px;
  font-weight: 800;
  line-height: 1.25;
}

.student-test-xp-badge {
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(139, 92, 246, 0.22);
  border-radius: 999px;
  padding: 3px 8px;
  color: #7c3aed;
  background: #f5f3ff;
  font-size: 10px;
  font-weight: 800;
}

.student-test-progress-summary {
  width: 132px;
  color: #64748b;
}

.student-test-progress-summary strong {
  color: #5b21b6;
}

.student-test-progress-track {
  height: 5px;
