  align-items: center;
  justify-content: center;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 12px;
  color: #475569;
  background: #f8fafc;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.student-test-close:hover {
  border-color: rgba(244, 63, 94, 0.24);
  color: #e11d48;
  background: #fff1f2;
  transform: translateY(-1px);
}

.student-test-side-nav {
  --student-test-side-nav-rgb: 168, 85, 247;
  --student-test-side-nav-hover-rgb: 126, 34, 206;
  --student-test-side-nav-fill: #a855f7;
  --student-test-side-nav-peek-bg: #f3e8ff;
  --student-test-side-nav-peek-border: #d8b4fe;
  --student-test-side-nav-hover-bg: #a855f7;
  --student-test-side-nav-icon-x: 0px;
  --student-test-side-nav-peek-shift: 0px;
  --student-test-side-nav-hover-shift: 0px;
  position: absolute;
  top: calc(50% + 36px);
  z-index: 18;
  display: inline-flex;
  width: 52px;
  height: 170px;
  align-items: center;
  justify-content: center;
  isolation: isolate;
  overflow: visible;
  border: 0;
  color: rgba(var(--student-test-side-nav-rgb), 0.92);
  background: transparent;
  box-shadow: none;
  opacity: 0.88;
  outline: none;
  transform: translateY(-50%) translateX(0) scale(1);
  will-change: transform, opacity;
  transition:
    opacity 220ms ease,
    transform 520ms cubic-bezier(0.18, 1.3, 0.28, 1),
    color 220ms ease,
    filter 260ms ease;
}

.student-test-side-nav::before,
.student-test-side-nav::after {
  content: "";
  position: absolute;
  pointer-events: none;
  transition:
    opacity 420ms ease,
    transform 520ms cubic-bezier(0.18, 1.35, 0.28, 1),
    filter 420ms ease,
    background 420ms ease;
}

.student-test-side-nav::before {
  z-index: -2;
  top: 50%;
  width: 190px;
  height: 240px;
  border-radius: 999px;
  background:
    radial-gradient(ellipse at center, rgba(var(--student-test-side-nav-rgb), 0.34), rgba(var(--student-test-side-nav-rgb), 0.17) 38%, transparent 72%);
  filter: blur(26px);
  opacity: 0.68;
  transform: translateY(-50%) scale(0.9);
}

.student-test-side-nav::after {
  z-index: -1;
  top: 50%;
  width: 96px;
  height: 170px;
  border-radius: 999px;
  background:
    radial-gradient(ellipse at center, rgba(255, 255, 255, 0.72), rgba(var(--student-test-side-nav-rgb), 0.12) 48%, transparent 74%);
  filter: blur(12px);
  opacity: 0.36;
  transform: translateY(-50%) scale(0.92);
}

.student-test-side-nav__glow,
.student-test-side-nav__sheen {
  position: absolute;
  top: 50%;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-50%) scale(0.96);
  transition:
    opacity 520ms ease,
    transform 560ms cubic-bezier(0.18, 1.28, 0.28, 1),
    filter 520ms ease;
}

.student-test-side-nav__glow {
  z-index: -2;
  width: 190px;
  height: 240px;
  border-radius: 999px;
  background:
    radial-gradient(ellipse at center, rgba(var(--student-test-side-nav-hover-rgb), 0.48), rgba(var(--student-test-side-nav-hover-rgb), 0.23) 38%, transparent 72%);
  filter: blur(28px);
}

.student-test-side-nav__sheen {
  z-index: -1;
  width: 96px;
  height: 170px;
  border-radius: 999px;
  background:
    radial-gradient(ellipse at center, rgba(255, 255, 255, 0.72), rgba(var(--student-test-side-nav-hover-rgb), 0.24) 48%, transparent 74%);
  filter: blur(12px);
}

.student-test-side-nav svg {
  position: relative;
  z-index: 1;
  transform: translateX(var(--student-test-side-nav-icon-x));
  filter:
    drop-shadow(0 8px 18px rgba(var(--student-test-side-nav-rgb), 0.34))
    drop-shadow(0 1px 2px rgba(255, 255, 255, 0.75));
  transition:
    color 360ms ease,
    filter 360ms ease,
    transform 460ms cubic-bezier(0.18, 1.38, 0.28, 1);
}

.student-test-side-nav.is-solved {
  --student-test-side-nav-rgb: 0, 171, 99;
  --student-test-side-nav-hover-rgb: 0, 133, 77;
  --student-test-side-nav-fill: #00ab63;
  --student-test-side-nav-peek-bg: #dcfce7;
  --student-test-side-nav-peek-border: #86efac;
  --student-test-side-nav-hover-bg: #22c55e;
}

.student-test-side-nav.is-wrong {
  --student-test-side-nav-rgb: 248, 113, 113;
  --student-test-side-nav-hover-rgb: 220, 38, 38;
  --student-test-side-nav-fill: #f87171;
  --student-test-side-nav-peek-bg: #ffe4e6;
  --student-test-side-nav-peek-border: #fda4af;
  --student-test-side-nav-hover-bg: #f87171;
}

.student-test-side-nav.is-draft {
  --student-test-side-nav-rgb: 56, 189, 248;
  --student-test-side-nav-hover-rgb: 2, 132, 199;
  --student-test-side-nav-fill: #38bdf8;
  --student-test-side-nav-peek-bg: #e0f2fe;
  --student-test-side-nav-peek-border: #7dd3fc;
  --student-test-side-nav-hover-bg: #38bdf8;
}

.student-test-side-nav.is-pending {
  --student-test-side-nav-rgb: 168, 85, 247;
  --student-test-side-nav-hover-rgb: 126, 34, 206;
  --student-test-side-nav-fill: #a855f7;
  --student-test-side-nav-peek-bg: #f3e8ff;
  --student-test-side-nav-peek-border: #d8b4fe;
  --student-test-side-nav-hover-bg: #a855f7;
}

.student-test-side-nav--prev {
  --student-test-side-nav-shift: -13px;
  --student-test-side-nav-peek-shift: 0px;
  --student-test-side-nav-hover-shift: -2px;
  --student-test-side-nav-icon-x: -8px;
  left: 0.82rem;
  border-left: 0;
}

.student-test-side-nav--next {
  --student-test-side-nav-shift: 13px;
  --student-test-side-nav-peek-shift: 0px;
  --student-test-side-nav-hover-shift: 2px;
  --student-test-side-nav-icon-x: 8px;
  right: 0.82rem;
  border-right: 0;
}

.student-test-side-nav--prev::before {
  left: -128px;
}

.student-test-side-nav--prev .student-test-side-nav__glow {
  left: -128px;
}

.student-test-side-nav--prev::after {
  left: -54px;
}

.student-test-side-nav--prev .student-test-side-nav__sheen {
  left: -54px;
}

.student-test-side-nav--next::before {
  right: -128px;
}

.student-test-side-nav--next .student-test-side-nav__glow {
  right: -128px;
}

.student-test-side-nav--next::after {
  right: -54px;
}

.student-test-side-nav--next .student-test-side-nav__sheen {
  right: -54px;
}

.student-test-workspace:hover .student-test-side-nav:not(:disabled) {
  opacity: 1;
  color: rgb(var(--student-test-side-nav-rgb));
  filter: saturate(1.04);
  transform: translateY(-50%) translateX(var(--student-test-side-nav-peek-shift)) scale(1.01);
}

.student-test-workspace:hover .student-test-side-nav:not(:disabled)::before {
  opacity: 0.88;
  transform: translateY(-50%) scale(1);
}

.student-test-workspace:hover .student-test-side-nav:not(:disabled)::after {
  opacity: 0.5;
  transform: translateY(-50%) scale(1);
}

.student-test-side-nav:hover:not(:disabled),
.student-test-side-nav:focus-visible:not(:disabled) {
  opacity: 1 !important;
  color: rgb(var(--student-test-side-nav-hover-rgb));
  filter: saturate(1.16);
  transform: translateY(-50%) translateX(var(--student-test-side-nav-hover-shift)) scale(1.055);
}

.student-test-side-nav:hover:not(:disabled)::before,
.student-test-side-nav:focus-visible:not(:disabled)::before {
  opacity: 0.12;
  filter: blur(28px);
  transform: translateY(-50%) scale(1.08);
}

.student-test-side-nav:hover:not(:disabled)::after,
.student-test-side-nav:focus-visible:not(:disabled)::after {
  opacity: 0.08;
  transform: translateY(-50%) scale(1.08);
}

.student-test-side-nav:hover:not(:disabled) .student-test-side-nav__glow,
.student-test-side-nav:focus-visible:not(:disabled) .student-test-side-nav__glow {
  opacity: 0.76;
  transform: translateY(-50%) scale(1.08);
}

.student-test-side-nav:hover:not(:disabled) .student-test-side-nav__sheen,
.student-test-side-nav:focus-visible:not(:disabled) .student-test-side-nav__sheen {
  opacity: 0.46;
  transform: translateY(-50%) scale(1.08);
}

.student-test-side-nav:hover:not(:disabled) svg,
.student-test-side-nav:focus-visible:not(:disabled) svg {
  filter:
    drop-shadow(0 7px 18px rgba(var(--student-test-side-nav-hover-rgb), 0.36))
    drop-shadow(0 1px 2px rgba(15, 23, 42, 0.1));
  transform: translateX(var(--student-test-side-nav-icon-x)) scale(1.1);
}

.student-test-side-nav:active:not(:disabled) {
  transform: translateY(-50%) translateX(var(--student-test-side-nav-hover-shift)) scale(0.98);
}

.student-test-side-nav:active:not(:disabled)::before {
  opacity: 0.8;
  transform: translateY(-50%) scale(0.96);
}

.student-test-side-nav:active:not(:disabled)::after {
  opacity: 0.36;
  transform: translateY(-50%) scale(0.96);
}

.student-test-side-nav:active:not(:disabled) .student-test-side-nav__glow,
.student-test-side-nav:active:not(:disabled) .student-test-side-nav__sheen {
  opacity: 0;
  transform: translateY(-50%) scale(0.96);
}

.student-test-side-nav:disabled {
  pointer-events: none;
  opacity: 0;
  transform: translateY(-50%) translateX(0) scale(0.82);
}

.student-test-navigation {
  padding: 10px 20px 9px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(248, 250, 252, 0.96);
}

.student-test-question-caption {
  color: #475569;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.student-test-mobile-progress {
  color: #7c3aed;
  font-size: 11px;
  font-weight: 700;
}

.student-test-question-list {
  margin-left: -6px;
  margin-right: -6px;
  padding: 6px 6px 7px;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(139, 92, 246, 0.38) transparent;
}

.student-test-question-list::-webkit-scrollbar {
  height: 4px;
}

.student-test-question-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(139, 92, 246, 0.36);
}

.student-test-question-button {
  display: inline-flex;
  width: 34px;
  height: 34px;
  min-width: 34px;
  flex: 0 0 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid #d7dce5;
  border-radius: 10px;
  color: #64748b;
  background: #fff;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.05);
  font-size: 12px;
  font-weight: 800;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.student-test-question-button:hover {
  border-color: #c4b5fd;
  color: #7c3aed;
  background: #faf8ff;
  transform: translateY(-1px);
}

.student-test-question-button.is-current {
  border-color: #8b5cf6;
  color: #fff;
  background: linear-gradient(145deg, #8b5cf6, #7c3aed);
  box-shadow: 0 5px 14px rgba(124, 58, 237, 0.3), 0 0 0 3px rgba(139, 92, 246, 0.13);
}

.student-test-question-button.is-correct:not(.is-current) {
  border-color: #a7f3d0;
  color: #047857;
  background: #ecfdf5;
}

.student-test-question-button.is-draft:not(.is-current) {
  border-color: #7dd3fc;
  color: #0284c7;
  background: #e0f2fe;
  box-shadow: 0 4px 12px rgba(14, 165, 233, 0.13);
}

.student-test-question-button.is-current.is-correct {
  border-color: #10b981;
  background: linear-gradient(145deg, #10b981, #059669);
  box-shadow: 0 5px 14px rgba(5, 150, 105, 0.26), 0 0 0 3px rgba(16, 185, 129, 0.13);
}

.student-test-question-button.is-current.is-draft {
  border-color: #0ea5e9;
  color: #fff;
  background: linear-gradient(145deg, #38bdf8, #0ea5e9);
  box-shadow: 0 5px 14px rgba(14, 165, 233, 0.25), 0 0 0 3px rgba(56, 189, 248, 0.14);
}

.student-test-question-button.is-wrong:not(.is-current) {
  border-color: #fecdd3;
  color: #e11d48;
  background: #fff1f2;
}

.student-test-question-button.is-current.is-wrong {
  border-color: #f43f5e;
  background: linear-gradient(145deg, #f43f5e, #e11d48);
  box-shadow: 0 5px 14px rgba(225, 29, 72, 0.24), 0 0 0 3px rgba(244, 63, 94, 0.12);
}

.student-test-scroll {
  overscroll-behavior: contain;
  padding: 18px 20px 24px;
  background:
    radial-gradient(circle at 100% 0%, rgba(139, 92, 246, 0.055), transparent 30%),
    linear-gradient(180deg, #f7f8fc 0%, #f3f5f9 100%);
  scrollbar-width: thin;
  scrollbar-color: rgba(100, 116, 139, 0.35) transparent;
}

.student-test-content {
  display: grid;
  gap: 14px;
}

.student-test-question-panel,
.student-test-answer-panel,
.student-test-code-panel {
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.055);
}

.student-test-question-panel {
  padding: 18px;
}

.student-test-question-panel > :last-child,
.student-test-question-panel > :last-child > :last-child {
  margin-bottom: 0;
}

.student-test-answer-panel {
  padding: 16px 18px;
}

.student-test-answer-panel input,
.student-test-answer-panel textarea {
  min-height: 46px;
  background: #f8fafc;
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.student-test-answer-panel input:focus,
.student-test-answer-panel textarea:focus {
  border-color: #8b5cf6;
  background: #fff;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.12);
}

.student-test-code-panel {
  margin-bottom: 2px;
  overflow: hidden;
}

.student-test-target {
  border: 1px solid rgba(139, 92, 246, 0.18);
  color: #6d28d9;
  background: linear-gradient(135deg, rgba(245, 243, 255, 0.96), rgba(250, 245, 255, 0.94));
}

.student-test-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 20px calc(12px + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 -10px 30px rgba(15, 23, 42, 0.055);
}

.student-test-primary-action {
  position: relative;
  overflow: hidden;
  box-shadow: 0 9px 22px rgba(124, 58, 237, 0.2);
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
}

/* Student test motion system */
.student-test-modal-backdrop {
  animation: studentTestBackdropIn 0.34s ease-out both;
}

.student-test-modal-backdrop.is-closing {
  pointer-events: none;
  animation: studentTestBackdropOut 0.28s ease-in both;
}

.student-test-workspace--animated {
  isolation: isolate;
  animation: studentTestWorkspaceIn 0.52s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.student-test-workspace--animated.is-closing {
  animation: studentTestWorkspaceOut 0.34s cubic-bezier(0.55, 0, 1, 0.45) both;
}

.student-test-workspace--animated::before {
  position: absolute;
  z-index: 0;
  width: 340px;
  height: 340px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(168, 85, 247, 0.13), transparent 68%);
  content: '';
  pointer-events: none;
  right: -170px;
  top: 12%;
  animation: studentTestAmbientOrb 9s ease-in-out infinite alternate;
}

.student-test-workspace--animated > * {
  position: relative;
  z-index: 1;
}

.student-test-workspace--animated > .student-test-side-nav {
  position: absolute;
  z-index: 18;
}

.student-test-header > * {
  animation: studentTestHeaderItemIn 0.46s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.student-test-header > *:last-child {
  animation-delay: 80ms;
}

.student-test-header-icon {
  position: relative;
  animation: studentTestHeaderIconFloat 4.8s ease-in-out 0.7s infinite;
}

.student-test-header-icon::after {
  position: absolute;
  inset: -5px;
  border: 1px solid rgba(139, 92, 246, 0.22);
  border-radius: 18px;
  content: '';
  pointer-events: none;
  animation: studentTestIconRing 3.4s ease-out 0.8s infinite;
}

.student-test-xp-badge {
  position: relative;
  overflow: hidden;
  animation: studentTestBadgePop 0.55s cubic-bezier(0.2, 1.45, 0.35, 1) 0.18s both;
}

.student-test-xp-badge::after {
  position: absolute;
  inset: -45% auto -45% -55%;
  width: 42%;
  background: linear-gradient(100deg, transparent, rgba(255, 255, 255, 0.82), transparent);
  content: '';
  pointer-events: none;
  transform: skewX(-18deg);
  animation: studentTestBadgeShine 4.2s ease-in-out 1.2s infinite;
}

.student-test-progress-track {
  position: relative;
  animation: studentTestProgressTrackIn 0.45s ease-out 0.15s both;
}

.student-test-progress-fill {
  position: relative;
  overflow: hidden;
  transition: width 0.62s cubic-bezier(0.16, 1, 0.3, 1);
}

.student-test-progress-fill::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 10%, rgba(255, 255, 255, 0.68) 48%, transparent 88%);
  content: '';
  transform: translateX(-110%);
  animation: studentTestProgressShine 2.8s ease-in-out 0.5s infinite;
}

.student-test-close:hover svg {
  animation: studentTestCloseWiggle 0.38s ease both;
}

.student-test-navigation {
  animation: studentTestNavigationIn 0.44s cubic-bezier(0.16, 1, 0.3, 1) 0.08s both;
}

.student-test-question-caption,
.student-test-mobile-progress {
  animation: studentTestSoftFadeIn 0.42s ease-out 0.16s both;
}

.student-test-question-button {
  position: relative;
}

.student-test-question-button:active {
  transform: translateY(1px) scale(0.92);
}

.student-test-question-button.is-current::after {
  position: absolute;
  inset: -5px;
  border: 2px solid currentColor;
  border-radius: 14px;
  content: '';
  opacity: 0;
  pointer-events: none;
  animation: studentTestCurrentQuestionRing 2.2s ease-out infinite;
}

.student-test-question-button.is-current.is-correct {
  animation: studentTestCorrectQuestionPop 0.58s cubic-bezier(0.18, 1.45, 0.3, 1) backwards;
}

.student-test-question-button.is-current.is-wrong {
  animation: studentTestWrongQuestionShake 0.48s ease backwards;
}

.student-test-question-button svg {
  animation: studentTestCheckDraw 0.45s cubic-bezier(0.2, 1.4, 0.35, 1) both;
}

.student-test-scroll {
  background-size: 135% 135%, 100% 100%;
  animation: studentTestCanvasDrift 12s ease-in-out infinite alternate;
}

.student-test-content--question-enter {
  animation: studentTestContentIn 0.42s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.student-test-target {
  overflow: hidden;
  position: relative;
  animation: studentTestTargetIn 0.46s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.student-test-target::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 20%, rgba(255, 255, 255, 0.72) 48%, transparent 76%);
  content: '';
  pointer-events: none;
  transform: translateX(-110%);
  animation: studentTestTargetShine 4.6s ease-in-out 1.1s infinite;
}

.student-test-target span {
  animation: studentTestChipIn 0.35s cubic-bezier(0.2, 1.4, 0.35, 1) backwards;
  animation-delay: calc(0.12s + (var(--student-test-item-index, 0) * 45ms));
}

.student-test-panel-enter {
  transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.25s ease;
}

.student-test-question-panel {
  animation: studentTestPanelIn 0.48s cubic-bezier(0.16, 1, 0.3, 1) 20ms backwards;
}

.student-test-answer-panel {
  position: relative;
  overflow: hidden;
  animation: studentTestPanelIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) 90ms backwards;
}

.student-test-code-panel {
  animation: studentTestPanelIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) 150ms backwards;
}

.student-test-question-panel:hover,
.student-test-code-panel:hover,
.student-test-answer-panel--pending:hover {
  border-color: rgba(139, 92, 246, 0.34);
  box-shadow: 0 13px 34px rgba(76, 29, 149, 0.09);
  transform: translateY(-1px);
}

.student-test-screenshot {
  width: 100%;
  max-width: 100%;
  aspect-ratio: var(--student-test-image-aspect, 3.2);
  position: relative;
  opacity: 1;
  display: grid;
  place-items: center;
  border-color: rgba(148, 163, 184, 0.2);
  background: #fff;
  animation: studentTestMediaIn 0.55s cubic-bezier(0.16, 1, 0.3, 1) backwards;
  animation-delay: calc(0.08s + (var(--student-test-item-index, 0) * 70ms));
  transition:
    aspect-ratio 0.42s cubic-bezier(0.16, 1, 0.3, 1),
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.student-test-screenshot::before {
  position: absolute;
  z-index: 1;
  inset: 0;
  background:
    linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, 0.7) 48%, transparent 66%),
    linear-gradient(135deg, rgba(226, 232, 240, 0.84), rgba(241, 245, 249, 0.96));
  background-size: 220% 100%, 100% 100%;
  content: '';
  opacity: 1;
  pointer-events: none;
  transition: opacity 0.34s ease;
  animation: studentTestImageSkeleton 1.35s ease-in-out infinite;
}

.student-test-screenshot.is-loaded::before {
  opacity: 0;
  animation: none;
}

.student-test-screenshot__loader {
  position: absolute;
  z-index: 2;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  color: #64748b;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.01em;
  opacity: 1;
  pointer-events: none;
  transition: opacity 0.28s ease, visibility 0s linear 0s;
}

.student-test-screenshot__loader svg {
  color: #8b5cf6;
  animation: studentTestImageLoaderSpin 1s linear infinite;
}

.student-test-screenshot.is-loaded .student-test-screenshot__loader {
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.28s ease, visibility 0s linear 0.28s;
}

.student-test-screenshot::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(112deg, transparent 25%, rgba(255, 255, 255, 0.18) 50%, transparent 75%);
  content: '';
  opacity: 0;
  pointer-events: none;
  transform: translateX(-100%);
  transition: opacity 0.2s ease;
}

.student-test-screenshot:hover::after {
  opacity: 1;
  animation: studentTestMediaShine 0.85s ease both;
}

.student-test-screenshot img {
  grid-area: 1 / 1;
  width: 100%;
  height: 100%;
  max-height: 100%;
  opacity: 0;
  transform: scale(0.992);
  transition: opacity 0.36s ease, transform 0.42s cubic-bezier(0.16, 1, 0.3, 1), filter 0.3s ease;
}

.student-test-screenshot.is-loaded img {
  opacity: 1;
  transform: scale(1);
}

.student-test-screenshot:hover img {
  filter: saturate(1.04) contrast(1.02);
  transform: scale(1.012);
}

.student-test-file {
  opacity: 1;
  animation: studentTestFileIn 0.4s ease-out backwards;
  animation-delay: calc(0.12s + (var(--student-test-item-index, 0) * 55ms));
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}

.student-test-file:hover {
  box-shadow: 0 8px 18px rgba(124, 58, 237, 0.1);
  transform: translateX(3px);
}

.student-test-file svg {
  transition: transform 0.22s ease;
}

.student-test-file:hover svg {
  transform: translateY(2px) scale(1.08);
}

.student-test-solved-label {
  animation: studentTestSolvedLabelIn 0.55s cubic-bezier(0.2, 1.4, 0.35, 1) both;
}

.student-test-question-text {
  animation: studentTestQuestionTextIn 0.48s ease-out 0.09s both;
}

.student-test-answer-panel input,
.student-test-answer-panel textarea,
.student-test-solved-answer {
  animation: studentTestAnswerFieldIn 0.42s ease-out backwards;
  animation-delay: calc(var(--student-test-item-index, 0) * 35ms);
}

.student-test-answer-panel input:hover:not(:disabled),
.student-test-answer-panel textarea:hover:not(:disabled) {
  border-color: rgba(139, 92, 246, 0.48);
  transform: translateY(-1px);
}

.student-test-answer-panel input:focus,
.student-test-answer-panel textarea:focus {
  transform: translateY(-1px) scale(1.002);
}

.student-test-answer-paste-hint {
  display: grid;
  gap: 4px;
  margin-top: -4px;
  border: 1px solid rgba(139, 92, 246, 0.16);
  border-radius: 10px;
  padding: 8px 9px;
  background: rgba(248, 250, 252, 0.86);
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
}

.student-test-answer-paste-hint strong,
.teacher-question-editor__answer-paste-hint strong {
  color: #334155;
  font-size: 11px;
  font-weight: 800;
}

.student-test-answer-paste-hint code,
.teacher-question-editor__answer-paste-hint code {
  width: fit-content;
  border-radius: 8px;
  padding: 5px 7px;
  background: rgba(15, 23, 42, 0.06);
  color: #475569;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 10px;
  line-height: 1.35;
}

.student-test-answer-panel--correct {
  border-color: rgba(16, 185, 129, 0.42);
  animation: studentTestAnswerCorrect 0.68s cubic-bezier(0.16, 1, 0.3, 1) backwards;
}

.student-test-answer-panel--correct::before {
  position: absolute;
  inset: -70%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 28% 38%, rgba(52, 211, 153, 0.25) 0 2px, transparent 3px),
    radial-gradient(circle at 66% 22%, rgba(139, 92, 246, 0.22) 0 2px, transparent 3px),
    radial-gradient(circle at 72% 70%, rgba(34, 211, 238, 0.2) 0 2px, transparent 3px),
    radial-gradient(circle, rgba(16, 185, 129, 0.16), transparent 58%);
  content: '';
  pointer-events: none;
  animation: studentTestSuccessBurst 0.9s ease-out both;
}

.student-test-answer-panel--wrong {
  border-color: rgba(244, 63, 94, 0.34);
  animation: studentTestAnswerWrong 0.48s ease backwards;
}

.student-test-result-feedback {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  padding: 4px 9px;
  font-weight: 800;
}

.student-test-result-feedback.is-correct {
  background: rgba(16, 185, 129, 0.1);
  animation: studentTestResultCorrect 0.55s cubic-bezier(0.2, 1.5, 0.35, 1) both;
}

.student-test-result-feedback.is-wrong {
  background: rgba(244, 63, 94, 0.08);
  animation: studentTestResultWrong 0.45s ease both;
}

.student-test-history {
  transition: border-color 0.22s ease, background 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease;
}

.student-test-history:hover {
  border-color: rgba(139, 92, 246, 0.3);
  box-shadow: 0 7px 18px rgba(76, 29, 149, 0.07);
}

.student-test-history-summary {
  transition: color 0.2s ease, transform 0.2s ease;
}

.student-test-history-summary:active {
  transform: scale(0.992);
}

.student-test-history-icon {
  transition: transform 0.32s cubic-bezier(0.2, 1.35, 0.35, 1);
}

.student-test-history[open] .student-test-history-icon {
  transform: rotate(-18deg) scale(1.14);
}

.student-test-history[open] > div {
  animation: studentTestDetailsOpen 0.32s ease-out both;
}

.student-test-history-entry {
  opacity: 1;
  animation: studentTestHistoryEntryIn 0.38s ease-out backwards;
  animation-delay: calc(var(--student-test-item-index, 0) * 45ms);
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.student-test-history-entry:hover {
  border-color: rgba(139, 92, 246, 0.28);
  box-shadow: 0 6px 15px rgba(76, 29, 149, 0.08);
  transform: translateX(2px);
}

.student-test-code-launch-card {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 58px;
  padding: 11px 13px 11px 15px;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96)),
    linear-gradient(120deg, rgba(139, 92, 246, 0.08), rgba(14, 165, 233, 0.08));
}

.student-test-code-launch-card::before {
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 0%, rgba(139, 92, 246, 0.08) 48%, transparent 100%);
  content: '';
  opacity: 0;
  pointer-events: none;
  transform: translateX(-40%);
  transition: opacity 0.22s ease;
}

.student-test-code-launch-card:hover::before {
  opacity: 1;
  animation: studentTestCodeLaunchSweep 1.1s ease both;
}

.student-test-code-launch-card__main {
  position: relative;
  z-index: 1;
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 11px;
}

.student-test-code-launch-card__icon {
  display: inline-flex;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(139, 92, 246, 0.18);
  border-radius: 12px;
  color: #7c3aed;
  background: linear-gradient(145deg, #f5f3ff, #eef2ff);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.92), 0 8px 18px rgba(124, 58, 237, 0.1);
}

.student-test-code-launch-card__title {
  color: #172033;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.15;
}

.student-test-code-launch-card__meta {
  margin-top: 2px;
  overflow: hidden;
  color: #64748b;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-test-code-launch-card__button {
  position: relative;
  z-index: 1;
  display: inline-flex;
  min-height: 36px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid rgba(124, 58, 237, 0.22);
  border-radius: 12px;
  padding: 0 12px;
  color: #fff;
  background: linear-gradient(135deg, #7c3aed, #a855f7);
  box-shadow: 0 10px 22px rgba(124, 58, 237, 0.23);
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.student-test-code-launch-card__button:hover {
  border-color: rgba(124, 58, 237, 0.38);
  box-shadow: 0 14px 28px rgba(124, 58, 237, 0.3);
  transform: translateY(-1px);
}

.student-test-code-focus {
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: clamp(10px, 1.8vw, 20px);
  color: #e5edf9;
  transition: padding 0.72s cubic-bezier(0.16, 1, 0.3, 1);
}

.student-test-code-focus.is-closing {
  pointer-events: none;
}

.student-test-code-focus__scrim {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(8, 13, 26, 0.78);
  backdrop-filter: blur(18px) saturate(116%);
  -webkit-backdrop-filter: blur(18px) saturate(116%);
  cursor: default;
  animation: studentTestCodeFocusScrimIn 0.26s ease-out both;
}

.student-test-code-focus__scrim:active {
  transform: none;
}

.student-test-code-focus.is-closing .student-test-code-focus__scrim {
  animation: studentTestCodeFocusScrimOut 0.28s ease-in both;
}

.student-test-code-focus__workspace {
  position: relative;
  display: flex;
  width: min(1440px, 100%);
  height: calc(100dvh - clamp(20px, 3.6vw, 40px));
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.26);
  border-radius: 24px;
  background:
    linear-gradient(180deg, rgba(20, 30, 48, 0.98), rgba(8, 13, 26, 0.99)),
    linear-gradient(120deg, rgba(45, 212, 191, 0.1), rgba(168, 85, 247, 0.1));
  box-shadow:
    0 34px 100px rgba(0, 0, 0, 0.56),
    0 14px 45px rgba(15, 23, 42, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  animation: studentTestCodeFocusWorkspaceIn 0.54s cubic-bezier(0.16, 1, 0.3, 1) both;
  transition: border-color 0.24s ease, box-shadow 0.24s ease, transform 0.24s ease;
}

.student-test-code-focus__workspace::before {
  position: absolute;
  top: 0;
  right: 18px;
  left: 18px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(103, 232, 249, 0.72), rgba(196, 181, 253, 0.7), transparent);
  content: '';
  opacity: 0.9;
  pointer-events: none;
  transform: translateX(-36%);
  animation: studentTestCodeFocusEdgeSweep 5.8s ease-in-out infinite;
  z-index: 2;
}

.student-test-code-focus__workspace.is-side-by-side {
  width: calc(100vw - clamp(20px, 3.6vw, 40px));
  max-width: none;
}

.student-test-code-focus.is-closing .student-test-code-focus__workspace {
  animation: studentTestCodeFocusWorkspaceOut 0.36s cubic-bezier(0.55, 0, 1, 0.45) both;
}

.student-test-code-focus__header {
  display: flex;
  min-height: 62px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(13, 20, 34, 0.9);
  transition: background 0.24s ease, border-color 0.24s ease;
}

.student-test-code-focus__title {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}

.student-test-code-focus__title-icon {
  display: inline-flex;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(125, 211, 252, 0.22);
  border-radius: 14px;
  color: #67e8f9;
  background: linear-gradient(145deg, rgba(8, 47, 73, 0.75), rgba(59, 7, 100, 0.42));
  box-shadow: 0 12px 24px rgba(8, 47, 73, 0.28);
  transition: transform 0.24s cubic-bezier(0.2, 1.4, 0.35, 1), box-shadow 0.24s ease;
}

.student-test-code-focus__workspace:hover .student-test-code-focus__title-icon {
  box-shadow: 0 14px 28px rgba(8, 47, 73, 0.38);
  transform: translateY(-1px);
}

.student-test-code-focus__eyebrow {
  color: #93c5fd;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
  line-height: 1.1;
  text-transform: uppercase;
}

.student-test-code-focus__title h3 {
  margin: 2px 0 0;
  overflow: hidden;
  color: #f8fafc;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-test-code-focus__header-actions {
  display: flex;
  min-width: 0;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}

.student-test-code-focus__save-state {
  display: inline-flex;
  min-height: 30px;
  max-width: 36vw;
  align-items: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 999px;
  padding: 0 10px;
  overflow: hidden;
  color: #cbd5e1;
  background: rgba(15, 23, 42, 0.7);
  font-size: 11px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-test-code-focus__close {
  display: inline-flex;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 12px;
  color: #cbd5e1;
  background: rgba(30, 41, 59, 0.72);
}

.student-test-code-focus__close:hover {
  border-color: rgba(248, 113, 113, 0.38);
  color: #fecdd3;
  background: rgba(136, 19, 55, 0.28);
}

.student-test-code-focus__body {
  display: grid;
  min-height: 0;
  flex: 1 1 auto;
  grid-template-rows: minmax(170px, clamp(210px, 30vh, 340px)) minmax(0, 1fr);
  gap: 10px;
  padding: 10px;
}

.student-test-code-focus__body.is-side-by-side {
  grid-template-columns: minmax(360px, 0.88fr) minmax(0, 1.36fr);
  grid-template-rows: minmax(0, 1fr);
}

.student-test-code-focus__task {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 8px;
