  padding: 8px;
  background:
    linear-gradient(180deg, rgba(15, 23, 42, 0.97), rgba(11, 17, 32, 0.96)),
    linear-gradient(120deg, rgba(45, 212, 191, 0.08), rgba(168, 85, 247, 0.08));
  color: #e5edf9;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  animation: studentTestCodeFocusTaskIn 0.48s cubic-bezier(0.16, 1, 0.3, 1) 0.08s both;
  contain: layout paint;
