  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.student-test-code-focus__label {
  display: inline-flex;
  min-width: 0;
  max-width: min(520px, 76%);
  align-items: center;
  border-radius: 999px;
  padding: 4px 10px;
  overflow: hidden;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-test-code-focus__task-meta {
  flex: 0 0 auto;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
}

.student-test-code-focus__media {
  display: grid;
  min-height: 0;
  flex: 1 1 auto;
  place-items: stretch;
  overflow: hidden;
}

.student-test-code-focus__media.is-gallery {
  grid-template-columns: repeat(auto-fit, minmax(min(380px, 100%), 1fr));
  gap: 8px;
  overflow: auto;
}

.student-test-code-focus__body.is-side-by-side .student-test-code-focus__media.is-gallery {
