}

.student-test-code-focus__activity {
  display: flex;
  min-height: 0;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 10px 7px;
  border-right: 1px solid rgba(71, 85, 105, 0.6);
  background: #111827;
}

.student-test-code-focus__activity span {
  display: inline-flex;
  width: 34px;
  height: 34px;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: #94a3b8;
}

.student-test-code-focus__activity span.is-active {
  color: #67e8f9;
  background: rgba(8, 47, 73, 0.72);
  box-shadow: inset 3px 0 0 #22d3ee;
}

.student-test-code-focus__editor-pane {
  min-width: 0;
  min-height: 0;
