/* Teacher panel workspace */
.teacher-panel-shell {
  --teacher-panel-border: rgba(148, 163, 184, 0.22);
}

.teacher-panel-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(460px, 0.92fr);
  gap: 18px;
  align-items: end;
  margin-bottom: 16px;
}

.teacher-panel-title {
  line-height: 1.1;
}

.teacher-panel-hero--simple {
  grid-template-columns: 1fr;
}

.teacher-panel-subtitle {
  margin-top: 4px;
  font-size: 15px;
}

.teacher-panel-hero__stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.teacher-panel-stat {
  min-width: 0;
  border: 1px solid var(--teacher-panel-border);
  border-radius: 18px;
  padding: 10px 12px;
  background:
    radial-gradient(circle at 100% 0%, rgba(14, 165, 233, 0.1), transparent 42%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.88));
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}

.teacher-panel-stat span,
.teacher-panel-stat small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.teacher-panel-stat span {
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.teacher-panel-stat strong {
  display: block;
  overflow: hidden;
  margin-top: 3px;
  color: #172033;
  font-size: 20px;
  font-weight: 900;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.teacher-panel-stat small {
  margin-top: 5px;
  color: #64748b;
  font-size: 11px;
  font-weight: 600;
}

.teacher-panel-admin-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, 0.78fr);
  gap: 14px;
  align-items: start;
  margin-bottom: 14px;
}

.teacher-panel-broadcast-stack > .space-y-6 {
  display: grid;
  gap: 12px;
}

.teacher-panel-broadcast-stack > .space-y-6 > :not([hidden]) ~ :not([hidden]) {
  margin-top: 0 !important;
}

.teacher-panel-broadcast-stack .surface-card,
.teacher-panel-card {
  border: 1px solid var(--teacher-panel-border) !important;
  border-radius: 22px !important;
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9)) !important;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.9) !important;
}

.teacher-panel-broadcast-stack .surface-card {
  padding: 16px !important;
}

.teacher-panel-broadcast-stack .teacher-broadcast-history__preview {
  margin-top: 10px !important;
  font-size: 13px !important;
}

.teacher-students-card {
  min-height: 100%;
}

.teacher-students-card > .flex:first-child {
  margin-bottom: 12px !important;
}

.teacher-panel-toggle {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid #dbe3ef;
  border-radius: 12px;
  padding: 0 12px;
  color: #475569;
  background: rgba(255, 255, 255, 0.9);
  font-size: 12px;
  font-weight: 800;
  transition: border-color 160ms ease, color 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
}

.teacher-panel-toggle:hover {
  border-color: rgba(14, 165, 233, 0.36);
  color: #0369a1;
  background: #f0f9ff;
  box-shadow: 0 8px 18px rgba(14, 165, 233, 0.1);
}

.teacher-code-card {
  margin-bottom: 14px;
  padding: 14px 16px !important;
}

.teacher-code-card__header,
.teacher-code-card__title {
  display: flex;
  align-items: center;
  gap: 12px;
}

.teacher-code-card__header {
  justify-content: space-between;
}

.teacher-code-card__title {
  min-width: 0;
}

.teacher-code-card__icon {
  display: inline-flex;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(20, 184, 166, 0.22);
  border-radius: 12px;
  color: #0f766e;
  background: linear-gradient(145deg, #ccfbf1, #ecfeff);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.75), 0 8px 16px rgba(20, 184, 166, 0.1);
}

.teacher-code-card__title h3 {
  color: #172033;
  font-size: 17px;
  font-weight: 900;
  line-height: 1.15;
}

.teacher-code-card__title p {
  margin-top: 2px;
  color: #64748b;
  font-size: 12px;
  font-weight: 600;
}

.teacher-code-card__preview {
  margin-top: 10px;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
  padding-top: 10px;
  color: #64748b;
  font-size: 13px;
}

.teacher-code-card__form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr)) auto;
  gap: 10px;
  align-items: center;
  margin-top: 12px;
}

.teacher-code-card__form input {
  min-height: 42px;
  background: #fff !important;
}

.teacher-code-card__button {
  min-height: 42px;
  white-space: nowrap;
}

.teacher-code-card__hint {
  display: block;
  margin-top: 8px;
  color: #64748b;
  font-size: 11px;
}

.teacher-test-builder-layout {
  border: 1px solid rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.22);
  border-radius: 26px;
  padding: 14px;
  background:
    radial-gradient(circle at 0% 0%, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.12), transparent 34%),
    radial-gradient(circle at 100% 0%, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.08), transparent 38%),
    linear-gradient(165deg, rgba(255, 255, 255, 0.86), rgba(248, 250, 252, 0.72));
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.86);
}

html[data-theme='dark'] .teacher-panel-stat,
html[data-theme='dark'] .teacher-panel-broadcast-stack .surface-card,
html[data-theme='dark'] .teacher-panel-card {
  border-color: rgba(71, 85, 105, 0.52) !important;
  background:
    radial-gradient(circle at 100% 0%, rgba(56, 189, 248, 0.1), transparent 40%),
    linear-gradient(155deg, rgba(15, 23, 42, 0.94), rgba(17, 24, 39, 0.88)) !important;
  box-shadow: 0 18px 42px rgba(2, 6, 23, 0.38), inset 0 1px 0 rgba(148, 163, 184, 0.08) !important;
}

html[data-theme='dark'] .teacher-panel-title,
html[data-theme='dark'] .teacher-panel-stat strong,
html[data-theme='dark'] .teacher-code-card__title h3 {
  color: #f8fafc !important;
}

html[data-theme='dark'] .teacher-panel-subtitle,
html[data-theme='dark'] .teacher-panel-stat span,
html[data-theme='dark'] .teacher-panel-stat small,
html[data-theme='dark'] .teacher-code-card__title p,
html[data-theme='dark'] .teacher-code-card__preview,
html[data-theme='dark'] .teacher-code-card__hint {
  color: #94a3b8 !important;
}

html[data-theme='dark'] .teacher-panel-toggle {
  border-color: rgba(71, 85, 105, 0.58);
  color: #cbd5e1;
  background: rgba(15, 23, 42, 0.84);
}

html[data-theme='dark'] .teacher-panel-toggle:hover {
