  background: rgba(8, 47, 73, 0.56);
}

html[data-theme='dark'] .teacher-code-card__icon {
  border-color: rgba(45, 212, 191, 0.28);
  color: #99f6e4;
  background: rgba(19, 78, 74, 0.44);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 8px 18px rgba(2, 6, 23, 0.22);
}

html[data-theme='dark'] .teacher-code-card__form input {
  border-color: rgba(71, 85, 105, 0.58) !important;
  color: #f8fafc;
