}

html[data-theme='dark'] .teacher-test-builder-layout {
  border-color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.32);
  background:
    radial-gradient(circle at 0% 0%, rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.16), transparent 34%),
    radial-gradient(circle at 100% 0%, rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.12), transparent 38%),
    linear-gradient(165deg, rgba(15, 23, 42, 0.92), rgba(17, 24, 39, 0.86));
  box-shadow: 0 18px 42px rgba(2, 6, 23, 0.42), inset 0 1px 0 rgba(148, 163, 184, 0.08);
}

html[data-theme='dark'] .teacher-task-selector-card {
  border-color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.36) !important;
  background:
    radial-gradient(circle at 100% 0%, rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.2), transparent 42%),
    linear-gradient(145deg, rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.12), rgba(15, 23, 42, 0.9)) !important;
}

html[data-theme='dark'] .teacher-task-selector-card__current span,
html[data-theme='dark'] .teacher-task-selector-card__current strong {
  color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.98);
}

html[data-theme='dark'] .teacher-task-selector-card__current span {
  border-color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.26);
  background: rgba(15, 23, 42, 0.62);
}

html[data-theme='dark'] .teacher-task-selector-card__current small {
  color: #94a3b8;
}

html[data-theme='dark'] .teacher-task-selector-card__select {
  border-color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.3) !important;
  color: #f8fafc;
  background-color: rgba(15, 23, 42, 0.72) !important;
}

html[data-theme='dark'] .teacher-test-builder-level.is-selected {
  border-color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.58) !important;
  color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.98) !important;
  background:
    linear-gradient(145deg, rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.18), rgba(15, 23, 42, 0.78)) !important;
  box-shadow:
    0 0 0 1px rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.34),
    0 10px 22px rgba(2, 6, 23, 0.2) !important;
}

@media (max-width: 1280px) {
  .teacher-panel-hero {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1080px) {
  .teacher-panel-admin-grid {
    grid-template-columns: 1fr;
  }

  .teacher-code-card__form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .teacher-code-card__button {
    grid-column: 1 / -1;
  }
}

@media (max-width: 639px) {
  .teacher-panel-hero__stats,
  .teacher-code-card__form {
    grid-template-columns: 1fr;
  }

  .teacher-code-card__button {
    grid-column: auto;
  }

  .teacher-code-card__header {
    align-items: stretch;
    flex-direction: column;
  }

  .teacher-panel-toggle {
    width: 100%;
  }

  .teacher-test-builder-layout {
    margin-inline: -2px;
    padding: 10px;
    border-radius: 20px;
  }
}

/* Teacher question editor */
.teacher-question-editor {
  position: relative;
  overflow: visible;
  border-color: rgba(139, 92, 246, 0.22);
  background:
    radial-gradient(circle at 100% 0%, rgba(139, 92, 246, 0.08), transparent 30%),
    linear-gradient(165deg, rgba(255, 255, 255, 0.98), rgba(250, 250, 255, 0.94));
}

.teacher-question-editor__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin: -0.2rem -0.2rem 0;
  padding: 0.2rem 0.2rem 1rem;
}

.teacher-question-editor__header-content {
  flex: 1 1 auto;
  min-width: 0;
}

.teacher-question-editor__title-icon {
  display: inline-flex;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(139, 92, 246, 0.2);
  border-radius: 11px;
  color: #7c3aed;
  background: linear-gradient(145deg, #f5f3ff, #ede9fe);
  box-shadow: inset 0 1px 0 #fff, 0 6px 15px rgba(124, 58, 237, 0.1);
}

.teacher-test-builder-layout .teacher-question-editor {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.34) !important;
  background:
    radial-gradient(circle at 0% 0%, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.11), transparent 35%),
    radial-gradient(circle at 100% 0%, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.08), transparent 32%),
    linear-gradient(165deg, rgba(255, 255, 255, 0.99), rgba(250, 250, 255, 0.94)) !important;
}

.teacher-test-builder-layout .teacher-question-editor__title-icon {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.24);
  color: var(--teacher-task-accent-color, #0284c7);
  background:
    linear-gradient(145deg, var(--teacher-task-accent-bg, #e0f2fe), rgba(255, 255, 255, 0.86));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.88),
    0 8px 18px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.14);
}

.teacher-question-editor__target-banner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin: 0 0 16px;
  border: 1px solid rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.36);
  border-radius: 20px;
  padding: 16px 18px 16px 20px;
  background:
    linear-gradient(90deg, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.15), transparent 34%),
    linear-gradient(145deg, var(--teacher-task-accent-bg-strong, #bae6fd), rgba(255, 255, 255, 0.9) 58%, var(--teacher-task-accent-bg, #e0f2fe));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    inset 5px 0 0 rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.95),
    0 14px 32px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.16);
}

.teacher-question-editor__target-main {
  display: grid;
  min-width: 0;
  gap: 7px;
}

.teacher-question-editor__target-main > span {
  color: var(--teacher-task-accent-dark, #075985);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.teacher-question-editor__target-main strong {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  color: #172033;
  font-size: 20px;
  font-weight: 900;
  line-height: 1.15;
  overflow-wrap: anywhere;
}

.teacher-question-editor__target-main b {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  min-height: 32px;
  padding: 0 12px;
  color: #fff;
  background: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.95);
  box-shadow: 0 10px 18px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.22);
  font-size: 13px;
  font-weight: 950;
  line-height: 1;
  white-space: nowrap;
