.teacher-question-editor__target-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.teacher-question-editor__target-meta span {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  border: 1px solid rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.22);
  border-radius: 999px;
  padding: 0 13px;
  color: var(--teacher-task-accent-dark, #075985);
  background: rgba(255, 255, 255, 0.72);
  font-size: 12px;
  font-weight: 850;
  white-space: nowrap;
}

.teacher-question-editor__context-chip {
  display: inline-flex;
  align-items: center;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  padding: 3px 8px;
  color: #64748b;
  background: rgba(248, 250, 252, 0.92);
  font-size: 10px;
  font-weight: 700;
}

.teacher-question-editor__status-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 14px;
  padding: 9px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 14px;
  background: rgba(248, 250, 252, 0.8);
}

.teacher-question-editor__status-row > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  padding: 5px 9px;
  color: #94a3b8;
  background: #fff;
  font-size: 10px;
  font-weight: 800;
  transition: color 0.2s ease, border-color 0.2s ease, background 0.2s ease;
}

.teacher-question-editor__status-row > span.is-ready {
  border-color: #a7f3d0;
  color: #047857;
  background: #ecfdf5;
}

.teacher-question-editor__intro-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(250px, 0.65fr);
  gap: 14px;
  align-items: stretch;
}

.teacher-question-editor__section {
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 18px;
  padding: 15px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 7px 20px rgba(15, 23, 42, 0.04);
}

.teacher-question-editor__section-heading {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
}

.teacher-question-editor__section-heading h4 {
  color: #273247;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
}

.teacher-question-editor__section-heading p {
  margin-top: 2px;
  color: #94a3b8;
  font-size: 10px;
  line-height: 1.4;
}

.teacher-question-editor__step {
  display: inline-flex;
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #fff;
  background: linear-gradient(145deg, #8b5cf6, #7c3aed);
  box-shadow: 0 5px 12px rgba(124, 58, 237, 0.2);
  font-size: 11px;
  font-weight: 900;
}

.teacher-question-editor__textarea {
  width: 100%;
  min-height: 180px;
  resize: vertical;
  border: 1px solid #dbe2ea;
  border-radius: 14px;
  padding: 13px 14px;
  outline: none;
  color: #1e293b;
  background: #f8fafc;
  font-size: 14px;
  line-height: 1.65;
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.teacher-question-editor__textarea:focus {
  border-color: #8b5cf6;
  background: #fff;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.11);
}

.teacher-question-editor__preview {
  display: flex;
  min-height: 258px;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(139, 92, 246, 0.18);
  border-radius: 18px;
  padding: 14px;
  background:
    radial-gradient(circle at 100% 0%, rgba(168, 85, 247, 0.12), transparent 42%),
    linear-gradient(150deg, #faf8ff, #f6f7fb);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.teacher-question-editor__preview-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: #7c3aed;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.teacher-question-editor__preview-title > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.teacher-question-editor__preview-title > span:last-child {
  color: #a1a1aa;
  font-size: 9px;
}

.teacher-question-editor__preview-image {
  width: 100%;
  max-height: 130px;
  margin-top: 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 11px;
  object-fit: contain;
  background: #fff;
}

.teacher-question-editor__preview-text {
  margin-top: 11px;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  color: #334155;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.55;
}

.teacher-question-editor__preview-text.is-empty {
  color: #a1a9b7;
  font-weight: 500;
}

.teacher-question-editor__preview-answer {
  margin-top: auto;
  padding-top: 14px;
}

.teacher-question-editor__preview-answer span {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.teacher-question-editor__preview-answer div {
  margin-top: 5px;
  border: 1px solid #dfe4ec;
  border-radius: 10px;
  padding: 9px 10px;
  color: #a1a9b7;
  background: rgba(255, 255, 255, 0.84);
  font-size: 11px;
}

.teacher-question-editor__label-section {
  border-color: rgba(139, 92, 246, 0.18);
  background: linear-gradient(145deg, rgba(250, 248, 255, 0.96), rgba(255, 255, 255, 0.9));
}

.teacher-question-editor__color-preset {
  width: 20px;
  height: 20px;
  border: 2px solid #fff;
  border-radius: 999px;
  box-shadow: 0 0 0 1px rgba(100, 116, 139, 0.22);
  transition: transform 0.16s ease, box-shadow 0.16s ease;
}

.teacher-question-editor__color-preset:hover {
  transform: scale(1.12);
}

.teacher-question-editor__color-preset.is-active {
  box-shadow: 0 0 0 2px #fff, 0 0 0 4px rgba(139, 92, 246, 0.55);
}

.teacher-question-editor__drop-zone {
  min-height: 104px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: #fbfcfe;
}

.teacher-question-editor__drop-zone:hover {
  border-color: rgba(139, 92, 246, 0.42);
  background: #faf8ff;
}

.teacher-question-editor__answer-section input {
  min-height: 46px;
  border-color: #dbe2ea;
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.teacher-question-editor__answer-section input:focus {
  border-color: #8b5cf6;
  background: #fff;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.11);
}

.teacher-question-editor__footer {
  position: sticky;
  bottom: 10px;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 4px -4px -4px;
  border: 1px solid rgba(139, 92, 246, 0.2);
  border-radius: 16px;
  padding: 11px 12px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.12), 0 0 0 5px rgba(246, 247, 251, 0.72);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.teacher-question-editor__save {
  min-width: 230px;
}

html[data-theme='dark'] .teacher-question-editor {
