}

html[data-theme='dark'] .teacher-question-editor__target-main strong {
  color: #f8fafc;
}

html[data-theme='dark'] .teacher-question-editor__target-meta span {
  border-color: rgb(var(--teacher-task-accent-rgb, 56 189 248) / 0.26);
  background: rgba(15, 23, 42, 0.68);
}

html[data-theme='dark'] .teacher-question-editor__context-chip,
html[data-theme='dark'] .teacher-question-editor__status-row {
