}

@media (max-width: 900px) {
  .teacher-question-editor__intro-grid {
    grid-template-columns: 1fr;
  }

  .teacher-question-editor__preview {
    min-height: 220px;
  }

  .teacher-question-editor__target-banner {
    grid-template-columns: 1fr;
  }

  .teacher-question-editor__target-meta {
    justify-content: flex-start;
  }

  .teacher-question-list__context,
  .teacher-question-card {
    grid-template-columns: 1fr;
  }

  .teacher-question-list__context-meta,
  .teacher-question-card__actions {
    justify-content: flex-start;
  }

  .teacher-question-card__drag-handle {
    width: 42px;
  }
}

@media (max-width: 639px) {
  .teacher-question-editor__header,
  .teacher-question-editor__footer {
    align-items: stretch;
    flex-direction: column;
  }

  .teacher-question-editor__section {
    padding: 12px;
    border-radius: 15px;
  }

  .teacher-question-editor__target-banner {
    padding: 14px 14px 14px 17px;
    border-radius: 18px;
  }

  .teacher-question-editor__target-main strong {
    font-size: 17px;
    line-height: 1.2;
  }

  .teacher-question-editor__target-main b {
    min-height: 30px;
    padding: 0 10px;
    font-size: 12px;
  }

  .teacher-question-editor__target-meta span {
    min-height: 32px;
    padding: 0 11px;
    font-size: 11px;
  }

  .teacher-question-list__context {
    padding: 13px 13px 13px 16px;
    border-radius: 18px;
  }

  .teacher-question-list__context-main strong {
    font-size: 16px;
  }

  .teacher-question-list-heading {
    align-items: stretch;
    flex-direction: column;
  }

  .teacher-question-card {
    gap: 11px;
    padding: 12px;
    border-radius: 18px;
  }

  .teacher-question-card__answer-row {
    grid-template-columns: 1fr;
  }

  .teacher-question-card__move-panel {
    width: 100%;
  }

  .teacher-question-editor__textarea {
    min-height: 150px;
  }

  .teacher-question-editor__footer {
    bottom: 6px;
  }

  .teacher-question-editor__save {
    width: 100%;
    min-width: 0;
  }
}

/* Compact desktop layout: the complete question editor fits in one viewport. */
.teacher-test-builder-layout {
  display: block;
}

.teacher-test-builder-controls {
  display: grid;
  grid-template-columns: minmax(250px, 1.1fr) minmax(390px, 1.6fr) minmax(180px, 0.7fr);
  gap: 12px;
  margin-bottom: 12px;
}

.teacher-test-builder-control-card {
  min-width: 0;
  border-radius: 18px !important;
  padding: 12px !important;
}

.teacher-test-builder-control-card label {
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.teacher-test-builder-control-card select {
  padding: 9px 11px;
  font-size: 13px;
}

.teacher-task-selector-card {
  position: relative;
  overflow: hidden;
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.32) !important;
  background:
    radial-gradient(circle at 100% 0%, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.16), transparent 42%),
    linear-gradient(145deg, var(--teacher-task-accent-bg, #e0f2fe), rgba(255, 255, 255, 0.96)) !important;
}

.teacher-task-selector-card::before {
  content: '';
  position: absolute;
  inset: 12px auto 12px 0;
  width: 5px;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.96),
    rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.4)
  );
  box-shadow: 0 0 20px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.24);
}

.teacher-task-selector-card__current {
  display: grid;
  gap: 3px;
  margin: 2px 0 10px;
  padding-left: 2px;
}

.teacher-task-selector-card__current span {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border: 1px solid rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.22);
  border-radius: 999px;
  padding: 3px 8px;
  color: var(--teacher-task-accent-dark, #075985);
  background: rgba(255, 255, 255, 0.72);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.teacher-task-selector-card__current strong {
  overflow: hidden;
  color: var(--teacher-task-accent-dark, #075985);
  font-size: 15px;
  font-weight: 900;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.teacher-task-selector-card__current small {
  color: #64748b;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.35;
}

.teacher-task-selector-card__select {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.28) !important;
  background-color: rgba(255, 255, 255, 0.86) !important;
  box-shadow: 0 8px 20px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.08);
}

.teacher-task-selector-card__select:focus {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.72) !important;
  box-shadow:
    0 0 0 3px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.14),
    0 10px 24px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.1);
}

.teacher-test-builder-levels {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.teacher-test-builder-levels button {
  min-width: 0;
  padding: 8px 9px;
  gap: 5px;
  font-size: 12px;
}

.teacher-test-builder-levels button > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.teacher-test-builder-levels button > span:last-child {
  padding: 2px 5px;
  font-size: 9px;
  white-space: nowrap;
}

.teacher-test-builder-level.is-selected {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.62) !important;
  color: var(--teacher-task-accent-dark, #075985) !important;
  background:
    linear-gradient(145deg, rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.16), rgba(255, 255, 255, 0.92)) !important;
  box-shadow:
    0 0 0 1px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.38),
    0 10px 22px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.12) !important;
}

.teacher-test-builder-level.is-selected > span:last-child {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.26);
  color: var(--teacher-task-accent-dark, #075985);
}

.teacher-test-builder-count {
  display: flex;
  min-height: 78px;
  flex-direction: column;
  justify-content: center;
  padding: 11px 13px !important;
  font-size: 11px !important;
  line-height: 1.45;
}

.teacher-test-builder-main {
  min-width: 0;
}

.teacher-question-editor {
  padding: 14px !important;
}

.teacher-question-editor__header {
  padding-bottom: 9px;
}

.teacher-question-editor__header p {
  margin-top: 2px;
}

.teacher-question-editor__header .mt-2 {
  margin-top: 5px;
}

.teacher-question-editor__status-row {
  margin-bottom: 10px;
  padding: 6px;
}

.teacher-question-editor__status-row > span {
  padding: 4px 8px;
}

.teacher-question-editor__body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-areas:
    "intro intro"
    "label materials"
    "answer materials"
    "footer footer";
  gap: 10px;
  align-items: stretch;
}

.teacher-question-editor__intro-grid {
  grid-area: intro;
  gap: 10px;
}

.teacher-question-editor__label-section {
  grid-area: label;
}

.teacher-question-editor__materials-section {
  grid-area: materials;
  max-height: 250px;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}

.teacher-question-editor__answer-section {
  grid-area: answer;
  max-height: 150px;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}

.teacher-question-editor__footer {
  grid-area: footer;
  position: static;
  margin: 0;
  padding: 8px 10px;
  border-radius: 14px;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

.teacher-question-editor__body > p {
  grid-column: 1 / -1;
  margin: 0;
}

.teacher-question-editor__section {
  padding: 11px;
  border-radius: 15px;
}

.teacher-question-editor__section-heading {
  gap: 8px;
  margin-bottom: 8px;
}

.teacher-question-editor__section-heading p {
  line-height: 1.25;
}

.teacher-question-editor__step {
  width: 23px;
  height: 23px;
  flex-basis: 23px;
}

.teacher-question-editor__textarea {
  min-height: 105px;
  max-height: 130px;
  padding: 10px 11px;
  line-height: 1.45;
}

.teacher-question-editor__preview {
