}

.teacher-question-card__actions {
  justify-content: flex-end;
}

.teacher-question-card__icon-action {
  display: inline-flex;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(203, 213, 225, 0.72);
  border-radius: 12px;
  color: #94a3b8;
  background: rgba(255, 255, 255, 0.82);
  transition: border-color 160ms ease, color 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
}

.teacher-question-card__icon-action:hover {
  border-color: rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.36);
  color: var(--teacher-task-accent-color, #0284c7);
  background: var(--teacher-task-accent-bg, #e0f2fe);
  box-shadow: 0 8px 18px rgb(var(--teacher-task-accent-rgb, 14 165 233) / 0.1);
}

.teacher-question-card__icon-action--danger:hover {
  border-color: rgba(244, 63, 94, 0.32);
  color: #e11d48;
  background: #fff1f2;
  box-shadow: 0 8px 18px rgba(244, 63, 94, 0.1);
}

.teacher-question-drop-indicator {
  position: relative;
  display: flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
}

.teacher-question-drop-indicator::before {
  content: '';
  position: absolute;
  left: 42px;
  right: 18px;
  top: 50%;
  height: 4px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(124, 58, 237, 0.1), #8b5cf6 18%, #38bdf8 82%, rgba(56, 189, 248, 0.08));
  box-shadow:
    0 0 0 4px rgba(139, 92, 246, 0.08),
    0 8px 22px rgba(124, 58, 237, 0.18);
  transform: translateY(-50%);
}

.teacher-question-drop-indicator::after {
  content: '';
  position: absolute;
  left: 34px;
  top: 50%;
  width: 20px;
  height: 20px;
  border: 4px solid #8b5cf6;
  border-radius: 999px;
  background: #fff;
  box-shadow: 0 8px 18px rgba(124, 58, 237, 0.2);
  transform: translateY(-50%);
}

.teacher-question-drop-indicator span {
  position: relative;
  z-index: 1;
  border: 1px solid rgba(139, 92, 246, 0.24);
  border-radius: 999px;
  padding: 5px 11px;
  background: rgba(255, 255, 255, 0.96);
  color: #7c3aed;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.035em;
  text-transform: uppercase;
  box-shadow: 0 10px 22px rgba(124, 58, 237, 0.14);
}

