.teacher-question-editor-inline-wrap {
  scroll-margin-top: 92px;
  margin: -2px 0 16px;
}

.teacher-question-editor--inline {
  border-color: rgba(139, 92, 246, 0.34) !important;
  background:
    radial-gradient(circle at 0% 0%, rgba(59, 130, 246, 0.065), transparent 34%),
    radial-gradient(circle at 100% 0%, rgba(168, 85, 247, 0.08), transparent 32%),
    linear-gradient(170deg, rgba(255, 255, 255, 0.99), rgba(250, 250, 255, 0.96)) !important;
  box-shadow:
    0 16px 34px rgba(88, 28, 135, 0.11),
    inset 0 1px 0 rgba(255, 255, 255, 0.86) !important;
}

.teacher-question-editor__inline-grid {
  grid-area: intro;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(280px, 0.75fr);
  gap: 10px;
  align-items: stretch;
}

.teacher-question-editor__preview-image-button,
.teacher-question-editor__attached-image-button {
  display: block;
  width: 100%;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  cursor: zoom-in;
  text-align: inherit;
}

.teacher-question-editor__preview-image-button .teacher-question-editor__preview-image,
.teacher-question-editor__attached-image-button img {
  transition: transform 170ms ease, filter 170ms ease;
}

.teacher-question-editor__preview-image-button:hover .teacher-question-editor__preview-image,
.teacher-question-editor__attached-image-button:hover img {
  transform: scale(1.012);
  filter: saturate(1.03);
}

.teacher-question-image-lightbox {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: flex;
  width: 100vw;
  height: 100dvh;
  align-items: center;
  justify-content: center;
  padding: clamp(16px, 3vw, 40px);
  background: rgba(15, 23, 42, 0.78);
  backdrop-filter: blur(10px) saturate(112%);
  -webkit-backdrop-filter: blur(10px) saturate(112%);
}

.teacher-question-image-lightbox__panel {
  display: flex;
  width: min(1180px, 96vw);
  max-height: 92vh;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 24px;
  background: rgba(15, 23, 42, 0.86);
  box-shadow: 0 28px 76px rgba(2, 6, 23, 0.48);
}

.teacher-question-image-lightbox__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px 10px 16px;
  color: #fff;
  font-size: 13px;
  font-weight: 800;
}

.teacher-question-image-lightbox__bar span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.teacher-question-image-lightbox__bar button {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.teacher-question-image-lightbox__bar button:hover {
  border-color: rgba(255, 255, 255, 0.34);
  background: rgba(255, 255, 255, 0.18);
  transform: translateY(-1px);
}

.teacher-question-image-lightbox__image {
  max-width: 100%;
  max-height: calc(92vh - 56px);
  object-fit: contain;
  background: #fff;
}

html[data-theme='dark'] .teacher-question-editor--inline {
  border-color: rgba(167, 139, 250, 0.28) !important;
  background:
    radial-gradient(circle at 0% 0%, rgba(59, 130, 246, 0.13), transparent 34%),
    radial-gradient(circle at 100% 0%, rgba(168, 85, 247, 0.13), transparent 32%),
    linear-gradient(170deg, rgba(15, 23, 42, 0.96), rgba(30, 41, 59, 0.9)) !important;
}

@media (max-width: 1050px) {
  .teacher-test-builder-controls {
    grid-template-columns: minmax(220px, 1fr) minmax(360px, 1.5fr);
  }

  .teacher-test-builder-count {
    grid-column: 1 / -1;
    min-height: 0;
  }
}

@media (max-width: 840px) {
  .teacher-test-builder-controls,
  .teacher-question-editor__body {
    grid-template-columns: 1fr;
  }

  .teacher-test-builder-controls {
    display: grid;
  }

  .teacher-question-editor__body {
    grid-template-areas:
      "intro"
      "label"
      "materials"
      "answer"
      "footer";
  }

  .teacher-question-editor__materials-section,
  .teacher-question-editor__answer-section {
    max-height: none;
  }

  .teacher-question-editor__inline-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 639px) {
  .teacher-test-builder-controls {
    grid-template-columns: 1fr;
  }

  .teacher-test-builder-levels {
    grid-template-columns: 1fr;
  }

  .teacher-question-editor {
    padding: 11px !important;
  }
}

/* Student test level picker */
.student-level-modal-backdrop {
  background:
    radial-gradient(circle at 50% 15%, rgba(139, 92, 246, 0.18), transparent 42%),
    rgba(15, 23, 42, 0.62);
  backdrop-filter: blur(11px) saturate(112%);
  -webkit-backdrop-filter: blur(11px) saturate(112%);
}

.student-level-modal {
  width: min(820px, calc(100vw - 24px)) !important;
  max-width: 820px !important;
  max-height: calc(100dvh - 24px) !important;
  overflow: auto;
  border: 1px solid rgba(148, 163, 184, 0.26);
  border-radius: 26px !important;
  padding: 18px !important;
  color: #172033;
  background:
    radial-gradient(circle at 100% 0%, rgba(139, 92, 246, 0.09), transparent 34%),
    linear-gradient(160deg, rgba(255, 255, 255, 0.99), rgba(247, 248, 252, 0.98));
  box-shadow:
    0 34px 90px rgba(15, 23, 42, 0.32),
    0 8px 24px rgba(15, 23, 42, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.student-level-modal--loading {
  max-width: 430px !important;
  padding: 32px 26px !important;
}

.student-level-modal__close {
  position: absolute;
  top: 13px;
  right: 13px;
  z-index: 2;
  display: inline-flex;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 12px;
  color: #475569;
  background: rgba(248, 250, 252, 0.92);
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.student-level-modal__close:hover {
  border-color: rgba(244, 63, 94, 0.26);
  color: #e11d48;
  background: #fff1f2;
  transform: translateY(-1px);
}

.student-level-modal__header {
  padding: 0 48px 13px;
  text-align: center;
}

.student-level-modal__task-chip {
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(139, 92, 246, 0.2);
  border-radius: 999px;
  padding: 4px 9px;
  color: #7c3aed;
  background: #f5f3ff;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.student-level-modal__header h2 {
  margin-top: 6px;
  color: #172033;
  font-size: clamp(21px, 3vw, 28px);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.035em;
}

.student-level-modal__header p {
  margin-top: 3px;
  overflow: hidden;
  color: #7b8799;
  font-size: 12px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-level-modal__mastery {
  width: min(290px, 100%);
  margin: 9px auto 0;
  color: #7b8799;
  font-size: 9px;
  font-weight: 700;
}

.student-level-modal__mastery strong {
  color: #6d28d9;
  font-size: 10px;
}

.student-level-modal__mastery > div:last-child {
  height: 4px;
  margin-top: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: #e9e5f5;
}

.student-level-modal__mastery > div:last-child span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #8b5cf6, #a855f7);
  box-shadow: 0 0 9px rgba(139, 92, 246, 0.4);
}

.student-level-modal__availability {
  width: fit-content;
  margin: 7px auto 0;
  border-radius: 999px;
  padding: 3px 8px;
  color: #64748b;
  background: rgba(241, 245, 249, 0.82);
  font-size: 9px;
  font-weight: 800;
}

.student-level-modal__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.student-level-card {
  --level-accent: #3b82f6;
  --level-soft: #eff6ff;
  --level-border: #bfdbfe;
  display: flex;
  min-width: 0;
  min-height: 174px;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  border: 1px solid var(--level-border);
  border-radius: 18px;
  padding: 13px;
  text-align: left;
  color: #263248;
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--level-accent) 12%, transparent), transparent 42%),
    rgba(255, 255, 255, 0.94);
  box-shadow: 0 7px 18px rgba(15, 23, 42, 0.055), inset 0 1px 0 #fff;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.student-level-card[data-level='advanced'] {
  --level-accent: #9333ea;
  --level-soft: #faf5ff;
  --level-border: #e9d5ff;
}

.student-level-card[data-level='expert'] {
  --level-accent: #f43f5e;
  --level-soft: #fff1f2;
  --level-border: #fecdd3;
}

.student-level-card[data-recommended='true'] {
  border-color: color-mix(in srgb, var(--level-accent) 58%, white);
  box-shadow:
    0 11px 24px color-mix(in srgb, var(--level-accent) 13%, transparent),
    0 0 0 3px color-mix(in srgb, var(--level-accent) 7%, transparent),
    inset 0 1px 0 #fff;
}

.student-level-card:hover:not(:disabled) {
  border-color: var(--level-accent);
  box-shadow: 0 14px 28px color-mix(in srgb, var(--level-accent) 18%, transparent), inset 0 1px 0 #fff;
  transform: translateY(-3px);
}

.student-level-card:disabled {
  cursor: not-allowed;
  filter: saturate(0.55);
  opacity: 0.62;
}

.student-level-card:disabled:hover {
  border-color: var(--level-border);
  box-shadow: 0 7px 18px rgba(15, 23, 42, 0.055), inset 0 1px 0 #fff;
  transform: none;
}

.student-level-card:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--level-accent) 20%, transparent), 0 12px 24px rgba(15, 23, 42, 0.12);
}

.student-level-card__topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.student-level-card__icon {
  display: inline-flex;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--level-border);
  border-radius: 11px;
  color: var(--level-accent);
  background: var(--level-soft);
}

.student-level-card__badges {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 4px;
}

.student-level-card__count,
.student-level-card__recommended {
  overflow: hidden;
  border-radius: 999px;
  padding: 3px 7px;
  color: #8490a2;
  background: #f8fafc;
  font-size: 9px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-level-card__recommended {
  color: var(--level-accent);
  background: var(--level-soft);
}

.student-level-card[data-completed='true'] .student-level-card__count {
  color: #047857;
  background: #ecfdf5;
}

.student-level-card__content {
  margin-top: 11px;
}

.student-level-card__content h3 {
  color: #202b40;
  font-size: 16px;
  font-weight: 900;
  line-height: 1.15;
}

.student-level-card__content p {
  margin-top: 4px;
  color: #7b8799;
  font-size: 10px;
  line-height: 1.38;
}

.student-level-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 10px;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
  padding-top: 9px;
  color: #475569;
  font-size: 11px;
  font-weight: 800;
}

.student-level-card__reward {
  border: 1px solid color-mix(in srgb, var(--level-accent) 22%, transparent);
  border-radius: 999px;
  padding: 3px 7px;
  color: var(--level-accent);
  background: var(--level-soft);
  font-size: 9px;
  white-space: nowrap;
}

.student-level-card__unavailable {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
}

.student-level-modal__loading-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgba(139, 92, 246, 0.22);
  border-radius: 12px;
  padding: 8px 11px;
  color: #7c3aed;
  background: #f5f3ff;
  font-size: 12px;
  font-weight: 800;
}

html[data-theme='dark'] .student-level-modal {
  border-color: rgba(100, 116, 139, 0.38);
