/* Modern compact level progress in the student top strip */
.top-stats-strip .level-progress-card {
  overflow: visible;
  border: 0;
  border-radius: 0;
  padding: 0.28rem 0.35rem !important;
  color: inherit;
  background: transparent;
  box-shadow: none;
  text-align: left;
  cursor: pointer;
  transition: filter 0.2s ease, transform 0.2s ease;
}

.top-stats-strip .level-progress-card:hover {
  filter: saturate(1.06);
  transform: translateY(-1px);
}

.top-stats-strip .level-progress-card:active {
  transform: translateY(0) scale(0.992);
}

.top-stats-strip .level-progress-card:focus-visible {
  border-radius: 12px;
  outline: 2px solid rgba(139, 92, 246, 0.48);
  outline-offset: 3px;
}

.top-stats-strip .level-progress-card::before {
  display: none;
}

.top-stats-strip .level-progress-card::after {
  display: none;
}

.top-stats-strip .level-progress-main {
  gap: 0.68rem;
}

.top-stats-strip .level-progress-badge {
  width: 44px;
  height: 48px;
  border: 1px solid rgba(255, 255, 255, 0.58);
  border-radius: 15px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  background:
    radial-gradient(circle at 28% 18%, rgba(255, 255, 255, 0.36), transparent 30%),
    linear-gradient(145deg, #8b5cf6 0%, #6d5dfc 52%, #4f46e5 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.46),
    inset 0 -7px 14px rgba(49, 46, 129, 0.22),
    0 8px 18px rgba(79, 70, 229, 0.25);
}

.top-stats-strip .level-progress-badge::before {
  position: absolute;
  inset: -4px;
  border: 1px solid rgba(139, 92, 246, 0.18);
  border-radius: 18px;
  content: '';
  pointer-events: none;
}

.level-progress-badge-label {
  position: relative;
  z-index: 1;
  font-size: 6px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.15em;
  opacity: 0.74;
}

.level-progress-badge-number {
  position: relative;
  z-index: 1;
  margin-top: 1px;
  font-size: 17px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: -0.04em;
}

.top-stats-strip .level-progress-head {
  min-height: 24px;
  align-items: flex-start;
  gap: 0.6rem;
}

.level-progress-identity {
  display: flex;
  min-width: 58px;
  flex-direction: column;
  gap: 1px;
}

.level-progress-eyebrow {
  color: #94a3b8;
  font-size: 7px;
  font-weight: 850;
  line-height: 1;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.top-stats-strip .level-progress-title {
  color: #4c1d95;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: -0.015em;
  text-shadow: none;
  white-space: nowrap;
}

.top-stats-strip .level-progress-head-meta {
  gap: 0.28rem;
  flex-wrap: wrap;
}

.top-stats-strip .level-progress-total {
  display: inline-flex;
  align-items: baseline;
  gap: 3px;
  border: 0;
  border-radius: 7px;
  padding: 2px 5px;
  color: #475569;
  background: rgba(255, 255, 255, 0.54);
  font-size: 9px;
  line-height: 1.2;
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.13);
  white-space: nowrap;
}

.level-progress-total-label {
  color: #94a3b8;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.top-stats-strip .level-progress-coin {
  gap: 0.24rem;
  border-color: rgba(245, 158, 11, 0.25);
  border-radius: 8px;
  padding: 2px 6px;
  background: linear-gradient(135deg, rgba(255, 251, 235, 0.94), rgba(254, 243, 199, 0.76));
  color: #92400e;
  font-size: 9px;
  line-height: 1.2;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.top-stats-strip .level-progress-coin img {
  width: 12px;
  height: 12px;
}

.top-stats-strip .level-progress-track {
  height: 8px;
  margin-top: 0.28rem;
  overflow: visible;
  border: 0;
  border-radius: 999px;
  background: rgba(139, 92, 246, 0.1);
  box-shadow: inset 0 1px 2px rgba(76, 29, 149, 0.1);
}

.top-stats-strip .level-progress-track-grid,
.top-stats-strip .level-progress-glass {
  display: none;
}

.top-stats-strip .level-progress-fill {
  overflow: visible;
  min-width: 7px;
  border-radius: 999px;
  background: linear-gradient(90deg, #6366f1 0%, #8b5cf6 58%, #d946ef 100%);
  background-size: 160% 100%;
  box-shadow: 0 2px 8px rgba(124, 58, 237, 0.28);
}

.top-stats-strip .level-progress-fill::before {
  inset: -60% auto -60% -28%;
  opacity: 0.72;
}

.level-progress-fill-tip {
  position: absolute;
  top: 50%;
  right: -3px;
  width: 10px;
  height: 10px;
  border: 2px solid rgba(255, 255, 255, 0.92);
  border-radius: 999px;
  background: #a855f7;
  box-shadow: 0 0 0 3px rgba(168, 85, 247, 0.12), 0 2px 7px rgba(88, 28, 135, 0.28);
  transform: translateY(-50%);
  animation: levelProgressTipPulse 2.4s ease-in-out infinite;
}

.top-stats-strip .level-progress-foot {
  margin-top: 0.34rem;
  color: #64748b;
  font-size: 8.5px;
  font-weight: 650;
  line-height: 1.15;
}

.level-progress-foot-current strong {
  color: #475569;
  font-weight: 850;
}

.level-progress-foot-next {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #8b5cf6;
  white-space: nowrap;
}

.level-progress-percent {
  border-radius: 999px;
  padding: 1px 5px;
  color: #6d28d9;
  background: rgba(139, 92, 246, 0.09);
  font-size: 8px;
  font-weight: 900;
}

.level-progress-foot-next strong {
  color: #6d28d9;
  font-weight: 850;
}

@keyframes levelProgressTipPulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(168, 85, 247, 0.1), 0 2px 7px rgba(88, 28, 135, 0.24); }
  50% { box-shadow: 0 0 0 5px rgba(168, 85, 247, 0.04), 0 2px 10px rgba(88, 28, 135, 0.36); }
}

html[data-theme='dark'] .top-stats-strip .level-progress-card {
  border: 0;
  background: transparent;
  box-shadow: none;
}

html[data-theme='dark'] .top-stats-strip .level-progress-title {
