      0 8px 20px rgba(44, 72, 116, 0.14),
      var(--collab-code-inner-shadow) !important;
    backdrop-filter: blur(10px);
    transform: translate(-50%, -50%) !important;
    transition:
      border-color 150ms ease,
      background-color 150ms ease,
      box-shadow 150ms ease !important;
  }

  html .collab-workspace-card--glass-board.collab-workspace-card--glass-board .collab-board-code-resizer__thumb svg {
    display: block !important;
    width: 9px;
    height: 12px;
