  html .collab-workspace-card--glass-board.collab-workspace-card--glass-board .collab-board-code-resizer__grip {
    width: 2px !important;
    height: 26px !important;
    border-radius: 999px !important;
    background: color-mix(in srgb, var(--collab-code-accent) 62%, var(--collab-code-line-strong)) !important;
    box-shadow: none !important;
