@media (max-width: 700px) {
  .student-goal-summary--collapsed {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 9px;
  }

  .student-goal-summary__collapsed-progress {
    display: none;
  }

  .student-goal-summary__expand {
    width: 38px;
    padding: 0;
  }

  .student-goal-summary__expand > span {
    display: none;
  }
}

@media (max-width: 520px) {
  .student-goal-summary--expanded {
    padding: 14px;
    border-radius: 22px;
  }

  .student-goal-summary__header {
    align-items: flex-start;
  }

  .student-goal-summary__heading h3 {
    font-size: 17px;
  }

  .student-goal-summary__header-actions {
    flex-direction: column;
    align-items: flex-end;
  }

  .student-goal-summary__collapse {
    width: 36px;
    padding: 0;
  }

  .student-goal-summary__collapse > span {
    display: none;
  }

  .student-goal-summary__item-header {
    align-items: stretch;
    flex-direction: column;
  }

  .student-goal-summary__item-action {
    width: 100%;
  }

  .student-goal-summary__target-list {
    width: 100%;
    max-width: 100%;
    flex-wrap: nowrap;
    overflow-x: auto;
    padding-bottom: 3px;
    scroll-snap-type: x proximity;
    scrollbar-width: none;
  }

  .student-goal-summary__target-list::-webkit-scrollbar {
    display: none;
  }

  .student-goal-summary__target {
    flex: 0 0 auto;
    scroll-snap-align: start;
  }

  .student-goal-summary--collapsed {
    min-height: 68px;
    padding: 9px 10px;
  }

  .student-goal-summary--collapsed .student-goal-summary__icon {
    width: 36px;
    height: 36px;
  }

  .student-goal-summary__collapsed-title {
    font-size: 12px;
  }

  .student-goal-summary__collapsed-meta {
    max-width: 155px;
  }

  .student-goal-summary__primary {
    min-height: 34px;
    padding: 0 10px;
    font-size: 10px;
  }

  .top-stats-strip .student-level-summary-card {
    padding: 7px 8px !important;
  }

  .top-stats-strip .student-level-summary-card .level-progress-main {
    gap: 8px;
  }

  .top-stats-strip .student-level-summary-card .level-progress-badge {
    width: 41px;
    height: 44px;
    border-radius: 14px;
  }

  .top-stats-strip .student-level-summary-card .level-progress-badge-number {
    font-size: 17px;
  }

  .top-stats-strip .student-level-summary-card .level-progress-identity {
    min-width: 72px;
  }

  .top-stats-strip .student-level-summary-card .level-progress-title {
    font-size: 12px;
  }

  .top-stats-strip .student-level-summary-card .level-progress-total,
  .top-stats-strip .student-level-summary-card .level-progress-open {
    display: none;
  }

  .top-stats-strip .student-level-summary-card .level-progress-remaining {
    display: inline !important;
  }

  .top-stats-strip .student-level-summary-card .level-progress-percent {
    display: none;
  }

  .top-stats-strip .student-level-summary-card .level-progress-foot {
    font-size: 8.5px;
  }
}

