/* Student Today polish: clear actions, elevated homework, richer dark surfaces. */
.student-today-overview {
  position: relative;
  isolation: isolate;
}

html:not([data-theme='dark']) .student-today-overview {
  border-color: rgba(196, 181, 253, 0.92) !important;
  background:
    radial-gradient(circle at 6% 0%, rgba(224, 231, 255, 0.42), transparent 34%),
    radial-gradient(circle at 96% 100%, rgba(186, 230, 253, 0.3), transparent 32%),
    linear-gradient(145deg, #ffffff 0%, #fcfbff 55%, #f6f8ff 100%) !important;
  box-shadow:
    0 26px 58px rgba(79, 70, 229, 0.15),
    0 5px 15px rgba(15, 23, 42, 0.055),
    inset 0 1px 0 #fff !important;
}

.student-today-overview::before {
  position: absolute;
  z-index: 3;
  top: 0;
  right: 28px;
  left: 28px;
  height: 3px;
  border-radius: 0 0 999px 999px;
  background: linear-gradient(90deg, transparent, #8b5cf6 22%, #6366f1 58%, #38bdf8 78%, transparent);
  content: '';
  pointer-events: none;
}

.student-today-overview__quick-action {
  --today-action-rgb: 124 58 237;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: 126px !important;
  cursor: pointer;
  border-color: rgb(var(--today-action-rgb) / 0.26) !important;
  background:
    radial-gradient(circle at 100% 0%, rgb(var(--today-action-rgb) / 0.13), transparent 48%),
    linear-gradient(145deg, #ffffff, rgb(var(--today-action-rgb) / 0.045)) !important;
  box-shadow:
    0 12px 27px rgb(var(--today-action-rgb) / 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.92) !important;
  transition: border-color 170ms ease, box-shadow 170ms ease, transform 170ms ease !important;
}

.student-today-overview__quick-action[data-tone='lesson'] {
  --today-action-rgb: 14 165 233;
}

.student-today-overview__quick-action[data-tone='chat'] {
  --today-action-rgb: 217 70 239;
}

.student-today-overview__quick-action[data-tone='practice'] {
  --today-action-rgb: 16 185 129;
}

.student-today-overview__quick-action:hover {
  z-index: 2;
  border-color: rgb(var(--today-action-rgb) / 0.5) !important;
  background:
    radial-gradient(circle at 100% 0%, rgb(var(--today-action-rgb) / 0.18), transparent 50%),
    linear-gradient(145deg, #ffffff, rgb(var(--today-action-rgb) / 0.075)) !important;
  box-shadow:
    0 17px 34px rgb(var(--today-action-rgb) / 0.17),
    inset 0 1px 0 #fff !important;
  transform: translateY(-2px) !important;
}

.student-today-overview__quick-action:active {
  box-shadow: 0 8px 18px rgb(var(--today-action-rgb) / 0.12) !important;
  transform: translateY(0) scale(0.99) !important;
}

.student-today-overview__quick-action:focus-visible {
  outline: 3px solid rgb(var(--today-action-rgb) / 0.34);
  outline-offset: 3px;
}

.student-today-overview__quick-icon,
.student-today-overview__quick-arrow {
  border-color: rgb(var(--today-action-rgb) / 0.18) !important;
  background: rgb(var(--today-action-rgb) / 0.09) !important;
  color: rgb(var(--today-action-rgb)) !important;
}

.student-today-overview__quick-arrow {
  display: inline-flex;
  width: 30px;
  height: 30px;
  align-items: center;
  justify-content: center;
  border: 1px solid;
  border-radius: 10px;
  transition: transform 170ms ease, background 170ms ease;
}

.student-today-overview__quick-action:hover .student-today-overview__quick-arrow {
  background: rgb(var(--today-action-rgb) / 0.15) !important;
  transform: translateX(2px);
}

.student-today-overview__quick-eyebrow,
.student-today-overview__quick-cta {
  color: rgb(var(--today-action-rgb)) !important;
}

.student-today-overview__quick-cta {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: auto !important;
  padding-top: 10px;
  font-size: 11px;
  font-weight: 900;
}

.student-today-overview__quick-cta svg {
  transition: transform 170ms ease;
}

.student-today-overview__quick-action:hover .student-today-overview__quick-cta svg {
  transform: translateX(2px);
}

