/* Student payment reminder shown once when the platform opens. */
.student-payment-reminder {
  position: fixed;
  z-index: 1700;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow-y: auto;
  padding: max(16px, env(safe-area-inset-top)) 16px max(16px, env(safe-area-inset-bottom));
  background: rgba(15, 23, 42, 0.58);
  backdrop-filter: blur(5px);
}

.student-payment-reminder__dialog {
  position: relative;
  width: min(560px, 100%);
  max-height: min(760px, calc(100dvh - 32px));
  overflow-y: auto;
  padding: 22px;
  border: 1px solid rgba(251, 113, 133, 0.54);
  border-radius: 28px;
  background: linear-gradient(145deg, #ffffff 0%, #fff8fb 52%, #f5f3ff 100%);
  box-shadow:
    0 34px 90px rgba(15, 23, 42, 0.3),
    0 10px 30px rgba(225, 29, 72, 0.13);
  animation: studentPaymentReminderIn 220ms ease both;
}

@keyframes studentPaymentReminderIn {
  from { opacity: 0; transform: translateY(14px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.student-payment-reminder__accent {
  position: absolute;
  top: 0;
  right: 24px;
  left: 24px;
  height: 4px;
  border-radius: 0 0 999px 999px;
  background: linear-gradient(90deg, #fb7185, #e11d48 48%, #8b5cf6);
}

.student-payment-reminder__close {
  position: absolute;
  top: 16px;
  right: 16px;
  display: inline-flex;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(203, 213, 225, 0.9);
  border-radius: 12px;
  background: #fff;
  color: #64748b;
  transition: border-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.student-payment-reminder__close:hover {
  border-color: rgba(251, 113, 133, 0.65);
  color: #e11d48;
  transform: rotate(3deg);
}

.student-payment-reminder__close:focus-visible,
.student-payment-reminder__later:focus-visible,
.student-payment-reminder__schedule:focus-visible {
  outline: 3px solid rgba(244, 63, 94, 0.3);
  outline-offset: 3px;
}

.student-payment-reminder__header {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  align-items: start;
  gap: 14px;
  padding-right: 36px;
}

.student-payment-reminder__icon {
  display: inline-flex;
  width: 52px;
  height: 52px;
  align-items: center;
  justify-content: center;
  border-radius: 17px;
  background: linear-gradient(145deg, #f43f5e, #e11d48 55%, #8b5cf6);
  color: #fff;
  box-shadow: 0 12px 26px rgba(225, 29, 72, 0.24);
}

.student-payment-reminder__eyebrow {
  display: block;
  color: #e11d48;
  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.student-payment-reminder__header h2 {
  margin-top: 3px;
  color: #0f172a;
  font-size: 22px;
  font-weight: 950;
  letter-spacing: -0.025em;
  line-height: 1.18;
}

.student-payment-reminder__header p {
  margin-top: 7px;
  color: #64748b;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.55;
}

.student-payment-reminder__list {
  display: grid;
  gap: 9px;
  margin-top: 18px;
}

.student-payment-reminder__item {
  display: grid;
  min-width: 0;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid rgba(253, 164, 175, 0.58);
  border-radius: 16px;
  background: linear-gradient(145deg, #fff1f2, #ffffff 70%);
  box-shadow: 0 8px 20px rgba(225, 29, 72, 0.07);
}

.student-payment-reminder__item-date {
  display: inline-flex;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #ffe4e6;
  color: #e11d48;
}

.student-payment-reminder__item-copy {
  min-width: 0;
}

.student-payment-reminder__item-copy strong,
.student-payment-reminder__item-copy span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.student-payment-reminder__item-copy strong {
  color: #1e293b;
  font-size: 13px;
  font-weight: 900;
}

.student-payment-reminder__item-copy span {
  margin-top: 2px;
  color: #64748b;
  font-size: 11px;
  font-weight: 650;
}

.student-payment-reminder__elapsed {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  gap: 4px;
  padding: 0 9px;
  border: 1px solid rgba(251, 113, 133, 0.46);
  border-radius: 999px;
  background: #fff;
  color: #be123c;
  font-size: 10px;
  font-weight: 850;
  white-space: nowrap;
}

.student-payment-reminder__more {
  padding: 4px 8px 0;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
}

.student-payment-reminder__actions {
  display: grid;
  grid-template-columns: minmax(0, 0.75fr) minmax(0, 1.25fr);
  gap: 10px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid rgba(253, 164, 175, 0.42);
}

.student-payment-reminder__later,
.student-payment-reminder__schedule {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 13px;
  font-size: 12px;
  font-weight: 900;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.student-payment-reminder__later {
  border: 1px solid rgba(203, 213, 225, 0.92);
  background: #fff;
  color: #475569;
}

.student-payment-reminder__schedule {
  border: 1px solid rgba(225, 29, 72, 0.55);
  background: linear-gradient(135deg, #f43f5e, #e11d48 58%, #8b5cf6);
  color: #fff;
  box-shadow: 0 12px 24px rgba(225, 29, 72, 0.22);
}

.student-payment-reminder__later:hover,
.student-payment-reminder__schedule:hover {
  transform: translateY(-1px);
}

.student-payment-reminder__later:hover {
  border-color: rgba(251, 113, 133, 0.58);
  color: #be123c;
}

.student-payment-reminder__schedule:hover {
  box-shadow: 0 16px 30px rgba(225, 29, 72, 0.28);
}

@media (max-width: 520px) {
  .student-payment-reminder {
    align-items: flex-end;
    padding: 10px 10px max(10px, env(safe-area-inset-bottom));
  }

  .student-payment-reminder__dialog {
    max-height: calc(100dvh - 20px);
    padding: 18px 14px 14px;
    border-radius: 24px;
  }

  .student-payment-reminder__header {
    grid-template-columns: 44px minmax(0, 1fr);
    gap: 11px;
    padding-right: 32px;
  }

  .student-payment-reminder__icon {
    width: 44px;
    height: 44px;
    border-radius: 14px;
  }

  .student-payment-reminder__header h2 {
    font-size: 19px;
  }

  .student-payment-reminder__item {
    grid-template-columns: 36px minmax(0, 1fr);
  }

  .student-payment-reminder__item-date {
    width: 36px;
    height: 36px;
  }

  .student-payment-reminder__elapsed {
    width: fit-content;
    grid-column: 2;
  }

  .student-payment-reminder__actions {
    grid-template-columns: 1fr;
  }
}

html[data-theme='dark'] .student-payment-reminder {
  background: rgba(2, 6, 23, 0.78);
}

html[data-theme='dark'] .student-payment-reminder__dialog {
  border-color: #8f3157;
