  0%, 100% {
    border-color: rgba(51, 65, 85, 0.68);
    box-shadow: 0 14px 38px rgba(0, 0, 0, 0.48);
  }
  50% {
    border-color: rgba(34, 211, 238, 0.3);
    box-shadow: 0 14px 38px rgba(0, 0, 0, 0.54), 0 0 0 4px rgba(34, 211, 238, 0.04);
  }
