@keyframes pythonVideoTouchFeedbackRipple {
  0% {
    opacity: 0;
    transform: scale(0.62);
  }
  22% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: scale(1.12);
  }
}

@keyframes pythonVideoTouchFeedbackLeft {
  from {
    opacity: 0;
